// C. BA-String

function solve(): void {
    const input = require('fs').readFileSync(0, 'utf8').trim().split('\n');
    let line = 0;

    const [n, k, x] = input[line++].split(' ').map(Number);
    const s = input[line++];

    if (!s.includes('*')) {
        console.log(s);
        return;
    }

    const stars = s.split('a').filter(Boolean);

    // A string of q stars can expand to 0, 1, 2, ..., q * k b's, which is
    // 1 + k * q possibilities
    const expand = stars.map(star => 1 + k * star.length);

    // Cumulative product of number of stars
    const prods: number[] = [expand[expand.length - 1]];
    for (let i = 1; i < stars.length; i++) {
        prods.push(prods[i - 1] * expand[stars.length - i - 1]);
    }

    let remainingX = x - 1;

    // Count how many b's to replace each * by
    const counts: number[] = [];
    for (let prod of [...prods].reverse()) {
        counts.push(Math.floor(remainingX / prod));
        remainingX -= prod * Math.floor(remainingX / prod);
    }
    counts.push(remainingX % prods[0]);

    // Construct the string
    let answer = "";
    let i = 1;
    let j = 0;
    while (j < s.length) {
        if (s[j] === 'a') {
            answer += 'a';
            j++;
        } else {
            answer += 'b'.repeat(counts[i]);
            i++;
            while (j < s.length && s[j] === '*') {
                j++;
            }
        }
    }

    console.log(answer);
}

