import * as readline from 'readline';

function process(A: number[], B: number[], Q: [number, number][]): number[] {
    const S: number[] = [0];
    const n = A.length;
    for (let i = 0; i < n; i++) {
        const ai = A[i];
        const bi = B[i];
        const di = bi - ai;
        S.push(S[S.length - 1] + di);
    }
    let p = Math.log2(S.length);
    p = Math.ceil(p);
    p = 2 ** p;
    const min_tree: (number | null)[] = new Array(2 * p - 1).fill(null);
    const max_tree: (number | null)[] = new Array(2 * p - 1).fill(null);
    for (let i = 0; i < p; i++) {
        if (i < S.length) {
            min_tree[i] = S[i];
            max_tree[i] = S[i];
        } else {
            min_tree[i] = Infinity;
            max_tree[i] = -Infinity;
        }
    }
    for (let i = p; i < 2 * p - 1; i++) {
        const i1 = (2 * p - 2) - i;
        const j1 = 2 * i1 + 1;
        const j2 = 2 * i1 + 2;
        const i_left = (2 * p - 2) - j1;
        const i_right = (2 * p - 2) - j2;
        min_tree[i] = Math.min(min_tree[i_left]!, min_tree[i_right]!);
        max_tree[i] = Math.max(max_tree[i_left]!, max_tree[i_right]!);
    }

    function find_max(l: number, r: number, start_l = 0, start_r = p - 1, start_i = 2 * p - 2): number | null {
        if (start_i < 0) return null;
        if (l === r) return max_tree[l];
        if (l === start_l && r === start_r) return max_tree[start_i];
        const i1 = (2 * p - 2) - start_i;
        const i_l = (2 * p - 2) - (2 * i1 + 2);
        const i_r = (2 * p - 2) - (2 * i1 + 1);
        const m1 = Math.floor((start_l + start_r) / 2);
        if (l > m1) {
            return find_max(l, r, m1 + 1, start_r, i_r);
        } else if (r <= m1) {
            return find_max(l, r, start_l, m1, i_l);
        } else {
            const max1 = find_max(l, m1, start_l, m1, i_l);
            const max2 = find_max(m1 + 1, r, m1 + 1, start_r, i_r);
            return Math.max(max1!, max2!);
        }
    }

    function find_min(l: number, r: number, start_l = 0, start_r = p - 1, start_i = 2 * p - 2): number | null {
        if (start_i < 0) return null;
        if (l === r) return min_tree[l];
        if (l === start_l && r === start_r) return min_tree[start_i];
        const i1 = (2 * p - 2) - start_i;
        const i_l = (2 * p - 2) - (2 * i1 + 2);
        const i_r = (2 * p - 2) - (2 * i1 + 1);
        const m1 = Math.floor((start_l + start_r) / 2);
        if (l > m1) {
            return find_min(l, r, m1 + 1, start_r, i_r);
        } else if (r <= m1) {
            return find_min(l, r, start_l, m1, i_l);
        } else {
            const min1 = find_min(l, m1, start_l, m1, i_l);
            const min2 = find_min(m1 + 1, r, m1 + 1, start_r, i_r);
            return Math.min(min1!, min2!);
        }
    }

    const answer: number[] = [];
    for (const [l, r] of Q) {
        const s1 = S[l - 1];
        const s2 = S[r];
        if (s1 !== s2) {
            answer.push(-1);
        } else {
            const my_min = find_min(l, r)!;
            const my_max = find_max(l, r)!;
            if (my_min - s1 < 0) {
                answer.push(-1);
            } else {
                answer.push(my_max - s1);
            }
        }
    }
    return answer;
}

