import * as readline from 'readline';

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

function main() {
    let inputLines: string[] = [];
    rl.on('line', (line) => {
        inputLines.push(line);
    }).on('close', () => {
        const t = parseInt(inputLines[0]);
        for (let _ = 0; _ < t; _++) {
            inputLines.shift();
            const [n, m] = inputLines.shift()!.split(' ').map(Number);
            const d: number[][] = [];
            for (let i = 0; i < n; i++) {
                const line = inputLines.shift()!;
                d.push(line.split('').map(j => j === 'R' ? -1 : j === 'U' ? -2 : j === 'L' ? -3 : -4));
            }

            let r = 0;
            let pos: [number, number] = [0, 0];

            for (let i = 0; i < n; i++) {
                for (let j = 0; j < m; j++) {
                    let a = i, b = j, p = d[i][j], c = 0;
                    const st: [number, number][] = [];

                    while (p < 0) {
                        d[a][b] = 0;
                        st.push([a, b]);
                        if (p === -1) b++;
                        else if (p === -2) a--;
                        else if (p === -3) b--;
                        else a++;
                        c++;
                        if (0 <= a && a < n && 0 <= b && b < m) {
                            p = d[a][b];
                        } else {
                            for (let ii = 0; ii < st.length; ii++) {
                                const [x, y] = st[ii];
                                d[x][y] = c - ii;
                            }
                            p = -1;
                            break;
                        }
                    }

                    if (p === 0) {
                        let jj = 0, flag = 0;
                        for (let ii = 0; ii < st.length; ii++) {
                            const [x, y] = st[ii];
                            d[x][y] = flag ? c - jj : c - ii;
                            if (x === a && y === b) {
                                flag = 1;
                                jj = ii;
                            }
                        }
                    }

                    if (p > 0) {
                        for (let ii = 0; ii < st.length; ii++) {
                            const [x, y] = st[ii];
                            d[x][y] = p + c - ii;
                        }
                    }

                    if (d[i][j] > r) {
                        r = d[i][j];
                        pos = [i, j];
                    }
                }
            }

            console.log(`${pos[0] + 1} ${pos[1] + 1} ${r}`);
        }
    });
}

