const BUFSIZE = 8192;

class FastIO {
    private _fd: number;
    private buffer: Uint8Array;
    private writable: boolean;
    private pos: number = 0;
    private length: number = 0;

    constructor(file: any) {
        this._fd = file.fileno();
        this.buffer = new Uint8Array(BUFSIZE);
        this.writable = "x" in file.mode || "r" not in file.mode;
    }

    async read(): Promise<string> {
        let data = "";
        while (true) {
            const bytesRead = await Deno.read(this._fd, this.buffer);
            if (bytesRead === null) break;
            this.length = bytesRead;
            this.pos = 0;
            data += new TextDecoder().decode(this.buffer.subarray(0, this.length));
        }
        return data;
    }

    async readline(): Promise<string> {
        let line = "";
        while (true) {
            if (this.pos >= this.length) {
                const bytesRead = await Deno.read(this._fd, this.buffer);
                if (bytesRead === null) break;
                this.length = bytesRead;
                this.pos = 0;
            }
            while (this.pos < this.length) {
                if (this.buffer[this.pos] === 10) { // newline character
                    line += new TextDecoder().decode(this.buffer.subarray(0, this.pos));
                    this.pos++;
                    return line + "\n";
                }
                this.pos++;
            }
        }
        return line;
    }

    write(data: string): void {
        if (this.writable) {
            Deno.writeSync(this._fd, new TextEncoder().encode(data));
        }
    }
}

