const BUFSIZE = 8192;

class FastIO {
    private _fd: number;
    private buffer: Uint8Array;
    private writable: boolean;
    private pos: number = 0;
    private readPos: number = 0;

    constructor(file: any) {
        this._fd = file.fd;
        this.buffer = new Uint8Array(BUFSIZE);
        this.writable = "x" in file.flags || !file.flags.includes("r");
    }

    async read(): Promise<void> {
        let bytesRead = 0;
        do {
            bytesRead = await Deno.read(this._fd, this.buffer);
            if (bytesRead === null) break;
            this.pos += bytesRead;
        } while (bytesRead > 0);
    }

    async readline(): Promise<string> {
        if (this.readPos >= this.pos) {
            await this.read();
        }
        let newlineIndex = this.buffer.indexOf(10, this.readPos);
        while (newlineIndex === -1 && this.pos < this.buffer.length) {
            this.readPos = this.pos;
            await this.read();
            newlineIndex = this.buffer.indexOf(10, this.readPos);
        }
        if (newlineIndex === -1) {
            return new TextDecoder().decode(this.buffer.subarray(this.readPos, this.pos));
        } else {
            const line = new TextDecoder().decode(this.buffer.subarray(this.readPos, newlineIndex));
            this.readPos = newlineIndex + 1;
            return line;
        }
    }

    write(data: string): void {
        if (this.writable) {
            Deno.writeSync(this._fd, new TextEncoder().encode(data));
        }
    }

    flush(): void {
        // No-op for simplicity
    }
}

