func (fio *FastIO) ReadLine() (string, error) {
	var line []byte
	for {
		b, err := fio.reader.ReadByte()
		if err != nil {
			return "", err
		}
		if b == '\n' {
			break
		}
		line = append(line, b)
	}
	return string(line), nil
