			ans[i] = s[len(s)-1]
		}
		s = append(s, i)
	}
	if f {
		for i := 0; i < n; i++ {
			if ans[i] != -1 {
				ans[i] = n - 1 - ans[i]
			}
		}
	}
	return ans
}

func dfs(i int, adj [][]int, p int, ans int) int {
	f := true
	a1 := 0
	for _, j := range adj[i] {
		if j != p {
			a1 += dfs(j, adj, i, ans+1)
			f = false
		}
	}
	if f {
		a1 += (ans * (ans - 1)) / 2
	}
	return a1
}

