func runCase(reader *bufio.Reader) {
	n, _ := strconv.Atoi(readLine(reader))
	alst := make([]int, n)
	pos := make([]int, n)
	for i := range pos {
		pos[i] = -1
	}

	input := strings.Fields(readLine(reader))
	for i := 0; i < n; i++ {
		a, _ := strconv.Atoi(input[i])
		a--
		alst[i] = a
		if (a-i)%2 == 1 {
			fmt.Println(-1)
			return
		}
		pos[a] = i
	}

	ans := []int{}
	for i := n - 1; i > 0; i -= 2 {
		p := pos[i]
		ans = append(ans, p+1)
		for j := 0; j < p/2; j++ {
			swap(alst, pos, j, p-j)
		}
		if i-1 >= 0 {
			p = pos[i-1]
			ans = append(ans, p)
			p--
			for j := 0; j < p/2; j++ {
				swap(alst, pos, j, p-j)
			}
		}
		ans = append(ans, i+3)
		p = i + 2
		if p < n {
			for j := 0; j < p/2; j++ {
				swap(alst, pos, j, p-j)
			}
		}
		p = 2
		ans = append(ans, 3)
		for j := 0; j < p/2; j++ {
			swap(alst, pos, j, p-j)
		}
		p = i
		ans = append(ans, p+1)
		for j := 0; j < p/2; j++ {
			swap(alst, pos, j, p-j)
		}
	}

	fmt.Println(len(ans))
	for _, v := range ans {
		fmt.Print(v, " ")
	}
	fmt.Println()
}

func swap(alst []int, pos []int, i, j int) {
	alst[i], alst[j] = alst[j], alst[i]
	pos[alst[i]], pos[alst[j]] = pos[alst[j]], pos[alst[i]]
}

