const BUFSIZE = 8192

type FastIO struct {
	reader *bufio.Reader
	writer *bufio.Writer
}

func NewFastIO(rw *os.File) *FastIO {
	return &FastIO{
		reader: bufio.NewReaderSize(rw, BUFSIZE),
		writer: bufio.NewWriterSize(rw, BUFSIZE),
	}
}

func (fio *FastIO) ReadLine() (string, error) {
	var line []byte
	for {
		b, err := fio.reader.ReadByte()
		if err != nil {
			return "", err
		}
		line = append(line, b)
		if b == '\n' {
			break
		}
	}
	return strings.TrimSpace(string(line)), nil
}

func (fio *FastIO) ReadInt() (int, error) {
	str, err := fio.ReadLine()
	if err != nil {
		return 0, err
	}
	return strconv.Atoi(str)
}

func (fio *FastIO) ReadInts() ([]int, error) {
	str, err := fio.ReadLine()
	if err != nil {
		return nil, err
	}
	parts := strings.Fields(str)
	ints := make([]int, len(parts))
	for i, part := range parts {
		ints[i], _ = strconv.Atoi(part)
	}
	return ints, nil
}

func (fio *FastIO) WriteString(s string) error {
	_, err := fio.writer.WriteString(s)
	return err
}

func (fio *FastIO) Flush() error {
	return fio.writer.Flush()
}

func main() {
	fio := NewFastIO(os.Stdin)
	defer fio.Flush()

	t, _ := fio.ReadInt()
	for i := 0; i < t; i++ {
		n, _ := fio.ReadInt()
		if n%2 == 0 {
			fmt.Fprintln(fio.writer, "YES")
			continue
		}
		l, _ := fio.ReadInts()
		flag := false
		for j := 0; j < n-1; j++ {
			if l[j] >= l[j+1] {
				flag = true
				break
			}
		}
		if flag {
			fmt.Fprintln(fio.writer, "YES")
		} else {
			fmt.Fprintln(fio.writer, "NO")
		}
	}
}

