func solve() {
	reader := bufio.NewReader(os.Stdin)
	input, _ := reader.ReadString('\n')
	parts := strings.Fields(input)
	n, _ := strconv.Atoi(parts[0])
	k, _ := strconv.Atoi(parts[1])
	x, _ := strconv.Atoi(parts[2])
	s, _ := reader.ReadString('\n')

	if !strings.Contains(s, "*") {
		fmt.Print(s)
		return
	}

	stars := strings.Split(strings.TrimSuffix(s, "\n"), "a")
	var expand []int
	for _, star := range stars {
		if star != "" {
			expand = append(expand, 1+k*len(star))
		}
	}

	if len(expand) == 0 {
		fmt.Print(s)
		return
	}

	prods := make([]int, len(expand))
	prods[len(expand)-1] = expand[len(expand)-1]
	for i := len(expand) - 2; i >= 0; i-- {
		prods[i] = prods[i+1] * expand[i]
	}

	x--
	var counts []int
	for _, prod := range prods {
		counts = append(counts, x/prod)
		x -= prod * (x / prod)
	}
	counts = append(counts, x%prods[0])

	answer := ""
	i := 1
	j := 0
	for j < len(s) {
		if s[j] == 'a' {
			answer += "a"
			j++
		} else {
			answer += strings.Repeat("b", counts[i])
			i++
			for j < len(s) && s[j] == '*' {
				j++
			}
		}
	}

	fmt.Print(answer)
}

