	"math"
	"os"
)

func process(A []int, B []int, Q [][]int) []int {
	S := []int{0}
	n := len(A)
	for i := 0; i < n; i++ {
		di := B[i] - A[i]
		S = append(S, S[len(S)-1]+di)
	}
	n = len(S)
	p := math.Ceil(math.Log(float64(n)) / math.Log(2))
	minTree := make([]int, int(2*p-1))
	maxTree := make([]int, int(2*p-1))
	for i := 0; i < int(p); i++ {
		if i < n {
			minTree[i] = S[i]
			maxTree[i] = S[i]
		} else {
			minTree[i] = int(^uint(0) >> 1) // max int
			maxTree[i] = -int(^uint(0) >> 1) - 1 // min int
		}
	}
	for i := int(p); i < int(2*p-1); i++ {
		i1 := (2*int(p) - 2) - i
		j1 := 2*i1 + 1
		j2 := 2*i1 + 2
		iLeft := (2*int(p) - 2) - j1
		iRight := (2*int(p) - 2) - j2
		minTree[i] = min(minTree[iLeft], minTree[iRight])
		maxTree[i] = max(maxTree[iLeft], maxTree[iRight])
	}

	var findMax func(l, r, startL, startR, startIndex int) int
	findMax = func(l, r, startL, startR, startIndex int) int {
		if startIndex < 0 {
			return -1
		}
		if l == r {
			return maxTree[l]
		}
		if l == startL && r == startR {
			return maxTree[startIndex]
		}
		i1 := (2*int(p) - 2) - startIndex
		iLeft := (2*int(p) - 2) - (2*i1 + 2)
		iRight := (2*int(p) - 2) - (2*i1 + 1)
		m1 := (startL + startR) / 2
		if l > m1 {
			return findMax(l, r, m1+1, startR, iRight)
		} else if r <= m1 {
			return findMax(l, r, startL, m1, iLeft)
		} else {
			max1 := findMax(l, m1, startL, m1, iLeft)
			max2 := findMax(m1+1, r, m1+1, startR, iRight)
			return max(max1, max2)
		}
	}

	var findMin func(l, r, startL, startR, startIndex int) int
	findMin = func(l, r, startL, startR, startIndex int) int {
		if startIndex < 0 {
			return -1
		}
		if l == r {
			return minTree[l]
		}
		if l == startL && r == startR {
			return minTree[startIndex]
		}
		i1 := (2*int(p) - 2) - startIndex
		iLeft := (2*int(p) - 2) - (2*i1 + 2)
		iRight := (2*int(p) - 2) - (2*i1 + 1)
		m1 := (startL + startR) / 2
		if l > m1 {
			return findMin(l, r, m1+1, startR, iRight)
		} else if r <= m1 {
			return findMin(l, r, startL, m1, iLeft)
		} else {
			min1 := findMin(l, m1, startL, m1, iLeft)
			min2 := findMin(m1+1, r, m1+1, startR, iRight)
			return min(min1, min2)
		}
	}

	answer := []int{}
	for _, qr := range Q {
		l, r := qr[0], qr[1]
		s1 := S[l-1]
		s2 := S[r]
		if s1 != s2 {
			answer = append(answer, -1)
		} else {
			myMin := findMin(l, r, 0, int(p)-1, 2*int(p)-2)
			myMax := findMax(l, r, 0, int(p)-1, 2*int(p)-2)
			if myMin-s1 < 0 {
				answer = append(answer, -1)
			} else {
				answer = append(answer, myMax-s1)
			}
		}
	}
	return answer
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

