		fmt.Sscanf(scanner.Text(), "%d", &A[i])
	}

	B := make([]int, n)
	for i := range B {
		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%d", &B[i])
	}

	Q := make([][]int, k)
	for i := 0; i < k; i++ {
