			if d1.union(i, j) == -1 {
				d1.parent[y] = y1
			} else if d2.union(i, j) == -1 {
				d2.parent[x] = x1
				d1.parent[y] = y1
			} else {
				d1.union(i, j)
				d2.union(i, j)
				v = append(v, []int{i, j})
			}
		}
	}

	fmt.Println(len(v))
	for _, pair := range v {
		fmt.Println(pair[0], pair[1])
