    private static void processTestCase(Scanner scanner) {
        int n = Integer.parseInt(scanner.nextLine());
        int[] alst = new int[n];
        String[] input = scanner.nextLine().split(" ");
        for (int j = 0; j < n; j++) {
            int a = Integer.parseInt(input[j]) - 1;
            alst[j] = a;
            if ((a - j) % 2 == 1) {
                System.out.println(-1);
                return;
            }
        }

        int[] pos = new int[n];
        for (int i = 0; i < n; i++) {
            pos[alst[i]] = i;
        }

        List<Integer> ans = new ArrayList<>();
        for (int i = n - 1; i > 0; i -= 2) {
            int p = pos[i];
            ans.add(p + 1);
            reverseAndSwap(alst, pos, p / 2);
            p = pos[i - 1];
            ans.add(p);
            p--;
            reverseAndSwap(alst, pos, p / 2);
            ans.add(p + 3);
            p += 2;
            reverseAndSwap(alst, pos, p / 2);
            p = 2;
            ans.add(3);
            reverseAndSwap(alst, pos, p / 2);
            p = i;
            ans.add(p + 1);
            reverseAndSwap(alst, pos, p / 2);
        }

        System.out.println(ans.size());
        for (int num : ans) {
            System.out.print(num + " ");
        }
        System.out.println();
    }

    private static void reverseAndSwap(int[] alst, int[] pos, int half) {
        for (int j = 0; j < half; j++) {
            int temp = alst[j];
            alst[j] = alst[pos[j]];
            alst[pos[j]] = temp;

            int tempPos = pos[temp];
            pos[temp] = pos[alst[j]];
            pos[alst[j]] = tempPos;
        }
    }
}

