import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = Integer.parseInt(scanner.nextLine());
        for (int i = 0; i < t; i++) {
            solve(scanner);
        }
        scanner.close();
    }

    private static void solve(Scanner scanner) {
        String[] input = scanner.nextLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int k = Integer.parseInt(input[1]);
        long x = Long.parseLong(input[2]);
        String s = scanner.nextLine();

        if (!s.contains("*")) {
            System.out.println(s);
            return;
        }

        String[] stars = s.split("a");
        List<String> starList = new ArrayList<>();
        for (String star : stars) {
            if (!star.isEmpty()) {
                starList.add(star);
            }
        }

        List<Integer> expand = new ArrayList<>();
        for (String star : starList) {
            expand.add(1 + k * star.length());
        }

        List<Long> prods = new ArrayList<>();
        prods.add((long) expand.get(expand.size() - 1));
        for (int i = 1; i < starList.size(); i++) {
            prods.add(prods.get(i - 1) * expand.get(starList.size() - i - 1));
        }

        x--;

        List<Long> counts = new ArrayList<>();
        for (int i = prods.size() - 1; i >= 0; i--) {
            long prod = prods.get(i);
            counts.add(x / prod);
            x -= prod * (x / prod);
        }
        counts.add(x % prods.get(0));

        StringBuilder answer = new StringBuilder();
        int i = 0;
        int j = 0;
        while (j < s.length()) {
            if (s.charAt(j) == 'a') {
                answer.append('a');
                j++;
            } else {
                for (int b = 0; b < counts.get(i); b++) {
                    answer.append('b');
                }
                i++;
                while (j < s.length() && s.charAt(j) == '*') {
                    j++;
                }
            }
        }

        System.out.println(answer.toString());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] input = reader.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int k = Integer.parseInt(input[1]);

        input = reader.readLine().split(" ");
        int[] A = new int[n];
        for (int i = 0; i < n; i++) {
            A[i] = Integer.parseInt(input[i]);
        }

        input = reader.readLine().split(" ");
        int[] B = new int[n];
        for (int i = 0; i < n; i++) {
            B[i] = Integer.parseInt(input[i]);
        }

        List<int[]> Q = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            input = reader.readLine().split(" ");
            int l = Integer.parseInt(input[0]);
            int r = Integer.parseInt(input[1]);
            Q.add(new int[]{l, r});
        }

        List<Integer> answer = process(A, B, Q);
        for (int x : answer) {
            System.out.println(x);
        }
    }

    public static List<Integer> process(int[] A, int[] B, List<int[]> Q) {
        List<Integer> S = new ArrayList<>();
        S.add(0);
        int n = A.length;
        for (int i = 0; i < n; i++) {
            int ai = A[i];
            int bi = B[i];
            int di = bi - ai;
            S.add(S.get(S.size() - 1) + di);
        }
        n = S.size();
        int p = (int) Math.ceil(Math.log(n) / Math.log(2));
        p = (int) Math.pow(2, p);

        int[] minTree = new int[2 * p - 1];
        int[] maxTree = new int[2 * p - 1];

        Arrays.fill(minTree, Integer.MAX_VALUE);
        Arrays.fill(maxTree, Integer.MIN_VALUE);

        for (int i = 0; i < p; i++) {
            if (i < n) {
                minTree[i] = S.get(i);
                maxTree[i] = S.get(i);
            }
        }

        for (int i = p; i < 2 * p - 1; i++) {
            int i1 = (2 * p - 2) - i;
            int j1 = 2 * i1 + 1;
            int j2 = 2 * i1 + 2;
            int iLeft = (2 * p - 2) - j1;
            int iRight = (2 * p - 2) - j2;
            minTree[i] = Math.min(minTree[iLeft], minTree[iRight]);
            maxTree[i] = Math.max(maxTree[iLeft], maxTree[iRight]);
        }

        List<Integer> answer = new ArrayList<>();
        for (int[] query : Q) {
            int l = query[0];
            int r = query[1];
            int s1 = S.get(l - 1);
            int s2 = S.get(r);
            if (s1 != s2) {
                answer.add(-1);
            } else {
                int myMin = findMin(l, r, 0, p - 1, 2 * p - 2, minTree);
                int myMax = findMax(l, r, 0, p - 1, 2 * p - 2, maxTree);
                if (myMin - s1 < 0) {
                    answer.add(-1);
                } else {
                    answer.add(myMax - s1);
                }
            }
        }
        return answer;
    }

    private static int findMin(int l, int r, int startL, int startR, int startIndex, int[] tree) {
        if (startIndex < 0) {
            return Integer.MAX_VALUE;
        }
        if (l == r) {
            return tree[l];
        }
        if (l == startL && r == startR) {
            return tree[startIndex];
        }
        int i1 = (2 * tree.length - 2) - startIndex;
        int iLeft = (2 * tree.length - 2) - (2 * i1 + 2);
        int iRight = (2 * tree.length - 2) - (2 * i1 + 1);
        int m1 = (startL + startR) / 2;
        if (l > m1) {
            return findMin(l, r, m1 + 1, startR, iRight, tree);
        } else if (r <= m1) {
            return findMin(l, r, startL, m1, iLeft, tree);
        } else {
            int min1 = findMin(l, m1, startL, m1, iLeft, tree);
            int min2 = findMin(m1 + 1, r, m1 + 1, startR, iRight, tree);
            return Math.min(min1, min2);
        }
    }

    private static int findMax(int l, int r, int startL, int startR, int startIndex, int[] tree) {
        if (startIndex < 0) {
            return Integer.MIN_VALUE;
        }
        if (l == r) {
            return tree[l];
        }
        if (l == startL && r == startR) {
            return tree[startIndex];
        }
        int i1 = (2 * tree.length - 2) - startIndex;
        int iLeft = (2 * tree.length - 2) - (2 * i1 + 2);
        int iRight = (2 * tree.length - 2) - (2 * i1 + 1);
        int m1 = (startL + startR) / 2;
        if (l > m1) {
            return findMax(l, r, m1 + 1, startR, iRight, tree);
        } else if (r <= m1) {
            return findMax(l, r, startL, m1, iLeft, tree);
        } else {
            int max1 = findMax(l, m1, startL, m1, iLeft, tree);
            int max2 = findMax(m1 + 1, r, m1 + 1, startR, iRight, tree);
            return Math.max(max1, max2);
        }
    }
}

