import java.util.Scanner;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) {
        solve();
    }

    private static void solve() {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        boolean wbPoss = n > 1;
        boolean bwPoss = n > 1;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        boolean anyBadPoss = n > 1;

        for (int i = 0; i < n; i++) {
            String s = scanner.next().trim();
            if (s.charAt(0) == 'B') {
                b++;
                wbPoss = false;
            } else if (s.charAt(0) == 'W') {
                w++;
                bwPoss = false;
            } else if (s.charAt(0) == '?') {
                q++;
            }
            if (s.charAt(1) == 'B') {
                b++;
                bwPoss = false;
            } else if (s.charAt(1) == 'W') {
                w++;
                bwPoss = false;
            } else if (s.charAt(1) == '?') {
                q++;
            }
            if (s.equals("??")) {
                free++;
            } else if (s.charAt(0) == s.charAt(1)) {
                anyBadPoss = false;
            }
        }

        int wNeeded = n - w;
        if (wNeeded > q || wNeeded < 0) {
            System.out.println(0);
            return;
        }

        long numBadPoss;
        if (anyBadPoss) {
            numBadPoss = powerOfTwoMod(free, MOD);
            numBadPoss -= (bwPoss ? 1 : 0) + (wbPoss ? 1 : 0);
            if (numBadPoss < 0) numBadPoss += MOD;
        } else {
            numBadPoss = 0;
        }

        System.out.println((modularSubtract(choose(q, wNeeded, MOD), numBadPoss, MOD)));
    }

    private static long egcd(long a, long b, long[] result) {
        if (a == 0) {
            result[0] = b;
            result[1] = 0;
            result[2] = 1;
            return b;
        } else {
            long[] tempResult = new long[3];
            long gcd = egcd(b % a, a, tempResult);
            result[0] = gcd;
            result[1] = tempResult[2] - (b / a) * tempResult[1];
            result[2] = tempResult[1];
            return gcd;
        }
    }

    private static long modinv(long a, long m) {
        long[] result = new long[3];
        egcd(a, m, result);
        if (result[0] != 1) {
            throw new IllegalArgumentException("modular inverse does not exist");
        } else {
            return (result[1] % m + m) % m;
        }
    }

    private static long choose(int n, int k, int p) {
        if (k == 0) {
            return 1;
        }
        long x = n;
        for (int y = n - 1; y > n - k; y--) {
            x = (x * y) % p;
        }
        long d = 1;
        for (int i = 2; i <= k; i++) {
            d = (d * i) % p;
        }
        return (x * modinv(d, p)) % p;
    }

    private static long powerOfTwoMod(int exp, int mod) {
        long result = 1;
        long base = 2;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    private static long modularSubtract(long a, long b, int mod) {
        return ((a - b) % mod + mod) % mod;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int BUFSIZE = 8192;

    public static void main(String[] args) throws IOException {
        FastIO io = new FastIO(System.in, System.out);
        int t = inp(io);
        while (t-- > 0) {
            int n = inp(io);
            List<Integer> l = inlt(io);
            if (!l.isEmpty()) {
                int s = l.get(0);
                for (int i = 1; i < n; i++) {
                    s &= l.get(i);
                }
                io.println(s);
            } else {
                io.println(0); // Handle empty list case
            }
        }
        io.close();
    }

    private static class FastIO extends PrintWriter {
        private InputStream in;
        private byte[] buffer;
        private int bufferSize, bufferPointer;

        public FastIO(InputStream in, OutputStream out) {
            super(out);
            this.in = in;
            this.bufferSize = BUFSIZE;
            this.buffer = new byte[bufferSize];
            this.bufferPointer = bufferSize;
        }

        private int read() throws IOException {
            if (bufferPointer == bufferSize) {
                bufferPointer = 0;
                bufferSize = in.read(buffer);
            }
            if (bufferSize == -1) return -1;
            return buffer[bufferPointer++];
        }

        public String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
            }
            return sb.toString();
        }

        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c));
            if (c == -1) return null;
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        public int nextInt() throws IOException {
            int sign = 1;
            int num = 0;
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c));
            if (c == '-') {
                sign = -1;
                c = read();
            }
            while (c != -1 && !Character.isWhitespace(c)) {
                if (c < '0' || c > '9') throw new NumberFormatException();
                num = num * 10 + (c - '0');
                c = read();
            }
            return sign * num;
        }

        public List<Integer> nextIntList() throws IOException {
            List<Integer> list = new ArrayList<>();
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c));
            while (c != -1) {
                if (!Character.isWhitespace(c)) {
                    int num = 0;
                    int sign = 1;
                    if (c == '-') {
                        sign = -1;
                        c = read();
                    }
                    while (c != -1 && !Character.isWhitespace(c)) {
                        if (c < '0' || c > '9') throw new NumberFormatException();
                        num = num * 10 + (c - '0');
                        c = read();
                    }
                    list.add(sign * num);
                }
                while ((c = read()) != -1 && Character.isWhitespace(c));
            }
            return list;
        }
    }

    private static int inp(FastIO io) throws IOException {
        return io.nextInt();
    }

    private static String inps(FastIO io) throws IOException {
        return io.next();
    }

    private static List<Integer> inlt(FastIO io) throws IOException {
        return io.nextIntList();
    }
}

