            int k = Integer.parseInt(input[2]);

            int bigTablesStartingNum = 0;
            int bigTablesCount = n % m;
            int bigTablesSize = 1 + n / m;

            int smallTablesCount = m - n % m;
            int smallTablesSize = n / m;
            int peopleAtBigTables = bigTablesSize * bigTablesCount;

            int[] bigTableNums = new int[bigTablesSize];
            int[] smallTableNums = new int[smallTablesSize];

            for (int iteration = 0; iteration < k; iteration++) {
                int i = 0;
                for (int bt = 0; bt < bigTablesCount; bt++) {
                    for (int x = 0; x < bigTablesSize; x++) {
                        bigTableNums[x] = (bigTablesStartingNum + i) % n + 1;
                        i++;
                    }
                    printTable(bigTableNums);
                }
