class Program
{
    const int BUFSIZE = 8192;

    static void Main(string[] args)
    {
        FastIO io = new FastIO(Console.OpenStandardInput(), Console.OpenStandardOutput());
        int t = int.Parse(io.ReadLine());
        for (int i = 0; i < t; i++)
        {
            var parts = io.ReadLine().Split(' ');
            int n = int.Parse(parts[0]);
            int s = int.Parse(parts[1]);
            io.WriteLine(s / ((n + 2) / 2));
        }
    }

    static List<int> NextLargerElement(int[] arr, int n, bool f)
    {
        Stack<int> s = new Stack<int>();
        List<int> ans = new List<int>(new int[n]);
        for (int i = 0; i < n; i++)
        {
            while (s.Count > 0 && arr[s.Peek()] < arr[i])
            {
                s.Pop();
            }
            if (s.Count > 0)
            {
                ans[i] = s.Peek();
            }
            s.Push(i);
        }
        if (f)
        {
            for (int i = 0; i < n; i++)
            {
                if (ans[i] != -1)
                {
                    ans[i] = n - 1 - ans[i];
                }
            }
        }
        return ans;
    }

    static int Dfs(int i, List<List<int>> adj, int p, int ans)
    {
        bool f = true;
        int a1 = 0;
        foreach (int j in adj[i])
        {
            if (j != p)
            {
                a1 += Dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f)
        {
            a1 += ans * (ans - 1) / 2;
        }
        return a1;
    }

    class FastIO : IDisposable
    {
        private readonly Stream _stream;
        private readonly byte[] _buffer;
        private int _bufferIndex;
        private int _bufferLength;

        public FastIO(Stream stream)
        {
            _stream = stream;
            _buffer = new byte[BUFSIZE];
            _bufferIndex = 0;
            _bufferLength = 0;
        }

        public string ReadLine()
        {
            List<byte> line = new List<byte>();
            while (true)
            {
                if (_bufferIndex >= _bufferLength)
                {
                    _bufferLength = _stream.Read(_buffer, 0, BUFSIZE);
                    _bufferIndex = 0;
                    if (_bufferLength == 0)
                    {
                        break;
                    }
                }
                while (_bufferIndex < _bufferLength && _buffer[_bufferIndex] != '\n')
                {
                    line.Add(_buffer[_bufferIndex++]);
                }
                if (_bufferIndex < _bufferLength || _stream.CanRead)
                {
                    break;
                }
            }
            return System.Text.Encoding.ASCII.GetString(line.ToArray());
        }

        public void WriteLine(int value)
        {
            byte[] data = System.Text.Encoding.ASCII.GetBytes(value.ToString() + "\n");
            _stream.Write(data, 0, data.Length);
        }

        public void Dispose()
        {
            _stream.Dispose();
        }
    }
}

