class Program
{
    static void Main()
    {
        int t = int.Parse(Console.ReadLine());
        for (int i = 0; i < t; i++)
        {
            MainFunction();
        }
    }

    static void MainFunction()
    {
        int n = int.Parse(Console.ReadLine());
        string[] input = Console.ReadLine().Split(' ');
        List<int> alst = new List<int>();
        foreach (var item in input)
        {
            alst.Add(int.Parse(item) - 1);
        }
        int[] pos = new int[n];
        for (int i = 0; i < n; i++)
        {
            pos[i] = -1;
        }
        for (int i = 0; i < n; i++)
        {
            int a = alst[i];
            if ((a - i) % 2 == 1)
            {
                Console.WriteLine(-1);
                return;
            }
            pos[a] = i;
        }
        List<int> ans = new List<int>();
        for (int i = n - 1; i > 0; i -= 2)
        {
            int p = pos[i];
            if (p >= 0)
            {
                ans.Add(p + 1);
                for (int j = 0; j < p / 2; j++)
                {
                    Swap(alst, j, p - j);
                    Swap(pos, alst[j], alst[p - j]);
                }
            }
            p = pos[i - 1];
            if (p >= 0)
            {
                ans.Add(p);
                p--;
                for (int j = 0; j < p / 2; j++)
                {
                    Swap(alst, j, p - j);
                    Swap(pos, alst[j], alst[p - j]);
                }
            }
            ans.Add(i + 1);
        }

        Console.WriteLine(ans.Count);
        Console.WriteLine(string.Join(" ", ans));
    }

    static void Swap(List<int> list, int i, int j)
    {
        int temp = list[i];
        list[i] = list[j];
        list[j] = temp;
    }

    static void Swap(int[] array, int i, int j)
    {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

