using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        int t = int.Parse(Console.ReadLine());
        for (int i = 0; i < t; i++)
        {
            Solve();
        }
    }

    static void Solve()
    {
        string[] input = Console.ReadLine().Split(' ');
        int n = int.Parse(input[0]);
        int k = int.Parse(input[1]);
        long x = long.Parse(input[2]);
        string s = Console.ReadLine();

        if (!s.Contains("*"))
        {
            Console.WriteLine(s);
            return;
        }

        List<string> stars = new List<string>(s.Split('a'));
        stars.RemoveAll(star => star.Length == 0);

        // A string of q stars can expand to 0, 1, 2, ..., q * k b's, which is
        // 1 + k * q possibilities
        List<long> expand = new List<long>();
        foreach (string star in stars)
        {
            expand.Add(1L + k * star.Length);
        }

        // Cumulative product of number of stars
        List<long> prods = new List<long>();
        prods.Add(expand[expand.Count - 1]);
        for (int i = 1; i < stars.Count; i++)
        {
            prods.Add(prods[i - 1] * expand[stars.Count - i - 1]);
        }

        x--;

        // Count how many b's to replace each * by
        List<long> counts = new List<long>();
        foreach (long prod in prods.AsEnumerable().Reverse())
        {
            counts.Add(x / prod);
            x -= prod * (x / prod);
        }
        counts.Add(x % prods[0]);

        // Construct the string
        string answer = "";
        int index = 0;
        int j = 0;
        while (j < s.Length)
        {
            if (s[j] == 'a')
            {
                answer += "a";
                j++;
            }
            else
            {
                answer += new string('b', (int)counts[index]);
                index++;
                while (j < s.Length && s[j] == '*')
                {
                    j++;
                }
            }
        }

        Console.WriteLine(answer);
    }
}

