        int n = int.Parse(input[0]);
        int k = int.Parse(input[1]);

        input = Console.ReadLine().Split();
        List<int> A = new List<int>();
        for (int i = 0; i < n; i++)
        {
            A.Add(int.Parse(input[i]));
        }

        input = Console.ReadLine().Split();
        List<int> B = new List<int>();
        for (int i = 0; i < n; i++)
        {
            B.Add(int.Parse(input[i]));
        }

        List<List<int>> Q = new List<List<int>>();
        for (int i = 0; i < k; i++)
        {
            input = Console.ReadLine().Split();
            Q.Add(new List<int> { int.Parse(input[0]), int.Parse(input[1]) });
        }

        List<int> answer = Process(A, B, Q);
        foreach (int x in answer)
        {
            Console.WriteLine(x);
        }
    }

    static List<int> Process(List<int> A, List<int> B, List<List<int>> Q)
    {
        List<long> S = new List<long> { 0 };
        int n = A.Count;
        for (int i = 0; i < n; i++)
        {
            long ai = A[i];
            long bi = B[i];
            long di = bi - ai;
            S.Add(S[S.Count - 1] + di);
        }
        n = S.Count;
        int p = (int)Math.Ceiling(Math.Log(n) / Math.Log(2));
        p = (int)Math.Pow(2, p);

        List<long> minTree = new List<long>(new long[2 * p - 1]);
        List<long> maxTree = new List<long>(new long[2 * p - 1]);

        for (int i = 0; i < p; i++)
        {
            if (i < n)
            {
                minTree[i] = S[i];
                maxTree[i] = S[i];
            }
            else
            {
                minTree[i] = long.MaxValue;
                maxTree[i] = long.MinValue;
            }
        }

        for (int i = p; i < 2 * p - 1; i++)
        {
            int i1 = (2 * p - 2) - i;
            int j1 = 2 * i1 + 1;
            int j2 = 2 * i1 + 2;
            int iLeft = (2 * p - 2) - j1;
            int iRight = (2 * p - 2) - j2;

            minTree[i] = Math.Min(minTree[iLeft], minTree[iRight]);
            maxTree[i] = Math.Max(maxTree[iLeft], maxTree[iRight]);
        }

        long FindMax(int l, int r, int startL = 0, int startR = -1, int startIndex = -1)
        {
            if (startIndex < 0)
            {
                startIndex = 2 * p - 2;
                startR = p - 1;
            }
            if (l == r)
            {
                return maxTree[l];
            }
            if (l == startL && r == startR)
            {
                return maxTree[startIndex];
            }

            int i1 = (2 * p - 2) - startIndex;
            int iLeft = (2 * p - 2) - (2 * i1 + 2);
            int iRight = (2 * p - 2) - (2 * i1 + 1);
            int m1 = (startL + startR) / 2;

            if (l > m1)
            {
                return FindMax(l, r, m1 + 1, startR, iRight);
            }
            else if (r <= m1)
            {
                return FindMax(l, r, startL, m1, iLeft);
            }
            else
            {
                long max1 = FindMax(l, m1, startL, m1, iLeft);
                long max2 = FindMax(m1 + 1, r, m1 + 1, startR, iRight);
                return Math.Max(max1, max2);
            }
        }

        long FindMin(int l, int r, int startL = 0, int startR = -1, int startIndex = -1)
        {
            if (startIndex < 0)
            {
                startIndex = 2 * p - 2;
                startR = p - 1;
            }
            if (l == r)
            {
                return minTree[l];
            }
            if (l == startL && r == startR)
            {
                return minTree[startIndex];
            }

            int i1 = (2 * p - 2) - startIndex;
            int iLeft = (2 * p - 2) - (2 * i1 + 2);
            int iRight = (2 * p - 2) - (2 * i1 + 1);
            int m1 = (startL + startR) / 2;

            if (l > m1)
            {
                return FindMin(l, r, m1 + 1, startR, iRight);
            }
            else if (r <= m1)
            {
                return FindMin(l, r, startL, m1, iLeft);
            }
            else
            {
                long min1 = FindMin(l, m1, startL, m1, iLeft);
                long min2 = FindMin(m1 + 1, r, m1 + 1, startR, iRight);
                return Math.Min(min1, min2);
            }
        }

        List<int> answer = new List<int>();
        foreach (var query in Q)
        {
            int l = query[0] - 1;
            int r = query[1];
            long s1 = S[l];
            long s2 = S[r];

            if (s1 != s2)
            {
                answer.Add(-1);
            }
            else
            {
                long myMin = FindMin(l, r);
                long myMax = FindMax(l, r);

                if (myMin - s1 < 0)
                {
                    answer.Add(-1);
                }
                else
                {
                    answer.Add((int)(myMax - s1));
                }
            }
        }

        return answer;
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        int t = int.Parse(Console.ReadLine());
        for (int _ = 0; _ < t; _++)
        {
            Console.ReadLine();
            string[] nm = Console.ReadLine().Split();
            int n = int.Parse(nm[0]);
            int m = int.Parse(nm[1]);
            int[,] d = new int[n, m];
            for (int i = 0; i < n; i++)
            {
                string line = Console.ReadLine().Trim();
                for (int j = 0; j < m; j++)
                {
                    char ch = line[j];
                    d[i, j] = ch == 'R' ? -1 : (ch == 'U' ? -2 : (ch == 'L' ? -3 : -4));
                }
            }

            int r = 0;
            Tuple<int, int> pos = new Tuple<int, int>(0, 0);

            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < m; j++)
                {
                    int a = i;
                    int b = j;
                    int p = d[a, b];
                    int c = 0;
                    List<Tuple<int, int>> st = new List<Tuple<int, int>>();

                    while (p < 0)
                    {
                        d[a, b] = 0;
                        st.Add(new Tuple<int, int>(a, b));
                        if (p == -1) b++;
                        else if (p == -2) a--;
                        else if (p == -3) b--;
                        else a++;

                        c++;
                        if (a >= 0 && a < n && b >= 0 && b < m)
                            p = d[a, b];
                        else
                        {
                            for (int ii = 0; ii < st.Count; ii++)
                            {
                                var (x, y) = st[ii];
                                d[x, y] = c - ii;
                            }
                            p = -1;
                            break;
                        }
                    }

                    if (p == 0)
                    {
                        int jj = 0;
                        int flag = 0;
                        for (int ii = 0; ii < st.Count; ii++)
                        {
                            var (x, y) = st[ii];
                            d[x, y] = flag != 0 ? c - jj : c - ii;
                            if (x == a && y == b)
                            {
                                flag = 1;
                                jj = ii;
                            }
                        }
                    }

                    if (p > 0)
                    {
                        for (int ii = 0; ii < st.Count; ii++)
                        {
                            var (x, y) = st[ii];
                            d[x, y] = p + c - ii;
                        }
                    }

                    if (d[i, j] > r)
                    {
                        r = d[i, j];
                        pos = new Tuple<int, int>(i, j);
                    }
                }
            }

            Console.WriteLine((pos.Item1 + 1) + " " + (pos.Item2 + 1) + " " + r);
        }
    }
}

