class Program
{
    const int BUFSIZE = 8192;

    class FastIO : IDisposable
    {
        private readonly Stream _stream;
        private readonly byte[] _buffer;
        private int _bufferIndex;
        private int _bufferLength;

        public FastIO(Stream stream)
        {
            _stream = stream;
            _buffer = new byte[BUFSIZE];
            _bufferIndex = 0;
            _bufferLength = 0;
        }

        public string ReadLine()
        {
            var sb = new System.Text.StringBuilder();
            while (true)
            {
                if (_bufferIndex >= _bufferLength)
                {
                    _bufferLength = _stream.Read(_buffer, 0, BUFSIZE);
                    _bufferIndex = 0;
                    if (_bufferLength == 0) break;
                }
                while (_bufferIndex < _bufferLength && _buffer[_bufferIndex] != '\n')
                {
                    sb.Append((char)_buffer[_bufferIndex++]);
                }
                if (_bufferIndex < _bufferLength)
                {
                    _bufferIndex++;
                    break;
                }
            }
            return sb.ToString();
        }

        public void Dispose()
        {
            _stream.Dispose();
        }
    }

    static void Main(string[] args)
    {
        using (FastIO io = new FastIO(Console.OpenStandardInput()))
        {
            int t = int.Parse(io.ReadLine());
            for (int i = 0; i < t; i++)
            {
                int n = int.Parse(io.ReadLine());
                string[] input = io.ReadLine().Split(' ');
                int[] arr = new int[n];
                for (int j = 0; j < n; j++)
                {
                    arr[j] = int.Parse(input[j]);
                }
                if (n == 2)
                {
                    Console.WriteLine(arr[0] * arr[1]);
                }
                else
                {
                    long res = -1; // Change int to long to handle larger products
                    for (int j = 0; j < n - 1; j++)
                    {
                        long product = (long)Math.Max(arr[j + 1], arr[j]) * Math.Min(arr[j + 1], arr[j]);
                        if (product > res)
                        {
                            res = product;
                        }
                    }
                    Console.WriteLine(res);
                }
            }
        }
    }
}

using System;
using System.Numerics;

class Program
{
    const int Mod = 998244353;

    static (int, int, int) Egcd(int a, int b)
    {
        if (a == 0)
            return (b, 0, 1);
        else
        {
            var result = Egcd(b % a, a);
            int g = result.Item1;
            int y = result.Item2;
            int x = result.Item3;
            return (g, x - (b / a) * y, y);
        }
    }

    static int Modinv(int a, int m)
    {
        var result = Egcd(a, m);
        if (result.Item1 != 1)
            throw new Exception("modular inverse does not exist");
        else
            return (result.Item2 % m + m) % m;
    }

    static int Choose(int n, int k, int p)
    {
        if (k == 0)
            return 1;
        BigInteger x = n;
        for (int y = n - 1; y > n - k; y--)
            x = (x * y) % p;
        BigInteger d = 1;
        for (int i = 2; i <= k; i++)
            d = (d * i) % p;
        return (int)(((x * Modinv((int)d, p)) % p + p) % p);
    }

    static void Solve()
    {
        int n = int.Parse(Console.ReadLine());
        bool wbPoss = n > 1;
        bool bwPoss = n > 1;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        bool anyBadPoss = n > 1;
        for (int i = 0; i < n; i++)
        {
            string s = Console.ReadLine().Trim();
            if (s[0] == 'B')
            {
                b++;
                wbPoss = false;
            }
            else if (s[0] == 'W')
            {
                w++;
                bwPoss = false;
            }
            else if (s[0] == '?')
                q++;

            if (s[1] == 'B')
            {
                b++;
                bwPoss = false;
            }
            else if (s[1] == 'W')
            {
                w++;
                wbPoss = false;
            }
            else if (s[1] == '?')
                q++;

            if (s == "??")
                free++;
            else if (s[0] == s[1])
                anyBadPoss = false;
        }

        int wNeeded = n - w;
        if (wNeeded > q || wNeeded < 0)
        {
            Console.WriteLine(0);
            return;
        }

        int numBadPoss;
        if (anyBadPoss)
            numBadPoss = (int)((BigInteger.Pow(2, free) % Mod) - (bwPoss ? 1 : 0) - (wbPoss ? 1 : 0));
        else
            numBadPoss = 0;

        Console.WriteLine((Choose(q, wNeeded, Mod) - numBadPoss + Mod) % Mod);
    }

    static void Main(string[] args)
    {
        Solve();
    }
}

