const MOD: usize = 998_244_353;
const N: usize = 1_000_000_007;

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: usize = I(&mut lines);
    for _ in 0..t {
        let n: usize = I(&mut lines);
        let mut dp1 = vec![0; n + 2];
        let mut dp2 = vec![0; n + 2];
        dp1[0] = 1;

        let line = S(&mut lines);
        let numbers: Vec<usize> = R(&line).collect();

        for &i in &numbers {
            dp1[i + 1] = (dp1[i + 1] << 1) % MOD;
            dp1[i + 1] = (dp1[i + 1] + dp1[i]) % MOD;
            if i > 0 {
                dp2[i - 1] = (dp2[i - 1] << 1) % MOD;
                dp2[i - 1] = (dp2[i - 1] + dp1[i - 1]) % MOD;
            }
            dp2[i + 1] = (dp2[i + 1] << 1) % MOD;
        }

        let mut ans = 0;
        for i in 0..=n + 1 {
            ans = (ans + dp1[i] + dp2[i]) % MOD;
        }
        println!("{}", (ans + MOD - 1) % MOD);
    }
}

fn I(lines: &mut io::Lines<io::StdinLock>) -> usize {
    R(&S(lines)).next().unwrap()
}

fn S(lines: &mut io::Lines<io::StdinLock>) -> String {
    lines.next().unwrap().unwrap()
}

fn R(line: &str) -> impl Iterator<Item = usize> + '_ {
    line.split_whitespace().map(|s| s.parse().unwrap())
}

use std::io::{self, Read};

const BUFSIZE: usize = 8192;

struct FastIO {
    buffer: Vec<u8>,
    pos: usize,
    end: usize,
}

impl FastIO {
    fn new() -> Self {
        let mut buffer = vec![0; BUFSIZE];
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        let end = handle.read(&mut buffer).unwrap_or(0);
        FastIO { buffer, pos: 0, end }
    }

    fn read_until(&mut self, delimiter: u8) -> String {
        let mut result = String::new();
        loop {
            if self.pos >= self.end {
                let stdin = io::stdin();
                let mut handle = stdin.lock();
                self.end = handle.read(&mut self.buffer).unwrap_or(0);
                self.pos = 0;
                if self.end == 0 {
                    break;
                }
            }
            while self.pos < self.end && self.buffer[self.pos] != delimiter {
                result.push(self.buffer[self.pos] as char);
                self.pos += 1;
            }
            if self.pos < self.end {
                self.pos += 1;
                break;
            }
        }
        result
    }

    fn read_line(&mut self) -> String {
        self.read_until(b'\n')
    }
}

fn next_larger_element(arr: &[i32], f: bool) -> Vec<i32> {
    let n = arr.len();
    let mut s = Vec::new();
    let mut ans = vec![-1; n];
    for i in 0..n {
        while !s.is_empty() && arr[*s.last().unwrap()] < arr[i] {
            s.pop();
        }
        if let Some(&top) = s.last() {
            ans[i] = top as i32;
        }
        s.push(i);
    }
    if f {
        for i in 0..n {
            if ans[i] != -1 {
                ans[i] = n as i32 - 1 - ans[i];
            }
        }
    }
    ans
}

fn dfs(i: usize, adj: &[Vec<usize>], p: usize, ans: usize) -> usize {
    let mut f = true;
    let mut a1 = 0;
    for &j in &adj[i] {
        if j != p {
            a1 += dfs(j, adj, i, ans + 1);
            f = false;
        }
    }
    if f {
        a1 += (ans * (ans - 1)) / 2;
    }
    a1
}

