            .collect()
    }

    let t: usize = read_int(&mut lines);
    for _ in 0..t {
        let n = read_int(&mut lines);
        let mut alst = read_ints(&mut lines).into_iter().map(|x| x - 1).collect::<Vec<usize>>();
        let mut pos = vec![None; n];

        for (i, &a) in alst.iter().enumerate() {
