                        pos.swap(alst[j], alst[p - j]);
                    }
                    if let Some(p) = pos[i] {
                        ans.push(p + 1);
                        for j in 0..p / 2 {
                            alst.swap(j, p - j);
                            pos.swap(alst[j], alst[p - j]);
                        }
