use std::io::{self, Read, Write};
use std::os::unix::io::AsRawFd;

const BUFSIZE: usize = 8192;

struct FastIO {
    fd: i32,
    buffer: Vec<u8>,
    pos: usize,
    end: usize,
}

impl FastIO {
    fn new(file: &File) -> Self {
        FastIO {
            fd: file.as_raw_fd(),
            buffer: vec![0; BUFSIZE],
            pos: 0,
            end: 0,
        }
    }

    fn read(&mut self) -> io::Result<()> {
        loop {
            let n = unsafe {
                libc::read(
                    self.fd,
                    self.buffer.as_mut_ptr().add(self.end),
                    BUFSIZE - self.end,
                )
            };
            if n == 0 {
                break;
            }
            self.end += n as usize;
        }
        Ok(())
    }

    fn readline(&mut self) -> io::Result<String> {
        let mut result = String::new();
        loop {
            if self.pos < self.end {
                while self.pos < self.end && self.buffer[self.pos] != b'\n' {
                    result.push(self.buffer[self.pos] as char);
                    self.pos += 1;
                }
                if self.pos < self.end {
                    result.push('\n');
                    self.pos += 1;
                    break;
                }
            } else {
                self.read()?;
                if self.end == 0 {
                    break;
                }
            }
        }
        Ok(result)
    }
}

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut fast_io = FastIO::new(&stdin.lock());
    let stdout = io::stdout();
