fn solve() {
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let mut iter = input.split_whitespace();
    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let x: usize = iter.next().unwrap().parse().unwrap();

    input.clear();
    io::stdin().read_line(&mut input).unwrap();
    let s = input.trim();

    if !s.contains('*') {
        println!("{}", s);
        return;
    }

    let stars: Vec<&str> = s.split('a').filter(|&x| !x.is_empty()).collect();

    let expand: Vec<usize> = stars.iter().map(|star| 1 + k * star.len()).collect();

    let mut prods = vec![*expand.last().unwrap()];
    for i in 1..stars.len() {
        prods.push(prods[i - 1] * expand[stars.len() - i - 1]);
    }

    let mut x = x - 1;
    let mut counts = Vec::new();
    for &prod in prods.iter().rev() {
        counts.push(x / prod);
        x -= prod * (x / prod);
    }
    counts.push(x % prods[0]);

    let mut answer = String::new();
    let mut i = 1;
    let mut j = 0;
    while j < s.len() {
        if &s[j..j + 1] == "a" {
            answer.push('a');
            j += 1;
        } else {
            answer.extend(std::iter::repeat('b').take(counts[i]));
            i += 1;
            while j < s.len() && &s[j..j + 1] == "*" {
                j += 1;
            }
        }
    }

    println!("{}", answer);
}

