    }
}

use std::io::{self, Read};

fn process(a: &[i32], b: &[i32], q: &[(usize, usize)]) -> Vec<i32> {
    let mut s = vec![0];
    for i in 0..a.len() {
        let di = b[i] - a[i];
        s.push(s[i] + di);
    }
    let n = s.len();
    let p = (n as f64).log2().ceil() as usize;
    let p = 1 << p;
    let mut min_tree = vec![i32::MAX; 2 * p - 1];
    let mut max_tree = vec![i32::MIN; 2 * p - 1];

    for i in 0..p {
        if i < n {
            min_tree[i] = s[i];
            max_tree[i] = s[i];
        } else {
            min_tree[i] = i32::MAX;
            max_tree[i] = i32::MIN;
        }
    }

    for i in p..(2 * p - 1) {
        let i1 = (2 * p - 2) - i;
        let j1 = 2 * i1 + 1;
        let j2 = 2 * i1 + 2;
        let i_left = (2 * p - 2) - j1;
        let i_right = (2 * p - 2) - j2;
        min_tree[i] = min_tree[i_left].min(min_tree[i_right]);
        max_tree[i] = max_tree[i_left].max(max_tree[i_right]);
    }

    fn find_max(
        l: usize,
        r: usize,
        start_l: usize,
        start_r: usize,
        start_i: usize,
        max_tree: &[i32],
    ) -> i32 {
        if start_i >= max_tree.len() || l > start_r || r < start_l {
            return i32::MIN;
        }
        if l == r {
            return max_tree[l];
        }
        if l == start_l && r == start_r {
            return max_tree[start_i];
        }
        let i1 = (2 * max_tree.len() - 2) - start_i;
        let i_l = (2 * max_tree.len() - 2) - (2 * i1 + 2);
        let i_r = (2 * max_tree.len() - 2) - (2 * i1 + 1);
        let m1 = (start_l + start_r) / 2;
        if l > m1 {
            find_max(l, r, m1 + 1, start_r, i_r, max_tree)
        } else if r <= m1 {
            find_max(l, r, start_l, m1, i_l, max_tree)
        } else {
            let max1 = find_max(l, m1, start_l, m1, i_l, max_tree);
            let max2 = find_max(m1 + 1, r, m1 + 1, start_r, i_r, max_tree);
            max1.max(max2)
        }
    }

    fn find_min(
        l: usize,
        r: usize,
        start_l: usize,
        start_r: usize,
        start_i: usize,
        min_tree: &[i32],
    ) -> i32 {
        if start_i >= min_tree.len() || l > start_r || r < start_l {
            return i32::MAX;
        }
        if l == r {
            return min_tree[l];
        }
        if l == start_l && r == start_r {
            return min_tree[start_i];
        }
        let i1 = (2 * min_tree.len() - 2) - start_i;
        let i_l = (2 * min_tree.len() - 2) - (2 * i1 + 2);
        let i_r = (2 * min_tree.len() - 2) - (2 * i1 + 1);
        let m1 = (start_l + start_r) / 2;
        if l > m1 {
            find_min(l, r, m1 + 1, start_r, i_r, min_tree)
        } else if r <= m1 {
            find_min(l, r, start_l, m1, i_l, min_tree)
        } else {
            let min1 = find_min(l, m1, start_l, m1, i_l, min_tree);
            let min2 = find_min(m1 + 1, r, m1 + 1, start_r, i_r, min_tree);
            min1.min(min2)
        }
    }

    let mut answer = Vec::new();
    for &(l, r) in q {
        let s1 = s[l - 1];
        let s2 = s[r];
        if s1 != s2 {
            answer.push(-1);
        } else {
            let my_min = find_min(l, r, 0, p - 1, 2 * p - 2, &min_tree);
            let my_max = find_max(l, r, 0, p - 1, 2 * p - 2, &max_tree);
            if my_min - s1 < 0 {
                answer.push(-1);
            } else {
                answer.push(my_max - s1);
            }
        }
    }
    answer
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

