fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: usize = lines.next().unwrap().expect("Failed to read line").parse().unwrap();

    for _ in 0..t {
        lines.next(); // Skip the empty line
        let first_line = lines.next().unwrap().expect("Failed to read line");
        let mut parts = first_line.split_whitespace();
        let n: usize = parts.next().unwrap().parse().unwrap();
        let m: usize = parts.next().unwrap().parse().unwrap();

        let mut d = vec![vec![-1; m]; n];

        let second_line = lines.next().unwrap().expect("Failed to read line");
        for (i, c) in second_line.chars().enumerate() {
            match c {
                'R' => d[0][i] = -1,
                'U' => d[0][i] = -2,
                'L' => d[0][i] = -3,
                _ => d[0][i] = -4,
            }
        }

        let mut r = 0;
        let mut pos = (0, 0);

        for i in 0..n {
            for j in 0..m {
                let mut a = i;
                let mut b = j;
                let mut p = d[a][b];
                let mut c = 0;
                let mut st = Vec::new();

                while p < 0 {
                    d[a][b] = 0;
                    st.push((a, b));
                    if p == -1 {
                        b += 1;
                    } else if p == -2 {
                        a = a.checked_sub(1).unwrap_or(a);
                    } else if p == -3 {
                        b = b.checked_sub(1).unwrap_or(b);
                    } else {
                        a += 1;
                    }
                    c += 1;
                    if a < n && b < m {
                        p = d[a][b];
                    } else {
                        for (ii, &(x, y)) in st.iter().enumerate() {
                            d[x][y] = c - ii;
                        }
                        p = -1;
                        break;
                    }
                }

