fn egcd(a: u64, b: u64) -> (u64, i64, i64) {
    if a == 0 {
        (b, 0, 1)
    } else {
        let (g, y, x) = egcd(b % a, a);
        (g, x - (b / a) as i64 * y, y)
    }
}

fn modinv(a: u64, m: u64) -> u64 {
    let (_, x, _) = egcd(a, m);
    ((x % m as i64 + m as i64) % m as i64) as u64
}

fn choose(n: u64, k: u64, p: u64) -> u64 {
    if k == 0 {
        return 1;
    }
    let mut x = n;
    for y in (n - 1..n - k).rev() {
        x = x * y % p;
    }
    let mut d = 1;
    for i in 2..=k {
        d = d * i % p;
    }
    x * modinv(d, p) % p
}

