use std::io::{self, Read, Write};
use std::os::unix::io::RawFd;
use std::sync::atomic::{AtomicUsize, Ordering};

const BUFSIZE: usize = 8192;

struct FastIO {
    fd: RawFd,
    buffer: Vec<u8>,
    pos: AtomicUsize,
    len: AtomicUsize,
}

impl FastIO {
    fn new(fd: RawFd) -> Self {
        FastIO {
            fd,
            buffer: vec![0; BUFSIZE],
            pos: AtomicUsize::new(0),
            len: AtomicUsize::new(0),
        }
    }

    fn read(&mut self) -> io::Result<()> {
        let mut total_read = 0;
        loop {
            let bytes_read = unsafe {
                libc::read(
                    self.fd,
                    self.buffer.as_mut_ptr().add(total_read),
                    BUFSIZE - total_read,
                )
            };
            if bytes_read == 0 {
                break;
            } else if bytes_read < 0 {
                return Err(io::Error::last_os_error());
            }
            total_read += bytes_read as usize;
        }
        self.len.store(total_read, Ordering::Relaxed);
        Ok(())
    }

    fn readline(&mut self) -> io::Result<String> {
        let mut result = String::new();
        loop {
            if self.pos.load(Ordering::Relaxed) >= self.len.load(Ordering::Relaxed) {
                self.read()?;
                if self.len.load(Ordering::Relaxed) == 0 {
                    break;
                }
            }
            while self.pos.load(Ordering::Relaxed) < self.len.load(Ordering::Relaxed) {
                let byte = self.buffer[self.pos.load(Ordering::Relaxed)];
                self.pos.fetch_add(1, Ordering::Relaxed);
                if byte == b'\n' {
                    result.push(byte as char);
                    return Ok(result);
                } else {
                    result.push(byte as char);
                }
            }
        }
        Ok(result)
    }
}

struct IOWrapper {
    buffer: FastIO,
}

impl IOWrapper {
    fn new(fd: RawFd) -> Self {
        IOWrapper {
            buffer: FastIO::new(fd),
        }
    }

    fn read_line(&mut self) -> io::Result<String> {
        self.buffer.readline()
    }
}

