long long inv(long long x) {
    long long result = 1;
    long long base = x;
    long long exp = N - 2;
    while (exp > 0) {
        if (exp % 2 == 1) {
            result = (result * base) % N;
        }
        base = (base * base) % N;
        exp /= 2;
    }
    return result;
}

