const int BUFSIZE = 8192;

class FastIO {
public:
    int _fd;
    std::string buffer;
    bool writable;

    FastIO(int fd, bool writable) : _fd(fd), writable(writable) {}

    std::string read() {
        char b[BUFSIZE];
        while (true) {
            ssize_t bytesRead = ::read(_fd, b, BUFSIZE);
            if (bytesRead <= 0) break;
            buffer.append(b, bytesRead);
        }
        return buffer;
    }

    std::string readline() {
        char b[BUFSIZE];
        while (true) {
            ssize_t bytesRead = ::read(_fd, b, BUFSIZE);
            if (bytesRead <= 0) break;
            size_t newlinePos = buffer.find('\n', buffer.size());
            if (newlinePos != std::string::npos) {
                buffer.append(b, newlinePos + 1);
                break;
            }
            buffer.append(b, bytesRead);
        }
        return buffer.substr(0, buffer.find_last_of('\n') + 1);
    }

    void flush() {
        if (writable) {
            ::write(_fd, buffer.c_str(), buffer.size());
            buffer.clear();
        }
    }
};

class IOWrapper {
public:
    FastIO* fastio;
    bool writable;

    IOWrapper(int fd, bool writable) : writable(writable), fastio(new FastIO(fd, writable)) {}

    ~IOWrapper() {
        delete fastio;
    }

    void write(const std::string& s) {
        if (writable) {
            fastio->buffer.append(s);
        }
    }

    std::string read() const {
        return fastio->read();
    }

    std::string readline() const {
        return fastio->readline();
    }

    void flush() {
        fastio->flush();
    }
};

std::ostream& operator<<(std::ostream& os, const IOWrapper& wrapper) {
    wrapper.flush();
    return os;
}

int inp(IOWrapper& input) {
    std::string line = input.readline();
    return std::stoi(line);
}

std::string inps(IOWrapper& input) {
    return input.readline().substr(0, input.readline().find_last_of('\n'));
}

std::vector<int> inlt(IOWrapper& input) {
    std::string line = input.readline();
    std::istringstream iss(line);
    std::vector<int> result;
    int num;
    while (iss >> num) {
        result.push_back(num);
    }
    return result;
}

std::vector<char> insr(IOWrapper& input) {
    std::string line = input.readline().substr(0, input.readline().find_last_of('\n'));
    return std::vector<char>(line.begin(), line.end());
}

std::vector<int> invr(IOWrapper& input) {
    std::string line = input.readline();
    std::istringstream iss(line);
    std::vector<int> result;
    int num;
    while (iss >> num) {
        result.push_back(num);
    }
    return result;
}

int main() {
    IOWrapper input(STDIN_FILENO, false);
    IOWrapper output(STDOUT_FILENO, true);

    int t = inp(input);
    for (int i = 0; i < t; ++i) {
        int n = inp(input);
        std::vector<int> l = inlt(input);
        if (n % 2 == 0) {
            output.write("YES\n");
        } else {
            bool flag = false;
            for (int j = 0; j < n - 1; ++j) {
                if (l[j] >= l[j + 1]) {
                    flag = true;
                    break;
                }
            }
            if (flag) {
                output.write("YES\n");
            } else {
                output.write("NO\n");
            }
        }
    }

    return 0;
}

