#include <string>

void solve() {
    int n, k, x;
    std::cin >> n >> k >> x;
    std::string s;
    std::getline(std::cin >> std::ws, s);

    if (s.find('*') == std::string::npos) {
        std::cout << s << std::endl;
        return;
    }

    std::vector<std::string> stars;
    size_t pos = 0;
    while ((pos = s.find('a', pos)) != std::string::npos) {
        if (pos > 0 && s[pos - 1] == '*') {
            stars.push_back(s.substr(pos - 1, pos - (pos - 1)));
        }
        pos++;
    }

    std::vector<int> expand;
    for (const auto& star : stars) {
        expand.push_back(1 + k * star.length());
    }

    std::vector<long long> prods{expand.back()};
    for (size_t i = 1; i < stars.size(); ++i) {
        prods.push_back(prods.back() * static_cast<long long>(expand[stars.size() - i - 1]));
    }

    x -= 1;

    std::vector<int> counts;
    for (auto it = prods.rbegin(); it != prods.rend(); ++it) {
        counts.push_back(x / *it);
        x -= *it * (x / *it);
    }
    counts.push_back(x % prods[0]);

    std::string answer;
    size_t i = 1;
    size_t j = 0;
    while (j < s.length()) {
        if (s[j] == 'a') {
            answer += 'a';
            j++;
        } else {
            answer.append(counts[i], 'b');
            i++;
            while (j < s.length() && s[j] == '*') {
                j++;
            }
        }
    }

    std::cout << answer << std::endl;
}

int main() {
    int t;
    std::cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <climits>
#include <functional>

using namespace std;

vector<int> process(const vector<int>& A, const vector<int>& B, const vector<vector<int>>& Q) {
    vector<long long> S = {0};
    int n = A.size();
    for (int i = 0; i < n; ++i) {
        long long ai = A[i];
        long long bi = B[i];
        long long di = bi - ai;
        S.push_back(S.back() + di);
    }
    n = S.size();
    int p = ceil(log2(n));
    p = 1 << p;
    vector<long long> min_tree(2 * p - 1, LLONG_MAX);
    vector<long long> max_tree(2 * p - 1, LLONG_MIN);

    for (int i = 0; i < p; ++i) {
        if (i < n) {
            min_tree[i] = S[i];
            max_tree[i] = S[i];
        } else {
            min_tree[i] = LLONG_MAX;
            max_tree[i] = LLONG_MIN;
        }
    }

    for (int i = p; i < 2 * p - 1; ++i) {
        int i1 = (2 * p - 2) - i;
        int j1 = 2 * i1 + 1;
        int j2 = 2 * i1 + 2;
        int i_left = (2 * p - 2) - j1;
        int i_right = (2 * p - 2) - j2;
        min_tree[i] = min(min_tree[i_left], min_tree[i_right]);
        max_tree[i] = max(max_tree[i_left], max_tree[i_right]);
    }

    function<long long(int, int, int, int, int)> find_max = [&](int l, int r, int start_l, int start_r, int start_i) -> long long {
        if (start_i < 0) return LLONG_MIN;
        if (l == r) return max_tree[l];
        if (l == start_l && r == start_r) return max_tree[start_i];
        int i1 = (2 * p - 2) - start_i;
        int i_l = (2 * p - 2) - (2 * i1 + 2);
        int i_r = (2 * p - 2) - (2 * i1 + 1);
        int m1 = (start_l + start_r) / 2;
        if (l > m1) return find_max(l, r, m1 + 1, start_r, i_r);
        else if (r <= m1) return find_max(l, r, start_l, m1, i_l);
        else {
            long long max1 = find_max(l, m1, start_l, m1, i_l);
            long long max2 = find_max(m1 + 1, r, m1 + 1, start_r, i_r);
            return max(max1, max2);
        }
    };

    function<long long(int, int, int, int, int)> find_min = [&](int l, int r, int start_l, int start_r, int start_i) -> long long {
        if (start_i < 0) return LLONG_MAX;
        if (l == r) return min_tree[l];
        if (l == start_l && r == start_r) return min_tree[start_i];
        int i1 = (2 * p - 2) - start_i;
        int i_l = (2 * p - 2) - (2 * i1 + 2);
        int i_r = (2 * p - 2) - (2 * i1 + 1);
        int m1 = (start_l + start_r) / 2;
        if (l > m1) return find_min(l, r, m1 + 1, start_r, i_r);
        else if (r <= m1) return find_min(l, r, start_l, m1, i_l);
        else {
            long long min1 = find_min(l, m1, start_l, m1, i_l);
            long long min2 = find_min(m1 + 1, r, m1 + 1, start_r, i_r);
            return min(min1, min2);
        }
    };

    vector<int> answer;
    for (const auto& qr : Q) {
        int l = qr[0];
        int r = qr[1];
        long long s1 = S[l - 1];
        long long s2 = S[r];
        if (s1 != s2) {
            answer.push_back(-1);
        } else {
            long long my_min = find_min(l, r, 0, p - 1, 2 * p - 2);
            long long my_max = find_max(l, r, 0, p - 1, 2 * p - 2);
            if (my_min - s1 < 0) {
                answer.push_back(-1);
            } else {
                answer.push_back(my_max - s1);
            }
        }
    }
    return answer;
}

int main() {
    int n, k;
    cin >> n >> k;
    vector<int> A(n), B(n);
    for (int i = 0; i < n; ++i) cin >> A[i];
    for (int i = 0; i < n; ++i) cin >> B[i];
    vector<vector<int>> Q(k, vector<int>(2));
    for (int i = 0; i < k; ++i) {
        cin >> Q[i][0] >> Q[i][1];
    }
    vector<int> answer = process(A, B, Q);
    for (int x : answer) {
        cout << x << '\n';
    }
    return 0;
}

