class Dsu {
public:
    vector<int> parent;

    Dsu(int n) : parent(n + 1) {}

    void makeSet() {
        for (int i = 1; i <= parent.size() - 1; ++i) {
            parent[i] = i;
        }
    }

    int findParent(int node) {
        if (node == parent[node]) {
            return node;
        }
        return parent[node] = findParent(parent[node]);
    }

    int unionSets(int u, int v) {
        int uParent = findParent(u);
        int vParent = findParent(v);

        if (uParent != vParent) {
            parent[vParent] = uParent;
            return 0;
        } else {
            return -1;
        }
    }

    void checkComponent(int u, int v) {
        if (findParent(u) != findParent(v)) {
            cout << "Both belongs to different components\n";
        } else {
            cout << "same component\n";
        }
    }

    void reUnion(int u, int v) {}
};

