const int BUFSIZE = 8192;

class FastIO {
private:
    int _fd;
    char buffer[BUFSIZE];
    bool writable;

public:
    FastIO(FILE* file) : _fd(fileno(file)), writable(isatty(_fd)) {}

    size_t read() {
        return ::read(_fd, buffer, BUFSIZE);
    }

    std::string readline() {
        std::string line;
        while (true) {
            ssize_t result = ::read(_fd, buffer, BUFSIZE);
            if (result <= 0) break;
            for (size_t i = 0; i < result; ++i) {
                if (buffer[i] == '\n') {
                    line.append(buffer, i + 1);
                    return line;
                }
            }
            line.append(buffer, result);
        }
        return line;
    }

    void write(const std::string& str) {
        if (writable) {
            ::write(_fd, str.c_str(), str.size());
        }
    }
};

