const int BUFSIZE = 8192;

class FastIO {
public:
    FILE* _fd;
    char buffer[BUFSIZE];
    bool writable;

    FastIO(FILE* file) : _fd(file), writable(file == stdout) {}

    std::string read() {
        std::ostringstream oss;
        while (true) {
            size_t bytesRead = fread(buffer, 1, BUFSIZE, _fd);
            if (bytesRead == 0) break;
            oss.write(buffer, bytesRead);
        }
        return oss.str();
    }

    std::string readline() {
        std::ostringstream oss;
        while (true) {
            size_t bytesRead = fread(buffer, 1, BUFSIZE, _fd);
            if (bytesRead == 0) break;
            oss.write(buffer, bytesRead);
            if (oss.tellp() > 0 && oss.str()[oss.tellp() - 1] == '\n') break;
        }
        return oss.str();
    }

    void flush() {
        if (writable) {
            fwrite(buffer, 1, std::strlen(buffer), _fd);
            buffer[0] = '\0';
        }
    }
};

class IOWrapper {
public:
    FastIO* fastio;
    bool writable;

    IOWrapper(FILE* file) : fastio(new FastIO(file)), writable(file == stdout) {}

    ~IOWrapper() {
        delete fastio;
    }

    std::string read() {
        return fastio->read();
    }

    std::string readline() {
        return fastio->readline();
    }

    void write(const std::string& str) {
        if (writable) {
            std::strncpy(fastio->buffer, str.c_str(), BUFSIZE - 1);
            fastio->flush();
        }
    }

    void flush() {
        fastio->flush();
    }
};

