func pow(_ base: Int, _ exponent: Int, _ modulus: Int) -> Int {
    var result = 1
    var base = base % modulus
    var exponent = exponent

    while exponent > 0 {
        if exponent & 1 == 1 {
            result = (result * base) % modulus
        }
        exponent >>= 1
        base = (base * base) % modulus
    }

    return result
}

func nCr(_ x: Int, _ y: Int) -> Int {
    let f = Array(0...x).map { factorial($0) % N }
    return (f[x] * inv((f[y] * f[x - y]) % N)) % N
}

