            }
        }
    }
    return ans
}

func dfs(_ i: Int, _ adj: [[Int]], _ p: Int, _ ans: Int) -> Int {
    var f = true
    var a1 = 0
    for j in adj[i] {
        if j != p {
            a1 += dfs(j, adj, i, ans + 1)
            f = false
        }
    }
    if f {
        a1 += ans * (ans - 1) / 2
    }
    return a1
}

