class FastIO {
    private var fd: Int32
    private var buffer: Data
    private var writable: Bool

    init(file: FileHandle) {
        self.fd = file.fileDescriptor
        self.buffer = Data()
        self.writable = file.writeabilityHandler != nil
    }

    func read() -> Data {
        while true {
            let data = FileHandle(fileDescriptor: fd).availableData
            if data.isEmpty {
                break
            }
            buffer.append(data)
        }
        return buffer
    }

    func readline() -> String? {
        while !buffer.contains(where: { $0 == 10 }) {
            let data = FileHandle(fileDescriptor: fd).availableData
            if data.isEmpty {
                break
            }
            buffer.append(data)
        }
        guard let newlineIndex = buffer.firstIndex(of: 10) else { return nil }
        let line = String(data: buffer[..<newlineIndex], encoding: .ascii)
        buffer.removeSubrange(...newlineIndex)
