import Foundation

func process(_ A: [Int], _ B: [Int], _ Q: [[Int]]) -> [Int] {
    var S = [0]
    let n = A.count
    for i in 0..<n {
        let ai = A[i]
        let bi = B[i]
        let di = bi - ai
        S.append(S.last! + di)
    }
    let m = S.count
    let p = Int(ceil(log(Double(m)) / log(2.0)))
    let treeSize = Int(pow(2.0, Double(p)))

    var minTree = Array(repeating: Int.max, count: 2 * treeSize - 1)
    var maxTree = Array(repeating: Int.min, count: 2 * treeSize - 1)

    for i in 0..<treeSize {
        if i < m {
            minTree[i] = S[i]
            maxTree[i] = S[i]
        } else {
            minTree[i] = Int.max
            maxTree[i] = Int.min
        }
    }

    for i in treeSize..<(2 * treeSize - 1) {
        let i1 = (2 * treeSize - 2) - i
        let j1 = 2 * i1 + 1
        let j2 = 2 * i1 + 2
        let iLeft = (2 * treeSize - 2) - j1
        let iRight = (2 * treeSize - 2) - j2
        minTree[i] = min(minTree[iLeft], minTree[iRight])
        maxTree[i] = max(maxTree[iLeft], maxTree[iRight])
    }

    func findMax(_ l: Int, _ r: Int, startL: Int = 0, startR: Int = -1, startIndex: Int = -1) -> Int {
        if startIndex < 0 {
            return Int.min
        }
        let startR = (startR == -1) ? treeSize - 1 : startR
        if l == r {
            return maxTree[l]
        }
        if l == startL && r == startR {
            return maxTree[startIndex]
        }
        let i1 = (2 * treeSize - 2) - startIndex
        let iLeft = (2 * treeSize - 2) - (2 * i1 + 2)
        let iRight = (2 * treeSize - 2) - (2 * i1 + 1)
        let m1 = (startL + startR) / 2
        if l > m1 {
            return findMax(l, r, startL: m1 + 1, startR: startR, startIndex: iRight)
        } else if r <= m1 {
            return findMax(l, r, startL: startL, startR: m1, startIndex: iLeft)
        } else {
            let max1 = findMax(l, m1, startL: startL, startR: m1, startIndex: iLeft)
            let max2 = findMax(m1 + 1, r, startL: m1 + 1, startR: startR, startIndex: iRight)
            return max(max1, max2)
        }
    }

    func findMin(_ l: Int, _ r: Int, startL: Int = 0, startR: Int = -1, startIndex: Int = -1) -> Int {
        assert(startL <= l && l <= r && (startR == -1 || r <= startR))
        if startIndex < 0 {
            return Int.max
        }
        let startR = (startR == -1) ? treeSize - 1 : startR
        if l == r {
            return minTree[l]
        }
        if l == startL && r == startR {
            return minTree[startIndex]
        }
        let i1 = (2 * treeSize - 2) - startIndex
        let iLeft = (2 * treeSize - 2) - (2 * i1 + 2)
        let iRight = (2 * treeSize - 2) - (2 * i1 + 1)
        let m1 = (startL + startR) / 2
        if l > m1 {
            return findMin(l, r, startL: m1 + 1, startR: startR, startIndex: iRight)
        } else if r <= m1 {
            return findMin(l, r, startL: startL, startR: m1, startIndex: iLeft)
        } else {
            let min1 = findMin(l, m1, startL: startL, startR: m1, startIndex: iLeft)
            let min2 = findMin(m1 + 1, r, startL: m1 + 1, startR: startR, startIndex: iRight)
            return min(min1, min2)
        }
    }

    var answer: [Int] = []
    for query in Q {
        let l = query[0]
        let r = query[1]
        let s1 = S[l - 1]
        let s2 = S[r]
        if s1 != s2 {
            answer.append(-1)
        } else {
            let myMin = findMin(l, r)
            let myMax = findMax(l, r)
            if myMin - s1 < 0 {
                answer.append(-1)
            } else {
                answer.append(myMax - s1)
            }
        }
    }
    return answer
}

