class Dsu {
    var parent: [Int]

    init(n: Int) {
        self.parent = Array(repeating: 0, count: n + 1)
    }

    func makeSet() {
        for i in 1...self.parent.count - 1 {
            self.parent[i] = i
        }
    }

    func findParent(_ node: Int) -> Int {
        if node == self.parent[node] {
            return node
        }

        self.parent[node] = findParent(self.parent[node])
        return self.parent[node]
    }

    func union(_ u: Int, _ v: Int) -> Int {
        let uParent = findParent(u)
        let vParent = findParent(v)

        if uParent != vParent {
            self.parent[vParent] = uParent
            return 0
        } else {
            return -1
        }
    }

