let mod = 998244353

func egcd(_ a: Int, _ b: Int) -> (Int, Int, Int) {
    if a == 0 {
        return (b, 0, 1)
    } else {
        let (g, y, x) = egcd(b % a, a)
        return (g, x - (b / a) * y, y)
    }
}

func modinv(_ a: Int, _ m: Int) -> Int {
    let (_, x, _) = egcd(a, m)
    if x < 0 {
        return (x % m + m) % m
    } else {
        return x % m
    }
}

func choose(_ n: Int, _ k: Int, _ p: Int) -> Int {
    if k == 0 {
        return 1
    }
    var x = n
    for y in stride(from: n - 1, through: n - k + 1, by: -1) {
        x = (x * y) % p
    }
    var d = 1
    for i in 2...k {
        d = (d * i) % p
    }
    return (x * modinv(d, p)) % p
}

