        } else if s.dropFirst().first == "W" {
            w += 1
            bw_poss = false
        } else if s.dropFirst().first == "?" {
            q += 1
        }

        if s == "??" {
            free += 1
        } else if s.first == s.dropFirst().first {
            any_bad_poss = false
        }
    }

    let w_needed = n - w
    if w_needed > q || w_needed < 0 {
        print(0)
        return
    }

    var num_bad_poss: Int
    if any_bad_poss {
        num_bad_poss = Int(pow(Double(2), Double(free))) % mod
        num_bad_poss = (num_bad_poss - (bw_poss ? 1 : 0) - (wb_poss ? 1 : 0) + mod) % mod
    } else {
        num_bad_poss = 0
    }

    print((choose(q, w_needed, mod) - num_bad_poss + mod) % mod)
}

