const MOD = 998244353;
const SZ = 2e6 + 5;

let fac: number[] = new Array(SZ).fill(1);
let ifac: number[] = new Array(SZ);
let prime: number[] = new Array(SZ);

function mpow(a: number, b: number = MOD - 2, m: number = MOD): number {
    let res = 1;
    a %= m;
    while (b > 0) {
        if (b & 1) res = (res * a) % m;
        a = (a * a) % m;
        b >>= 1;
    }
    return res;
}

function init(): void {
    for (let i = 2; i < SZ; i++) fac[i] = (fac[i - 1] * i) % MOD;
    ifac[SZ - 1] = mpow(fac[SZ - 1]);
    for (let i = SZ - 2; i >= 0; i--) ifac[i] = (ifac[i + 1] * (i + 1)) % MOD;
    for (let i = 2; i < SZ; i++) prime[i] = i;
    for (let i = 2; i * i < SZ; i++) {
        if (prime[i] !== i) continue;
        for (let j = i * i; j < SZ; j += i) {
            if (prime[j] === j) prime[j] = i;
        }
    }
}

function nCr(n: number, r: number): number {
    if (n <= 0 || r < 0) return 0;
    if (n < r) return 0;
    return (fac[n] * (ifac[r] * ifac[n - r] % MOD)) % MOD;
}

function gcd(a: number, b: number): number { return b ? gcd(b, a % b) : a; }
function lcm(a: number, b: number): number { return Math.floor((a / gcd(a, b)) * b); }

function solve(input: string[]): void {
    const [n, m, k] = input.map(Number);
    const highTables = n % m;
    const remTables = m - highTables;
    const highPeople = Math.ceil(n / m);
    const lessPeople = Math.floor(n / m);
    const players: number[] = Array.from({ length: n }, (_, i) => i + 1);

    for (let game = 0; game < k; game++) {
        let tableNo = 1;
        for (; tableNo <= highTables; ++tableNo) {
            process.stdout.write(`${highPeople} `);
            for (let peep = 1; peep <= highPeople; peep++) {
                const indx = players.shift()!;
                process.stdout.write(`${indx} `);
                players.push(indx);
            }
            process.stdout.write("\n");
        }
        for (; tableNo <= m; ++tableNo) {
            process.stdout.write(`${lessPeople} `);
            for (let peep = 1; peep <= lessPeople; peep++) {
                const indx = players.shift()!;
                process.stdout.write(`${indx} `);
                players.push(indx);
            }
            process.stdout.write("\n");
        }
        const shiftBack = highTables * highPeople;
        for (let i = 0; i < shiftBack; i++) {
            const indx = players.shift()!;
            players.push(indx);
        }
    }
    process.stdout.write("\n");
}

