	a[1] = false
	a[0] = false
	h := int64(n + 1)
	for i := int64(2); i < h; i++ {
		if !a[i] {
			continue
		}
		for j := int64(2 * i); j < n+1; j += i {
			a[j] = false
		}
	}
}

