	r := dfs(gox, goy, t+1)
	if cyc {
		if beg.x == x && beg.y == y {
			cyc = false
		}
		ans[x][y] = r
	} else {
		ans[x][y] = r + 1
	}
	ret[x][y] = cur
	return ans[x][y]
}

