func pw(x int64, k int) int64 {
	res := int64(1)
	for k > 0 {
		if k&1 == 1 {
			res *= x
			res %= mod
		}
		k >>= 1
		x *= x
		x %= mod
	}
	return res
}

func c(n, k int) int64 {
	if k < 0 {
		return 0
	}
	res := int64(1)
	for i := n - k + 1; i <= n; i++ {
		res *= int64(i)
		res %= mod
	}
	for i := 2; i <= k; i++ {
		res *= pw(int64(i), mod-2)
		res %= mod
	}
	return res
}

