const mod = 998244353
const sz = 2000005

var fac [sz]int64
var ifac [sz]int64
var prime [sz]int

func mpow(a, b, m int64) int64 {
	res := int64(1)
	a %= m
	for b > 0 {
		if b&1 == 1 {
			res = res * a % m
		}
		a = a * a % m
		b >>= 1
	}
	return res
}

func initialize() {
	fac[0], fac[1] = 1, 1
	for i := 2; i < sz; i++ {
		fac[i] = fac[i-1]*int64(i) % mod
	}
	ifac[sz-1] = mpow(fac[sz-1], mod-2, mod)
	for i := sz - 2; i >= 0; i-- {
		ifac[i] = ifac[i+1]*(i+1)%mod
	}
	for i := 2; i < sz; i++ {
		prime[i] = i
	}
	for i := 2; i*i < sz; i++ {
		if prime[i] != i {
			continue
		}
		for j := i * i; j < sz; j += i {
			if prime[j] == j {
				prime[j] = i
			}
		}
	}
}

func nCr(n, r int64) int64 {
	if n <= 0 || r < 0 {
		return 0
	}
	if n < r {
		return 0
	}
	return fac[n] * ifac[r] % mod * ifac[n-r] % mod
}

func gcd(a, b int64) int64 {
	if b == 0 {
		return a
	}
	return gcd(b, a%b)
}

func lcm(a, b int64) int64 {
	return (a / gcd(a, b)) * b
}

