public class Main {
    private static final double EPS = 0.000001;
    private static final int MOD = 998244353;
    private static final int INF = 1000000101;
    private static final long LLINF = 1223372000000000555L;
    private static final int N = (int) (2e6 + 3e2);
    private static final int M = 522;

    private static int[] a = new int[N];
    private static int[] f = new int[N];
    private static int[] dp = new int[N];
    private static int[] color = new int[N];
    private static boolean cycle = false;
    private static long startTime;

    public static void debugOut(Object... args) {
        System.err.print("[");
        for (int i = 0; i < args.length; i++) {
            System.err.print(args[i]);
            if (i < args.length - 1) System.err.print(", ");
        }
        System.err.println("]");
    }

    public static double getCurrentTime() {
        return (System.currentTimeMillis() - startTime) / 1000.0;
    }

    private static void dfs(int v) {
        if (cycle) return;
        color[v] = 1;
        if (a[v] == 0) {
            dp[v] = 0;
            color[v] = 2;
            return;
        }
        int u = f[v];
        if (color[u] == 0) dfs(u);
        if (color[u] == 1) {
            cycle = true;
            return;
        }
        dp[v] = dp[u] + 1;
        color[v] = 2;
    }

    private static void solve(int TC, Scanner scanner) {
        int n = scanner.nextInt();
        int d = scanner.nextInt();
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
            f[i] = (i + n - d) % n;
            color[i] = 0;
            dp[i] = INF;
        }
        cycle = false;
        for (int i = 0; i < n; i++) {
            if (color[i] == 0) dfs(i);
            if (cycle) break;
        }
        if (cycle) {
            System.out.println(-1);
            return;
        }
        int maxDp = Arrays.stream(dp, 0, n).max().orElse(0);
        System.out.println(maxDp);
    }

    public static void main(String[] args) {
        startTime = System.currentTimeMillis();
        Scanner scanner = new Scanner(System.in);
        int TC = scanner.nextInt();
        for (int test = 1; test <= TC; test++) {
            solve(test, scanner);
        }
        System.err.println("Time: " + (int) (getCurrentTime() * 1000) + " ms");
    }
}

