public class Main {
    static long n, k, x;
    static String s;
    static List<Integer> vec = new ArrayList<>();
    static List<Integer> ans = new ArrayList<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int q = Integer.parseInt(scanner.nextLine());
        while (q-- > 0) {
            input(scanner);
            solve();
        }
        scanner.close();
    }

    private static void input(Scanner scanner) {
        String[] parts = scanner.nextLine().split(" ");
        n = Long.parseLong(parts[0]);
        k = Long.parseLong(parts[1]);
        x = Long.parseLong(parts[2]) - 1;
        s = scanner.nextLine();
    }

    private static void solve() {
        vec.clear();
        ans.clear();
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '*') {
                cnt++;
            } else {
                vec.add((int) (cnt * k));
                cnt = 0;
            }
        }
        vec.add((int) (cnt * k));
        for (int i = vec.size() - 1; i >= 0; i--) {
            ans.add((int) (x % (vec.get(i) + 1)));
            x /= (vec.get(i) + 1);
        }
        int sr = ans.size();
        for (int i = sr; i < vec.size(); i++) {
            ans.add(0);
        }
        StringBuilder fin = new StringBuilder();
        Collections.reverse(ans);
        for (int i = 0; i < ans.size(); i++) {
            String str = "b".repeat(ans.get(i));
            fin.append(str);
            if (i != ans.size() - 1) {
                fin.append('a');
            }
        }
        System.out.println(fin.toString());
    }
}

