public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int q = scanner.nextInt();

        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextLong();
        }

        for (int i = 0; i < n; i++) {
            int b = scanner.nextInt();
            a[i] = b - a[i];
            if (i > 0) {
                a[i] += a[i - 1];
            }
        }

        long[][] mn = new long[20][n];
        long[][] mx = new long[20][n];

        for (int i = 0; i < n; i++) {
            mn[0][i] = a[i];
            mx[0][i] = a[i];
        }

        for (int k = 1; k < 20; k++) {
            for (int i = 0; i + (1 << (k - 1)) < n; i++) {
                mn[k][i] = Math.min(mn[k - 1][i], mn[k - 1][i + (1 << (k - 1))]);
                mx[k][i] = Math.max(mx[k - 1][i], mx[k - 1][i + (1 << (k - 1))]);
            }
        }

        while (q-- > 0) {
            int l = scanner.nextInt() - 1;
            int r = scanner.nextInt();
            int k = log2(r - l);
            long _min = Math.min(mn[k][l], mn[k][r - (1 << k)]);
            long _max = Math.max(mx[k][l], mx[k][r - (1 << k)]);
            long start = l > 0 ? a[l - 1] : 0;

            if (start != a[r - 1] || _min < start) {
                System.out.println("-1");
            } else {
                System.out.println(_max - start);
            }
        }

        scanner.close();
    }

    public static int log2(int x) {
        return 31 - Integer.numberOfLeadingZeros(x);
    }
}

