public class Main {
    static char[][] str = new char[2020][2020];
    static int[][] fusnfe = new int[2020][2020];
    static int[][] vis = new int[2020][2020];
    static int[][] ret = new int[2020][2020];
    static int[][] ans = new int[2020][2020];
    static int cur = 0;
    static int n, m;
    static boolean cyc = false;
    static int[] beg = new int[2];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int nt = scanner.nextInt();
        while (nt-- > 0) {
            cur++;
            n = scanner.nextInt();
            m = scanner.nextInt();
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                for (int j = 0; j < m; j++) {
                    str[i][j] = line.charAt(j);
                    vis[i][j] = 0;
                }
            }
            int mx = 0, ansx = 0, ansy = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (vis[i][j] != 0) continue;
                    int t = dfs(i, j, 0);
                    if (t > mx) {
                        mx = t;
                        ansx = i + 1;
                        ansy = j + 1;
                    }
                }
            }
            System.out.printf("%d %d %d%n", ansx, ansy, mx);
        }
    }

    static int dfs(int x, int y, int t) {
        if (x < 0 || x == n || y < 0 || y == m) return 0;
        if (vis[x][y] == cur && ret[x][y] < cur) {
            cyc = true;
            beg[0] = x;
            beg[1] = y;
            return ans[x][y] = t - fusnfe[x][y];
        }
        if (vis[x][y] == cur) return ans[x][y];
        vis[x][y] = cur;
        fusnfe[x][y] = t;
        int gox = x, goy = y;
        if (str[x][y] == 'R') goy++;
        if (str[x][y] == 'L') goy--;
        if (str[x][y] == 'U') gox--;
        if (str[x][y] == 'D') gox++;
        int r = dfs(gox, goy, t + 1);
        if (cyc) {
            if (x == beg[0] && y == beg[1]) cyc = false;
            ans[x][y] = r;
        } else {
            ans[x][y] = r + 1;
        }
        ret[x][y] = cur;
        return ans[x][y];
    }
}

