import java.util.Scanner;

public class Main {
    static final int MAXN = (int) 1e5 + 7;
    static final int INF = (int) 2e9 + 9;
    static final int MOD = 998244353;
    static char[] a = new char[2];

    public static void main(String[] args) {
        solve();
    }

    static long pw(long x, int k) {
        long res = 1L;
        while (k > 0) {
            if ((k & 1) == 1) {
                res *= x;
                res %= MOD;
            }
            k >>= 1;
            x *= x;
            x %= MOD;
        }
        return res;
    }

    static long c(int n, int k) {
        if (k < 0) return 0;
        long res = 1;
        for (int i = n - k + 1; i <= n; ++i) {
            res *= i;
            res %= MOD;
        }
        for (int i = 2; i <= k; ++i) {
            res *= pw(i, MOD - 2);
            res %= MOD;
        }
        return res;
    }

    static boolean is(char[] c) {
        return a[0] == c[0] && a[1] == c[1];
    }

    static void solve() {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int _b = 0, b_ = 0, _w = 0, w_ = 0, __ = 0, e = 0, tw = 0, tb = 0;
        boolean same = false;
        for (int i = 0; i < n; ++i) {
            scanner.next().getChars(0, 2, a, 0);
            for (int j = 0; j < 2; ++j) {
                if (a[j] == 'B') {
                    tb++;
                } else if (a[j] == 'W') {
                    tw++;
                }
            }
            if (is("??".toCharArray())) __++;
            if (is("BB".toCharArray()) || is("WW".toCharArray())) same = true;
            switch (a[0]) {
                case 'B':
                    b_ = 1;
                    break;
                case 'W':
                    w_ = 1;
                    break;
                case '?':
                    e++;
                    break;
            }
            switch (a[1]) {
                case 'B':
                    _b = 1;
                    break;
                case 'W':
                    _w = 1;
                    break;
                case '?':
                    e++;
                    break;
            }
        }
        int d = Math.abs(tb - tw);
        long res = c(e, (e - d) / 2);
        if (!same) {
            res -= pw(2, __);
            if (_w == 0 && b_ == 0) res++;
            if (w_ == 0 && _b == 0) res++;
            res = (res + MOD) % MOD;
        }
        System.out.printf("%d", res);
    }
}

