        }
        long sum = 0;
        sum += cnt[0] * cnt[1] + cnt[0] * cnt[2] + cnt[0] * cnt[3];
        for (int i = 0; i < 4; i++) {
            sum += (cnt[i] * (cnt[i] - 1)) / 2;
        }
        return sum;
    }

