import java.io.*;
import java.util.*;

public class Main {
    private static final long MOD = 998244353;
    private static final int SZ = (int) 2e6 + 5;
    private static long[] fac, ifac;
    private static int[] prime;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        init();
        int t = Integer.parseInt(br.readLine());
        for (int i = 1; i <= t; i++) {
            solve(br, out);
        }
        out.close();
    }

    private static long mpow(long a, long b, long m) {
        long res = 1;
        a %= m;
        assert b >= 0;
        for (; b > 0; b >>= 1) {
            if ((b & 1) == 1) res = res * a % m;
            a = a * a % m;
        }
        return res;
    }

    private static void init() {
        fac = new long[SZ];
        ifac = new long[SZ];
        Arrays.fill(fac, 1);
        fac[0] = fac[1] = 1;
        for (int i = 2; i < SZ; i++) fac[i] = (fac[i - 1] * i) % MOD;
        ifac[SZ - 1] = mpow(fac[SZ - 1], MOD - 2, MOD);
        for (int i = SZ - 2; i >= 0; i--) {
            ifac[i] = (ifac[i + 1] * (i + 1)) % MOD;
        }
        prime = new int[SZ];
        for (int i = 2; i < SZ; i++) prime[i] = i;
        for (long i = 2; i * i < SZ; i++) {
            if (prime[(int) i] != (int) i) continue;
            for (long j = i * i; j < SZ; j += i) {
                if (prime[(int) j] == (int) j) prime[(int) j] = (int) i;
            }
        }
    }

    private static long nCr(long n, long r) {
        if (n <= 0 || r < 0) return 0;
        if (n < r) return 0;
        return (fac[(int) n] * (ifac[(int) r] * ifac[(int) (n - r)] % MOD)) % MOD;
    }

    private static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    private static long lcm(long a, long b) {
        return (a / gcd(a, b)) * b;
    }

    private static void solve(BufferedReader br, PrintWriter out) throws IOException {
        String[] input = br.readLine().split(" ");
        long n = Long.parseLong(input[0]);
        long m = Long.parseLong(input[1]);
        long k = Long.parseLong(input[2]);
        long highTables = n % m;
        long remTables = m - highTables;
        long highPeople = (n + m - 1) / m;
        long lessPeople = n / m;
        Queue<Long> players = new LinkedList<>();
        for (int i = 1; i <= n; i++) players.add((long) i);
        for (long game = 0; game < k; game++) {
            long tableNo;
            for (tableNo = 1; tableNo <= highTables; ++tableNo) {
                out.print(highPeople + " ");
                for (int peep = 1; peep <= highPeople; peep++) {
                    long indx = players.poll();
                    out.print(indx + " ");
                    players.add(indx);
                }
                out.println();
            }
            for (tableNo = 1; tableNo <= remTables; ++tableNo) {
                out.print(lessPeople + " ");
                for (int peep = 1; peep <= lessPeople; peep++) {
                    long indx = players.poll();
                    out.print(indx + " ");
                    players.add(indx);
                }
                out.println();
            }
            long shiftBack = highTables * highPeople;
            for (int i = 0; i < shiftBack; i++) {
                long indx = players.poll();
                players.add(indx);
            }
        }
        out.println();
    }
}

