class Program
{
    const int maxn = 100007, inf = 2000000009, mod = 998244353;

    static long Pw(long x, int k)
    {
        long res = 1;
        while (k > 0)
        {
            if ((k & 1) == 1)
            {
                res *= x;
                res %= mod;
            }
            k >>= 1;
            x *= x;
            x %= mod;
        }
        return res;
    }

    static long C(int n, int k)
    {
        if (k < 0) return 0;
        long res = 1;
        for (int i = n - k + 1; i <= n; ++i)
        {
            res *= i;
            res %= mod;
        }
        for (int i = 2; i <= k; ++i)
        {
            res *= Pw(i, mod - 2);
            res %= mod;
        }
        return res;
    }

    static bool Is(char[] a, char[] c)
    {
        return a[0] == c[0] && a[1] == c[1];
    }

    static void Solve()
    {
        int n = int.Parse(Console.ReadLine());
        int _b = 0, b_ = 0, _w = 0, w_ = 0, __ = 0, e = 0, tw = 0, tb = 0;
        bool same = false;
        for (int i = 0; i < n; ++i)
        {
            char[] a = Console.ReadLine().ToCharArray();
            for (int j = 0; j < 2; ++j)
            {
                if (a[j] == 'B')
                    tb++;
                else if (a[j] == 'W')
                    tw++;
            }
            if (Is(a, new char[] { '?', '?' })) __++;
            if (Is(a, new char[] { 'B', 'B' }) || Is(a, new char[] { 'W', 'W' })) same = true;
            switch (a[0])
            {
                case 'B':
                    b_ = 1;
                    break;
                case 'W':
                    w_ = 1;
                    break;
                case '?':
                    e++;
                    break;
            }
            switch (a[1])
            {
                case 'B':
                    _b = 1;
                    break;
                case 'W':
                    _w = 1;
                    break;
                case '?':
                    e++;
                    break;
            }
        }
        int d = Math.Abs(tb - tw);
        long res = C(e, (e - d) / 2);
        if (!same)
        {
            res -= Pw(2, __);
            if (_w == 0 && b_ == 0) res++;
            if (w_ == 0 && _b == 0) res++;
            res = (res + mod) % mod;
        }
        Console.WriteLine(res);
    }

    static void Main(string[] args)
    {
        Solve();
    }
}

