class Program
{
    const long Mod = 998244353;
    const int Sz = (int)2e6 + 5;
    static List<long> Fac, Ifac;
    static List<int> Prime;

    static long MPow(long a, long b = Mod - 2, long m = Mod)
    {
        long res = 1;
        a %= m;
        while (b > 0)
        {
            if ((b & 1) == 1) res = res * a % m;
            a = a * a % m;
            b >>= 1;
        }
        return res;
    }

    static void Init()
    {
        Fac = new List<long>(new long[Sz]);
        Ifac = new List<long>(new long[Sz]);
        Fac[0] = Fac[1] = 1;
        for (long i = 2; i < Sz; i++) Fac[(int)i] = (Fac[(int)(i - 1)] * i) % Mod;
        Ifac[Sz - 1] = MPow(Fac[Sz - 1]);
        for (long i = Sz - 2; i >= 0; i--)
            Ifac[(int)i] = (Ifac[(int)(i + 1)] * (i + 1)) % Mod;
        Prime = new List<int>(new int[Sz]);
        for (int i = 2; i < Sz; i++) Prime[i] = i;
        for (long i = 2; i * i < Sz; i++)
        {
            if (Prime[(int)i] != (int)i) continue;
            for (long j = i * i; j < Sz; j += i)
                if (Prime[(int)j] == (int)j) Prime[(int)j] = (int)i;
        }
    }

    static long NCr(long n, long r)
    {
        if (n <= 0 || r < 0) return 0;
        if (n < r) return 0;
        return (Fac[(int)n] * (Ifac[(int)r] * Ifac[(int)(n - r)] % Mod)) % Mod;
    }

    static long GCD(long a, long b) => b == 0 ? a : GCD(b, a % b);

    static long LCM(long a, long b) => (a / GCD(a, b)) * b;

    static void Solve()
    {
        string[] input = Console.ReadLine().Split();
        long n = long.Parse(input[0]);
        long m = long.Parse(input[1]);
        long k = long.Parse(input[2]);
        long highTables = n % m;
        long remTables = m - highTables;
        long highPeople = (n + m - 1) / m;
        long lessPeople = n / m;
        Queue<long> players = new Queue<long>();
        for (int i = 1; i <= n; i++) players.Enqueue(i);
        for (long game = 0; game < k; game++)
        {
            long tableNo;
            for (tableNo = 1; tableNo <= highTables; ++tableNo)
            {
                Console.Write(highPeople + " ");
                for (int peep = 1; peep <= highPeople; peep++)
                {
                    long indx = players.Dequeue();
                    Console.Write(indx + " ");
                    players.Enqueue(indx);
                }
                Console.WriteLine();
            }
            for (tableNo = 1; tableNo <= remTables; ++tableNo)
            {
                Console.Write(lessPeople + " ");
                for (int peep = 1; peep <= lessPeople; peep++)
                {
                    long indx = players.Dequeue();
                    Console.Write(indx + " ");
                    players.Enqueue(indx);
                }
                Console.WriteLine();
            }
            long shiftBack = highTables * highPeople;
            for (int i = 0; i < shiftBack; i++)
            {
                long indx = players.Dequeue();
                players.Enqueue(indx);
            }
        }
        Console.WriteLine();
    }

    static void Main()
    {
        Init();
        int t = int.Parse(Console.ReadLine());
        for (int i = 1; i <= t; i++)
        {
            Solve();
        }
    }
}

