fn isprime(n: i64) -> bool {
    if n == 1 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    for i in (3..=((n as f64).sqrt() as i64)).step_by(2) {
        if n % i == 0 {
            return false;
        }
    }
    true
}

fn power(mut x: i64, mut y: i64, mod_val: i64) -> i64 {
    let mut ans = 1;
    x %= mod_val;
    while y > 0 {
        if y % 2 == 1 {
            ans = (ans * x) % mod_val;
        }
        y /= 2;
        x = (x * x) % mod_val;
    }
    ans
}

fn sieve(a: &mut [bool], n: usize) {
    a[0] = false;
    a[1] = false;
    let h = ((n + 1) as f64).sqrt() as usize;
    for i in 2..h {
        if !a[i] {
            continue;
        }
        for j in (i * 2..=n).step_by(i) {
            a[j] = false;
        }
    }
}

