const MAX_N: usize = 2022;

fn go(a: &mut [i64], pos: &mut usize, ans: &mut Vec<usize>) {
    ans.push(*pos);
    a[1..=*pos].reverse();
}

fn solve(input: &mut dyn BufRead) -> io::Result<()> {
    let mut buffer = String::new();
    input.read_line(&mut buffer)?;
    let n: usize = buffer.trim().parse().map_err(|_| io::Error::new(io::ErrorKind::Other, "Parse error"))?;

    let mut a = vec![0; MAX_N];
    buffer.clear();
    input.read_line(&mut buffer)?;
    let numbers: Vec<i64> = buffer.trim().split_whitespace()
        .map(|s| s.parse().map_err(|_| io::Error::new(io::ErrorKind::Other, "Parse error")))
        .collect::<Result<_, _>>()?;
    for i in 0..n {
        a[i + 1] = numbers[i];
    }

    let mut ans = Vec::new();
    let mut pos = 0;
    for i in 1..=n {
        if i % 2 != a[i] as usize % 2 {
            print!("-1\n");
            return Ok(());
        }
    }
    for i in (2..=n).rev().step_by(2) {
        for j in 1..=n {
            if a[j] == i as i64 {
                pos = j;
                break;
            }
        }
        go(&mut a, &mut pos, &mut ans);
        for j in 1..=n {
            if a[j] == (i - 1) as i64 {
                pos = j - 1;
                break;
            }
        }
        go(&mut a, &mut pos, &mut ans);
        for j in 1..=n {
            if a[j] == (i - 1) as i64 {
                pos = j + 1;
                break;
            }
        }
        go(&mut a, &mut pos, &mut ans);
        pos = 3;
        go(&mut a, &mut pos, &mut ans);
        pos = i;
        go(&mut a, &mut pos, &mut ans);
    }
    print!("{}\n", ans.len());
    for &i in &ans {
        print!("{} ", i);
    }
    println!();
    Ok(())
}

