fn dfs(v: usize, a: &mut [i32], f: &[usize], dp: &mut [i32], color: &mut [u8], cycle: &mut bool) {
    if *cycle {
        return;
    }
    color[v] = 1;
    if a[v] == 0 {
        dp[v] = 0;
        color[v] = 2;
        return;
    }
    let u = f[v];
    if color[u] == 0 {
        dfs(u, a, f, dp, color, cycle);
    }
    if color[u] == 1 {
        *cycle = true;
        return;
    }
    dp[v] = dp[u] + 1;
    color[v] = 2;
}

fn solve(_tc: usize) -> String {
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let mut iter = input.split_whitespace();
    let n: usize = iter.next().unwrap().parse().unwrap();
    let d: usize = iter.next().unwrap().parse().unwrap();

    input.clear();
    io::stdin().read_line(&mut input).unwrap();
    let numbers: Vec<i32> = input.split_whitespace().map(|x| x.parse().unwrap()).collect();

    let mut a = vec![0; n];
    let mut f = vec![0; n];
    let mut dp = vec![INF; n];
    let mut color = vec![0; n];
    let mut cycle = false;

    for i in 0..n {
        a[i] = numbers[i];
        f[i] = (i + n - d) % n;
        color[i] = 0;
        dp[i] = INF;
    }

    for i in 0..n {
        if color[i] == 0 {
            dfs(i, &mut a, &f, &mut dp, &mut color, &mut cycle);
        }
        if cycle {
            break;
        }
    }

    if cycle {
        "-1\n".to_string()
    } else {
        format!("{}\n", *dp.iter().max().unwrap())
    }
}

