fn log2(x: usize) -> usize {
    31 - x.leading_zeros() as usize
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let first_line = lines.next().unwrap().unwrap();
    let mut parts = first_line.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let q: usize = parts.next().unwrap().parse().unwrap();

    let mut a = vec![0; n];
    let second_line = lines.next().unwrap().unwrap();
    for (i, num) in second_line.split_whitespace().enumerate() {
        a[i] = num.parse::<i64>().unwrap();
    }

    let third_line = lines.next().unwrap().unwrap();
    for (i, num) in third_line.split_whitespace().enumerate() {
        let b: i64 = num.parse().unwrap();
        a[i] = b - a[i];
        if i > 0 {
            a[i] += a[i - 1];
        }
    }

    const MAX_K: usize = 20;
    let mut mn = vec![vec![0; n]; MAX_K];
    let mut mx = vec![vec![0; n]; MAX_K];

    for i in 0..n {
        mn[0][i] = a[i];
        mx[0][i] = a[i];
    }

    for k in 1..MAX_K {
        for i in 0..n - (1 << (k - 1)) {
            mn[k][i] = mn[k - 1][i].min(mn[k - 1][i + (1 << (k - 1))]);
            mx[k][i] = mx[k - 1][i].max(mx[k - 1][i + (1 << (k - 1))]);
        }
    }

    for _ in 0..q {
