        let r: usize = parts.next().unwrap().parse::<usize>().unwrap();

        let k = log2(r - l);
        let _min = mn[k][l].min(mn[k][r - (1 << k)]);
        let _max = mx[k][l].max(mx[k][r - (1 << k)]);
        let start = if l > 0 { a[l - 1] } else { 0 };

        if start != a[r - 1] || _min < start {
            println!("-1");
        } else {
            println!("{}", _max - start);
        }
    }
}

