const MOD: i64 = 998244353;
const SZ: usize = 2_000_001;

fn mpow(mut a: i64, mut b: i64, m: i64) -> i64 {
    let mut res = 1;
    a %= m;
    assert!(b >= 0);
    while b > 0 {
        if b & 1 == 1 {
            res = res * a % m;
        }
        a = a * a % m;
        b >>= 1;
    }
    res
}

fn init() -> (Vec<i64>, Vec<i64>, Vec<usize>) {
    let mut fac = vec![1; SZ];
    let mut ifac = vec![0; SZ];
    for i in 2..SZ {
        fac[i] = fac[i - 1] * i as i64 % MOD;
    }
    ifac[SZ - 1] = mpow(fac[SZ - 1], MOD - 2, MOD);
    for i in (0..SZ - 1).rev() {
        ifac[i] = ifac[i + 1] * (i as i64 + 1) % MOD;
    }
    let mut prime = vec![0; SZ];
    for i in 2..SZ {
        prime[i] = i;
    }
    for i in 2..=((SZ as f64).sqrt() as usize) {
        if prime[i] != i {
            continue;
        }
        for j in (i * i..SZ).step_by(i) {
            if prime[j] == j {
                prime[j] = i;
            }
        }
    }
    (fac, ifac, prime)
}

fn ncr(n: usize, r: usize, fac: &Vec<i64>, ifac: &Vec<i64>) -> i64 {
    if n <= 0 || r < 0 {
        return 0;
    }
    if n < r {
        return 0;
    }
    (fac[n] * ifac[r] % MOD * ifac[n - r] % MOD) % MOD
}

fn gcd(mut a: i64, mut b: i64) -> i64 {
