func pw(_ x: Int, _ k: Int) -> Int {
    var res = 1
    var base = x
    var exp = k
    while exp > 0 {
        if exp & 1 == 1 {
            res *= base
            res %= mod
        }
        base *= base
        base %= mod
        exp >>= 1
    }
    return res
}

func c(_ n: Int, _ k: Int) -> Int {
    if k < 0 { return 0 }
    var res = 1
    for i in (n - k + 1)...n {
        res *= i
        res %= mod
    }
    for i in 2...k {
        res *= pw(i, mod - 2)
        res %= mod
    }
    return res
}

