        self.tmin = [float('inf')] * (self.n * 2)

        for i in range(self.n):
            self.tmax[self.n + i] = self.tmin[self.n + i] = self.aa[i]

        for i in range(self.n - 1, 0, -1):
            self.tmax[i] = max(self.tmax[i << 1], self.tmax[(i << 1) | 1])
            self.tmin[i] = min(self.tmin[i << 1], self.tmin[(i << 1) | 1])

    def qmax(self, l, r):
        ans = float('-inf')
        l += self.n
        r += self.n

        while l <= r:
            if l & 1:
                ans = max(ans, self.tmax[l])
                l += 1
            if not (r & 1):
                ans = max(ans, self.tmax[r])
                r -= 1
            l >>= 1
            r >>= 1

        return ans

    def qmin(self, l, r):
        ans = float('inf')
        l += self.n
        r += self.n

        while l <= r:
            if l & 1:
                ans = min(ans, self.tmin[l])
                l += 1
            if not (r & 1):
                ans = min(ans, self.tmin[r])
                r -= 1
            l >>= 1
            r >>= 1

        return ans

