class Constant:
    MOD = 998244353

def bin_pow(a, b):
    res = 1
    while b > 0:
        a %= Constant.MOD
        if b & 1 == 1:
            res = (res * a) % Constant.MOD
        b >>= 1
        a = (a * a) % Constant.MOD
    return res

def mod_inverse(a):
    return bin_pow(a, Constant.MOD - 2)

def mul(a, b):
    return (a * b) % Constant.MOD

