                let one = 1 + D[u][1];
                if (u > 1) one += D[u - 2][2];
                let two = 1 + D[u][2];
                if (u + 2 <= n) two += D[u + 2][1];

                D[u][0] = (D[u][0] + zero) % this.mod;
                D[u][1] = (D[u][1] + one) % this.mod;
                D[u][2] = (D[u][2] + two) % this.mod;
            }

            const ans = (D[0][0] + D[1][1]) % this.mod;
            this.out.write(`${ans}\n`);
        }
    }

    dc(a: number): number {
        let r = 0;
        while (a > 0) {
            r++;
            a = Math.floor(a / 10);
        }
        return r;
    }

    gcd(a: number, b: number): number {
        return b === 0 ? a : this.gcd(b, a % b);
    }

    mp(a: number, p: number): number {
        let r = 1;
        while (p > 0) {
            if (p & 1) r = (r * a) % this.mod;
            p >>= 1;
            a = (a * a) % this.mod;
        }
        return r;
    }
}

