                if (p % 2 !== a[i] % 2) {
                    flag = 1;
                }
            }
            if (flag === 1) {
                out.write('-1\n');
            } else {
                const list: number[] = [];
                for (let i = n; i > 1; i -= 2) {
                    let in1 = 0, in2 = 0;
                    for (let j = 0; j < n; j++) {
                        if (a[j] === i) in1 = j;
                        else if (a[j] === i - 1) in2 = j;
                    }
                    this.reverse(a, in1);
                    if (in1 > in2) {
                        in2 = in1 - in2;
                    }
                    this.reverse(a, in2 - 1);
                    this.reverse(a, in2 + 1);
                    this.reverse(a, 2);
                    this.reverse(a, i - 1);
                    list.push(in1 + 1); list.push(in2); list.push(in2 + 2); list.push(3); list.push(i);
                }
                out.write(`${list.length}\n`);
                out.write(list.join(' ') + '\n');
            }
        }
    }

    public static reverse(a: number[], r: number) {
        for (let i = 0; i <= Math.floor(r / 2); i++) {
            const l = i, h = r - i;
            const t = a[l];
            a[l] = a[h];
            a[h] = t;
        }
    }
}

class FastReader {
    private lines: string[];
    private currentLine: number;
    private tokens: string[];

    constructor(input: string) {
        this.lines = input.split('\n');
        this.currentLine = 0;
        this.tokens = [];
    }

    private readLine(): string {
        if (this.currentLine >= this.lines.length) {
            throw new Error("No more lines");
        }
        return this.lines[this.currentLine++];
    }

    public next(): string {
        while (this.tokens.length === 0) {
            this.tokens = this.readLine().split(/\s+/);
        }
        return this.tokens.shift()!;
    }

    public nextInt(): number {
        return parseInt(this.next(), 10);
    }

    public nextLong(): number {
        return parseFloat(this.next());
    }

    public nextDouble(): number {
        return parseFloat(this.next());
    }

    public nextLine(): string {
        if (this.tokens.length > 0) {
            return this.tokens.join(' ');
        }
        return this.readLine();
    }
}

