const INF = Math.floor(Number.MAX_SAFE_INTEGER / 2);

function main() {
    const input = process.stdin;
    const output = process.stdout;
    let data = '';

    input.on('data', chunk => {
        data += chunk.toString();
    });

    input.on('end', () => {
        const lines = data.split('\n');
        let index = 0;

        const T = parseInt(lines[index++].trim());
        const sb: string[] = [];

        for (let t = 0; t < T; t++) {
            const [N, D] = lines[index++].trim().split(' ').map(Number);
            const arr = readArr(N, lines[index++]);
            const dist = new Array(N).fill(INF);
            const q: number[] = [];

            for (let i = 0; i < N; i++) {
                if (arr[i] === 0) {
                    dist[i] = 0;
                    q.push(i);
                }
            }

            while (q.length > 0) {
                const curr = q.shift()!;
                let next = curr + D;
                if (next >= N) {
                    next -= N;
                }
                if (dist[next] === INF) {
                    dist[next] = dist[curr] + 1;
                    q.push(next);
                }
            }

            let res = 0;
            for (const x of dist) {
                res = Math.max(res, x);
            }
            if (res === INF) {
                res = -1;
            }
            sb.push(`${res}\n`);
        }

        output.write(sb.join(''));
    });
}

function readArr(N: number, line: string): number[] {
    const arr = new Array(N);
    for (let i = 0; i < N; i++) {
        arr[i] = line.charCodeAt(i) - '0'.charCodeAt(0);
    }
    return arr;
}

