class CF1556E {
    private rl: readline.Interface;
    private aa: number[];
    private tmax: number[];
    private tmin: number[];
    private n: number;

    constructor() {
        this.rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout
        });
    }

    public async main() {
        const lines: string[] = [];
        for await (const line of this.rl) {
            lines.push(line);
        }
        const allInput = lines.join(' ');
        const tokens = allInput.split(/\s+/).map(Number);

        let index = 0;
        this.n = tokens[index++];
        let q = tokens[index++];

        this.aa = new Array(this.n).fill(0);
        for (let i = 0; i < this.n; i++) {
            this.aa[i] = -tokens[index++];
        }
        for (let i = 0; i < this.n; i++) {
            this.aa[i] += tokens[index++];
        }
        for (let i = 1; i < this.n; i++) {
            this.aa[i] += this.aa[i - 1];
        }

        this.build();
        while (q-- > 0) {
            const l = tokens[index++] - 1;
            const r = tokens[index++] - 1;
            const a = l === 0 ? 0 : this.aa[l - 1];
            const b = this.aa[r];
            console.log(a !== b || this.qmin(l, r) !== a ? -1 : this.qmax(l, r) - a);
        }
    }

    private build() {
        this.tmax = new Array(this.n * 2).fill(Number.NEGATIVE_INFINITY);
        this.tmin = new Array(this.n * 2).fill(Number.POSITIVE_INFINITY);
        for (let i = 0; i < this.n; i++) {
            this.tmax[this.n + i] = this.tmin[this.n + i] = this.aa[i];
        }
        for (let i = this.n - 1; i > 0; i--) {
            this.tmax[i] = Math.max(this.tmax[i << 1], this.tmax[(i << 1) | 1]);
            this.tmin[i] = Math.min(this.tmin[i << 1], this.tmin[(i << 1) | 1]);
        }
    }

    private qmax(l: number, r: number): number {
        let ans = Number.NEGATIVE_INFINITY;
        for (l += this.n, r += this.n; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) === 1) {
                ans = Math.max(ans, this.tmax[l++]);
            }
            if ((r & 1) === 0) {
                ans = Math.max(ans, this.tmax[r--]);
            }
        }
        return ans;
    }

    private qmin(l: number, r: number): number {
        let ans = Number.POSITIVE_INFINITY;
        for (l += this.n, r += this.n; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) === 1) {
                ans = Math.min(ans, this.tmin[l++]);
            }
            if ((r & 1) === 0) {
                ans = Math.min(ans, this.tmin[r--]);
            }
        }
        return ans;
    }
}

