    private buffer: string[] = [];
    private currentIndex: number = 0;

    constructor() {
        this.rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout,
            terminal: false
        });
        this.readInput();
    }

    private readInput(): void {
        this.rl.on('line', (line) => {
            this.buffer.push(...line.split(/\s+/));
        });
    }

    public next(): string {
        while (this.currentIndex >= this.buffer.length) {
            // Wait for more input if buffer is empty
        }
        return this.buffer[this.currentIndex++];
    }

    public nextInt(): number {
        return parseInt(this.next(), 10);
    }

    public nextLine(): string {
        let line = '';
        while (true) {
            const token = this.next();
            if (token === '') break;
            line += token + ' ';
        }
        return line.trim();
    }

    public readArray(n: number): number[] {
        const array: number[] = [];
        for (let i = 0; i < n; i++) {
            array.push(this.nextInt());
        }
        return array;
    }

    public readArrayLong(n: number): bigint[] {
