function solve(io: FastIOAdapter): void {
    const n = io.nextInt();
    const m = io.nextInt();
    const a: string[][] = [];
    for (let i = 0; i < n; i++) {
        a[i] = io.next().split('');
    }
    const lengths: number[][] = Array.from({ length: n }, () => Array(m).fill(0));
    const indices: number[][] = Array.from({ length: n }, () => Array(m).fill(0));
    let x = 0, y = 0;
    let max = 0;

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
            if (lengths[i][j] === 0) {
                const stack: [number, number][] = [];
                stack.push([i, j]);
                lengths[i][j] = -1;
                indices[i][j] = 0;
                let length = 1;
                let cycle = 0;
                let cycX = -1, cycY = -1;

                while (true) {
                    const [xc, yc] = stack[stack.length - 1];
                    let newXc = xc, newYc = yc;
                    if (a[xc][yc] === 'U') {
                        newXc--;
                    } else if (a[xc][yc] === 'D') {
                        newXc++;
                    } else if (a[xc][yc] === 'L') {
                        newYc--;
                    } else {
                        newYc++;
                    }

                    if (newXc < 0 || newXc >= n || newYc < 0 || newYc >= m) {
                        break;
                    } else if (lengths[newXc][newYc] < 0) {
                        cycle -= indices[newXc][newYc] - 1;
                        length = cycle + 1;
                        cycX = newXc;
                        cycY = newYc;
                        break;
                    } else if (lengths[newXc][newYc] > 0) {
                        length = lengths[newXc][newYc] + 1;
                        break;
                    } else {
                        lengths[newXc][newYc] = -1;
                        indices[newXc][newYc] = ++cycle;
                        stack.push([newXc, newYc]);
                    }
                }

                const isCycle = cycX !== -1;
                let len = isCycle ? cycle : length;
                while (stack.length > 0) {
                    const [xyx, xyy] = stack.pop()!;
                    lengths[xyx][xyy] = len;
                    if (isCycle) {
                        if (xyx === cycX && xyy === cycY) {
                            isCycle = false;
                            len = length;
                        }
                    } else {
                        len++;
                    }
                }

                if (max < lengths[i][j]) {
                    max = lengths[i][j];
                    x = i + 1;
                    y = j + 1;
                }
            }
        }
    }
    console.log(`${x} ${y} ${max}`);
}

async function main(): Promise<void> {
    const ioAdapter = new FastIOAdapter();
    let count = 1;
    count = ioAdapter.nextInt();
    while (count-- > 0) {
        solve(ioAdapter);
    }
    ioAdapter.close();
}

