const MOD: number = 998244353;

let fact: number[] = [];
let invFact: number[] = [];

function binPow(a: number, b: number): number {
    let res: number = 1;
    while (b > 0) {
        a = a % MOD;
        if (b & 1) {
            res = (res * a) % MOD;
        }
        b >>= 1;
        a = (a * a) % MOD;
    }
    return res;
}

function modInverse(a: number): number {
    return binPow(a, MOD - 2);
}

function mul(a: number, b: number): number {
    return (a * b) % MOD;
}

function nCr(n: number, r: number): number {
    let res: number = mul(fact[n], invFact[r]);
    res = mul(res, invFact[n - r]);
    return res;
}

async function main() {
    const input = await readInput();
    const lines = input.split('\n');
    const n = parseInt(lines[0].trim(), 10);
