    let black = 0, white = 0;

    for (let i = 0; i < n; ++i) {
        ls[i] = lines[i + 1].trim();
        if (ls[i][0] === 'W') white++;
        if (ls[i][0] === 'B') black++;
        if (ls[i][1] === 'W') white++;
        if (ls[i][1] === 'B') black++;
        if (ls[i][0] !== '?' && ls[i][0] === ls[i][1]) {
            full = true;
        }
    }

    if (black > n || white > n) {
        console.log(0);
        return;
    }

    fact[0] = 1;
    invFact[0] = 1;
    for (let i = 1; i <= 2 * n; ++i) {
        fact[i] = mul(fact[i - 1], i);
        invFact[i] = modInverse(fact[i]);
    }

    let empty = 2 * n - black - white;
    let ans = nCr(empty, n - black);

    if (full) {
        console.log(ans);
        return;
    }

    let invalid = 1;
    let WB = true, BW = true;

    for (let i = 0; i < n; ++i) {
        if (ls[i][0] === '?' && ls[i][1] === '?') {
            invalid = mul(invalid, 2);
