class StringTokenizer {
    tokens: string[];
    index: number;

    constructor(input: string) {
        this.tokens = input.split(/\s+/);
        this.index = 0;
    }

    nextToken(): string {
        if (this.index >= this.tokens.length) {
            throw new Error("No more tokens");
        }
        return this.tokens[this.index++];
    }
}

