    const n = await sc.nextInt();
    const m = await sc.nextInt();
    const k = await sc.nextInt();

    const b_t = n % m;
    const b_p = Math.floor(n / m) + 1;
    let next_b = 1;
    let next_s = 1;

    if (b_t === 0) {
        for (let i = 0; i < k; i++) {
            for (let j = 0; j < m; j++) {
                process.stdout.write(`${Math.floor(n / m)} `);
                for (let play = 0; play < Math.floor(n / m); play++) {
                    process.stdout.write(`${next_b} `);
                    next_b = next_b === n ? 1 : next_b + 1;
                }
                process.stdout.write('\n');
            }
        }
    } else {
        for (let i = 0; i < k; i++) {
            for (let j = 0; j < b_t; j++) {
                process.stdout.write(`${b_p} `);
                for (let play = 0; play < b_p; play++) {
                    process.stdout.write(`${next_b} `);
                    next_b = next_b === n ? 1 : next_b + 1;
                }
                process.stdout.write('\n');
            }
            next_s = next_b;
            for (let j = 0; j < m - b_t; j++) {
                process.stdout.write(`${Math.floor(n / m)} `);
                for (let play = 0; play < b_p - 1; play++) {
                    process.stdout.write(`${next_s} `);
                    next_s = next_s === n ? 1 : next_s + 1;
                }
                process.stdout.write('\n');
            }
        }
    }
