const mod = 998244353

type Main struct {
	out *bufio.Writer
	in  *bufio.Scanner
	tok []string
}

func (m *Main) next() string {
	if len(m.tok) == 0 {
		m.tok = strings.Fields(m.in.Text())
		m.in.Scan()
	}
	token := m.tok[0]
	m.tok = m.tok[1:]
	return token
}

func (m *Main) ni() int {
	n, _ := strconv.Atoi(m.next())
	return n
}

func (m *Main) nl() int64 {
	n, _ := strconv.ParseInt(m.next(), 10, 64)
	return n
}

func (m *Main) na(n int) []int {
	A := make([]int, n)
	for i := 0; i < n; i++ {
		A[i] = m.ni()
	}
	return A
}

func (m *Main) solve() {
	tc := m.ni()
	for tc > 0 {
		n := m.ni()
		A := m.na(n)

		D := make([][3]int64, n+1)

		for i := n - 1; i >= 0; i-- {
			u := A[i]
			zero := int64(1) + D[u][0]
			if u+1 <= n {
				zero += D[u+1][0]
			}
			if u+2 <= n {
				zero += D[u+2][1]
			}
			one := int64(1) + D[u][1]
			if u > 1 {
				one += D[u-2][2]
			}
			two := int64(1) + D[u][2]
			if u+2 <= n {
				two += D[u+2][1]
			}

			D[u][0] = (D[u][0] + zero) % mod
			D[u][1] = (D[u][1] + one) % mod
			D[u][2] = (D[u][2] + two) % mod
		}

		ans := (D[0][0] + D[1][1]) % mod
		fmt.Fprintln(m.out, ans)
		tc--
	}
	m.out.Flush()
}

func (m *Main) dc(a int64) int {
	r := 0
	for a > 0 {
		r++
		a /= 10
	}
	return r
}

func gcd(a, b int64) int64 {
	if b == 0 {
		return a
	}
	return gcd(b, a%b)
}

func mp(a, p int64) int64 {
	r := int64(1)
	for p > 0 {
		if p&1 == 1 {
			r = (r * a) % mod
		}
		p >>= 1
		a = (a * a) % mod
	}
	return r
}

func main() {
	m := &Main{
		out: bufio.NewWriter(os.Stdout),
		in:  bufio.NewScanner(os.Stdin),
	}
	m.in.Scan()
	m.solve()
}

