func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var T int
	fmt.Fscanf(reader, "%d\n", &T)

	for T > 0 {
		T--
		var n int
		fmt.Fscanf(reader, "%d\n", &n)

		a := make([]int, n)
		flag := 0

		line, _ := reader.ReadString('\n')
		parts := strings.Fields(line)
		for i := range parts {
			num, _ := strconv.Atoi(parts[i])
			a[i] = num
			if (i+1)%2 != num%2 {
				flag = 1
			}
		}

		if flag == 1 {
			fmt.Fprintln(writer, -1)
		} else {
			var list []int
			for i := n; i > 1; i -= 2 {
				in1, in2 := 0, 0
				for j := range a {
					if a[j] == i {
						in1 = j
					} else if a[j] == i-1 {
						in2 = j
					}
				}
				reverse(a, in1)
				if in1 > in2 {
					in2 = in1 - in2
				}
				reverse(a, in2-1)
				reverse(a, in2+1)
				reverse(a, 2)
				reverse(a, i-1)
				list = append(list, in1+1, in2, in2+2, 3, i)
			}
			fmt.Fprintln(writer, len(list))
			for _, v := range list {
				fmt.Fprintf(writer, "%d ", v)
			}
			fmt.Fprintln(writer)
		}
	}
}

func reverse(a []int, r int) {
	for i := 0; i <= r/2; i++ {
		l, h := i, r-i
		a[l], a[h] = a[h], a[l]
	}
}

