const INF = 1 << 30

func main() {
	infile := bufio.NewReader(os.Stdin)
	var sb []string

	T, _ := infile.ReadString('\n')
	T = strings.TrimSpace(T)
	numTests, _ := strconv.Atoi(T)

	for i := 0; i < numTests; i++ {
		line, _ := infile.ReadString('\n')
		parts := strings.Fields(line)
		N, _ := strconv.Atoi(parts[0])
		D, _ := strconv.Atoi(parts[1])

		arr := readArr(N, infile)
		dist := make([]int, N)
		for j := range dist {
			dist[j] = INF
		}
		q := []int{}

		for j := 0; j < N; j++ {
			if arr[j] == 0 {
				dist[j] = 0
				q = append(q, j)
			}
		}

		for len(q) > 0 {
			curr := q[0]
			q = q[1:]
			next := curr + D
			if next >= N {
				next -= N
			}
			if dist[next] == INF {
				dist[next] = dist[curr] + 1
				q = append(q, next)
			}
			prev := curr - D
			if prev < 0 {
				prev += N
			}
			if dist[prev] == INF {
				dist[prev] = dist[curr] + 1
				q = append(q, prev)
			}
		}

		res := 0
		for _, x := range dist {
			if x > res {
				res = x
			}
		}
		if res == INF {
			res = -1
		}
		sb = append(sb, fmt.Sprintf("%d\n", res))
	}

	fmt.Print(strings.Join(sb, ""))
}

func readArr(N int, infile *bufio.Reader) []int {
	line, _ := infile.ReadString('\n')
	arr := make([]int, N)
	for i := 0; i < N; i++ {
		arr[i] = int(line[i]) - '0'
	}
	return arr
}

