		sc: bufio.NewScanner(os.Stdin),
		w:  bufio.NewWriter(os.Stdout),
	}
}

func (o *CF1556E) main() {
	o.sc.Scan()
	var n, q int
	fmt.Sscanf(o.sc.Text(), "%d %d", &n, &q)
	o.n = n
	o.aa = make([]int64, n)
	o.tmax = make([]int64, 2*n)
	o.tmin = make([]int64, 2*n)

	for i := 0; i < n; i++ {
		o.sc.Scan()
		var x int
		fmt.Sscanf(o.sc.Text(), "%d", &x)
		o.aa[i] = -int64(x)
	}

	for i := 0; i < n; i++ {
		o.sc.Scan()
		var x int
		fmt.Sscanf(o.sc.Text(), "%d", &x)
		o.aa[i] += int64(x)
	}

	for i := 1; i < n; i++ {
		o.aa[i] += o.aa[i-1]
	}

	o.build()

	for i := 0; i < q; i++ {
		o.sc.Scan()
		var l, r int
		fmt.Sscanf(o.sc.Text(), "%d %d", &l, &r)
		l--
		r--
		var a int64
		if l > 0 {
			a = o.aa[l-1]
		}
		b := o.aa[r]
		if a != b || o.qmin(l, r) != a {
			fmt.Fprintln(o.w, -1)
		} else {
			fmt.Fprintln(o.w, o.qmax(l, r)-a)
		}
	}
}

func (o *CF1556E) build() {
	for i := 0; i < o.n; i++ {
		o.tmax[o.n+i] = o.aa[i]
		o.tmin[o.n+i] = o.aa[i]
	}
	for i := o.n - 1; i > 0; i-- {
		o.tmax[i] = max(o.tmax[i<<1], o.tmax[i<<1|1])
		o.tmin[i] = min(o.tmin[i<<1], o.tmin[i<<1|1])
	}
}

func (o *CF1556E) qmax(l, r int) int64 {
	ans := -INF
	l += o.n
	r += o.n
	for l <= r {
		if l&1 == 1 {
			ans = max(ans, o.tmax[l])
			l++
		}
		if r&1 == 0 {
			ans = max(ans, o.tmax[r])
			r--
		}
		l >>= 1
		r >>= 1
	}
	return ans
}

func (o *CF1556E) qmin(l, r int) int64 {
	ans := INF
	l += o.n
	r += o.n
	for l <= r {
		if l&1 == 1 {
			ans = min(ans, o.tmin[l])
			l++
		}
		if r&1 == 0 {
			ans = min(ans, o.tmin[r])
			r--
		}
		l >>= 1
		r >>= 1
	}
	return ans
}

