func solve(io *FastIOAdapter) {
	n := io.nextInt()
	m := io.nextInt()
	a := make([][]rune, n)
	for i := range a {
		a[i] = []rune(io.next())
	}
	lengths := make([][]int, n)
	indices := make([][]int, n)
	for i := range lengths {
		lengths[i] = make([]int, m)
		indices[i] = make([]int, m)
	}
	var x, y, max int
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if lengths[i][j] == 0 {
				stack := [][]int{{i, j}}
				lengths[i][j] = -1
				indices[i][j] = 0
				length := 1
				cycle := 0
				var cycX, cycY int
				for {
					xy := stack[len(stack)-1]
					xc, yc := xy[0], xy[1]
					switch a[xc][yc] {
					case 'U':
						xc--
					case 'D':
						xc++
					case 'L':
						yc--
					default:
						yc++
					}
					if xc < 0 || xc >= n || yc < 0 || yc >= m {
						break
					} else if lengths[xc][yc] < 0 {
						cycle -= indices[xc][yc] - 1
						length = cycle + 1
						cycX, cycY = xc, yc
						break
					} else if lengths[xc][yc] > 0 {
						length = lengths[xc][yc] + 1
						break
					} else {
						lengths[xc][yc] = -1
						indices[xc][yc] = cycle + 1
						stack = append(stack, []int{xc, yc})
					}
				}
				isCycle := cycX != -1
				var len int
				if isCycle {
					len = cycle
				} else {
					len = length
				}
				for len(stack) > 0 {
					xy := stack[len(stack)-1]
					stack = stack[:len(stack)-1]
					lengths[xy[0]][xy[1]] = len
					if isCycle {
						if xy[0] == cycX && xy[1] == cycY {
							isCycle = false
							len = length
						}
					} else {
						len++
					}
				}
				if max < lengths[i][j] {
					max = lengths[i][j]
					x, y = i+1, j+1
				}
			}
		}
	}
	fmt.Fprintln(io.out, x, y, max)
}

func main() {
	ioAdapter := &FastIOAdapter{br: bufio.NewReader(os.Stdin), out: os.Stdout}
	count := ioAdapter.nextInt()
	for count > 0 {
		solve(ioAdapter)
		count--
	}
}

type FastIOAdapter struct {
	br  *bufio.Reader
	out *os.File
	st  strings.Builder
}

func (io *FastIOAdapter) next() string {
	if io.st.Len() == 0 {
		line, _ := io.br.ReadString('\n')
		io.st.WriteString(line)
	}
	token := strings.TrimSpace(io.st.String())
	io.st.Reset()
	return token
}

func (io *FastIOAdapter) nextInt() int {
	s := io.next()
	var n int
	fmt.Sscanf(s, "%d", &n)
	return n
}

func (io *FastIOAdapter) readArray(n int) []int {
	arr := make([]int, n)
	for i := range arr {
		arr[i] = io.nextInt()
	}
	return arr
}

func (io *FastIOAdapter) nextLine() string {
	line, _ := io.br.ReadString('\n')
	return strings.TrimSpace(line)
}

