        private void ReadNextLine()
        {
            string line = reader.ReadLine();
            if (line != null)
            {
                tokens = line.Split(' ');
                tokenIndex = 0;
            }
        }

        public string Next()
        {
            while (tokenIndex >= tokens.Length)
            {
                ReadNextLine();
            }
            return tokens[tokenIndex++];
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }

        public long NextLong()
        {
            return long.Parse(Next());
        }

        public double NextDouble()
        {
            return double.Parse(Next());
        }

        public string NextLine()
        {
            ReadNextLine();
            return string.Join(" ", tokens);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Text;

class Program
{
    const int INF = int.MaxValue / 2;

    static void Main(string[] args)
    {
        var reader = new StreamReader(Console.OpenStandardInput());
        var tokenizer = new StringTokenizer(reader.ReadLine());
        int T = int.Parse(tokenizer.NextToken());
        var sb = new StringBuilder();
        while (T-- > 0)
        {
            tokenizer = new StringTokenizer(reader.ReadLine());
            int N = int.Parse(tokenizer.NextToken());
            int D = int.Parse(tokenizer.NextToken());
            int[] arr = ReadArr(N, reader, tokenizer);
            int[] dist = new int[N];
            Array.Fill(dist, INF);
            var q = new Queue<int>();
            for (int i = 0; i < N; i++)
                if (arr[i] == 0)
                {
                    dist[i] = 0;
                    q.Enqueue(i);
                }
            while (q.Count > 0)
            {
                int curr = q.Dequeue();
                int next = curr + D;
                if (next >= N)
                    next -= N;
                if (dist[next] == INF)
                {
                    dist[next] = dist[curr] + 1;
                    q.Enqueue(next);
                }
            }
            int res = 0;
            foreach (int x in dist)
                res = Math.Max(res, x);
            if (res == INF)
                res = -1;
            sb.Append(res + "\n");
        }
        Console.Write(sb.ToString());
    }

    static int[] ReadArr(int N, StreamReader infile, StringTokenizer st)
    {
        int[] arr = new int[N];
        st = new StringTokenizer(infile.ReadLine());
        for (int i = 0; i < N; i++)
            arr[i] = st.NextToken()[0] - '0';
        return arr;
    }
}

class StringTokenizer
{
    private readonly string _input;
    private int _index;

    public StringTokenizer(string input)
    {
        _input = input;
        _index = 0;
    }

    public string NextToken()
    {
        while (_index < _input.Length && char.IsWhiteSpace(_input[_index]))
            _index++;
        if (_index >= _input.Length)
            throw new InvalidOperationException("No more tokens");
        int start = _index;
        while (_index < _input.Length && !char.IsWhiteSpace(_input[_index]))
            _index++;
        return _input.Substring(start, _index - start);
    }
}

