class Program : StreamWriter
{
    const long INF = 0x3f3f3f3f3f3f3f3fL;
    long[] aa, tmax, tmin; int n;

    public Program() : base(Console.OpenStandardOutput()) { }

    void Build()
    {
        tmax = new long[n * 2];
        tmin = new long[n * 2];
        for (int i = 0; i < n; i++)
            tmax[n + i] = tmin[n + i] = aa[i];
        for (int i = n - 1; i > 0; i--)
        {
            tmax[i] = Math.Max(tmax[i << 1], tmax[(i << 1) | 1]);
            tmin[i] = Math.Min(tmin[i << 1], tmin[(i << 1) | 1]);
        }
    }

    long QMax(int l, int r)
    {
        long ans = -INF;
        for (l += n, r += n; l <= r; l >>= 1, r >>= 1)
        {
            if ((l & 1) == 1)
                ans = Math.Max(ans, tmax[l++]);
            if ((r & 1) == 0)
                ans = Math.Max(ans, tmax[r--]);
        }
        return ans;
    }

    long QMin(int l, int r)
    {
        long ans = INF;
        for (l += n, r += n; l <= r; l >>= 1, r >>= 1)
        {
            if ((l & 1) == 1)
                ans = Math.Min(ans, tmin[l++]);
            if ((r & 1) == 0)
                ans = Math.Min(ans, tmin[r--]);
        }
        return ans;
    }

    void Main()
    {
        var sc = new StreamReader(Console.OpenStandardInput());
        string[] input = sc.ReadLine().Split(' ');
        n = int.Parse(input[0]);
        int q = int.Parse(input[1]);

        aa = new long[n];
        input = sc.ReadLine().Split(' ');
        for (int i = 0; i < n; i++)
            aa[i] = -int.Parse(input[i]);

        input = sc.ReadLine().Split(' ');
        for (int i = 0; i < n; i++)
            aa[i] += int.Parse(input[i]);

        for (int i = 1; i < n; i++)
            aa[i] += aa[i - 1];

        Build();

        while (q-- > 0)
        {
            input = sc.ReadLine().Split(' ');
            int l = int.Parse(input[0]) - 1;
            int r = int.Parse(input[1]) - 1;

            long a = l == 0 ? 0 : aa[l - 1];
            long b = aa[r];

            WriteLine(a != b || QMin(l, r) != a ? -1 : QMax(l, r) - a);
        }
    }

    static void Main(string[] args)
    {
        using (var program = new Program())
        {
            program.Main();
        }
    }
}

using System;
using System.Collections.Generic;

class Program
{
    private static void Solve(FastIOAdapter io)
    {
        int n = io.NextInt();
        int m = io.NextInt();
        char[][] a = new char[n][];
        for (int i = 0; i < n; i++)
        {
            a[i] = io.Next().ToCharArray();
        }
        int[,] lengths = new int[n, m];
        int[,] indices = new int[n, m];
        int x = 0, y = 0;
        int max = 0;
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < m; j++)
            {
                if (lengths[i, j] == 0) // we did not check this
                {
                    Stack<int[]> stack = new Stack<int[]>();
                    stack.Push(new int[] { i, j });
                    lengths[i, j] = -1; // we were here
                    indices[i, j] = 0;
                    int length = 1;
                    int cycle = 0;
                    int cycX = -1, cycY = -1;
                    while (true)
                    {
                        int[] xy = stack.Peek();
                        int xc = xy[0], yc = xy[1];
                        if (a[xc][yc] == 'U')
                        {
                            xc--;
                        }
                        else if (a[xc][yc] == 'D')
                        {
                            xc++;
                        }
                        else if (a[xc][yc] == 'L')
                        {
                            yc--;
                        }
                        else yc++;
                        if (xc < 0 || xc >= n || yc < 0 || yc >= m)
                        {
                            break;
                        }
                        else if (lengths[xc, yc] < 0)
                        {
                            cycle -= indices[xc, yc] - 1;
                            length = cycle + 1;
                            cycX = xc;
                            cycY = yc;
                            break;
                        }
                        else if (lengths[xc, yc] > 0)
                        {
                            length = lengths[xc, yc] + 1;
                            break;
                        }
                        else
                        {
                            lengths[xc, yc] = -1;
                            indices[xc, yc] = ++cycle;
                            stack.Push(new int[] { xc, yc });
                        }
                    }
                    bool isCycle = cycX != -1;
                    int len = isCycle ? cycle : length;
                    while (stack.Count > 0)
                    {
                        int[] xy = stack.Pop();
                        lengths[xy[0], xy[1]] = len;
                        if (isCycle)
                        {
                            if (xy[0] == cycX && xy[1] == cycY)
                            {
                                isCycle = false;
                                len = length;
                            }
                        }
                        else len++;
                    }
                    if (max < lengths[i, j])
                    {
                        max = lengths[i, j];
                        x = i + 1;
                        y = j + 1;
                    }
                }
            }
        }
        io.Out.WriteLine($"{x} {y} {max}");
    }

    static void Main(string[] args)
    {
        using (FastIOAdapter ioAdapter = new FastIOAdapter())
        {
            int count = 1;
            count = ioAdapter.NextInt();
            while (count-- > 0)
            {
                Solve(ioAdapter);
            }
        }
    }

    class FastIOAdapter : IDisposable
    {
        private readonly System.IO.StreamReader br;
        public System.IO.TextWriter Out { get; }
        private string[] st;
        private int index;

        public FastIOAdapter()
        {
            br = new System.IO.StreamReader(Console.OpenStandardInput());
            Out = Console.Out;
            st = new string[0];
            index = 0;
        }

        private void ReadLine()
        {
            try
            {
                st = br.ReadLine().Split(' ');
                index = 0;
            }
            catch (System.IO.IOException)
            {
                // Handle exception if needed
            }
        }

        public string Next()
        {
            if (index >= st.Length)
            {
                ReadLine();
            }
            return st[index++];
        }

        public string NextLine()
        {
            try
            {
                return br.ReadLine();
            }
            catch (System.IO.IOException)
            {
                return null;
            }
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }

        public long NextLong()
        {
            return long.Parse(Next());
        }

        public void Dispose()
        {
            Out.Flush();
            br.Close();
        }
    }
}

