using System;

class Program
{
    private static readonly System.IO.StreamReader br = new System.IO.StreamReader(Console.OpenStandardInput());
    private static readonly System.IO.TextWriter pw = Console.Out;

    private const long Mod = 998244353;
    private static long[] fact;
    private static long[] invFact;

    private static long BinPow(long a, long b)
    {
        long res = 1;
        while (b > 0)
        {
            a = a % Mod;
            if ((b & 1) == 1)
            {
                res = (res * a) % Mod;
            }
            b >>= 1;
            a = (a * a) % Mod;
        }
        return res;
    }

    private static long ModInverse(long a)
    {
        return BinPow(a, Mod - 2);
    }

    private static long Mul(long a, long b)
    {
        return (a * b) % Mod;
    }

    private static long NCr(int n, int r)
    {
        long res = Mul(fact[n], invFact[r]);
        res = Mul(res, invFact[n - r]);
        return res;
    }

    public static void Main(string[] args)
    {
        int n = int.Parse(br.ReadLine());
        string[] ls = new string[n];
        bool full = false;
        int black = 0, white = 0;
        for (int i = 0; i < n; ++i)
        {
            ls[i] = br.ReadLine();
            if (ls[i][0] == 'W')
                white++;
            if (ls[i][0] == 'B')
                black++;
            if (ls[i][1] == 'W')
                white++;
            if (ls[i][1] == 'B')
                black++;
            if (ls[i][0] != '?' && ls[i][0] == ls[i][1])
            {
                full = true;
            }
        }
        if (black > n || white > n)
        {
            pw.WriteLine(0);
            return;
        }

        fact = new long[2 * n + 1];
        invFact = new long[2 * n + 1];
        fact[0] = 1;
        invFact[0] = 1;
        for (int i = 1; i <= 2 * n; ++i)
        {
            fact[i] = Mul(fact[i - 1], i);
            invFact[i] = ModInverse(fact[i]);
        }
        int empty = 2 * n - black - white;
        long ans = NCr(empty, n - black);
        if (full)
        {
            pw.WriteLine(ans);
            return;
        }
