use std::io::{self, BufRead, Write};

const MOD: i64 = 998244353;

struct Main {
    out: io::StdoutLock<'static>,
    in_buf: String,
    tok: Vec<String>,
}

impl Main {
    fn new() -> Self {
        let stdout = io::stdout();
        Main {
            out: stdout.lock(),
            in_buf: String::new(),
            tok: Vec::new(),
        }
    }

    fn next(&mut self) -> io::Result<String> {
        if self.tok.is_empty() {
            self.in_buf.clear();
            io::stdin().read_line(&mut self.in_buf)?;
            self.tok = self.in_buf.trim().split_whitespace().map(|s| s.to_string()).collect();
        }
        Ok(self.tok.remove(0))
    }

    fn ni(&mut self) -> io::Result<i32> {
        self.next()?.parse().map_err(|e| io::Error::new(io::ErrorKind::Other, e))
    }

    fn nl(&mut self) -> io::Result<i64> {
        self.next()?.parse().map_err(|e| io::Error::new(io::ErrorKind::Other, e))
    }

    fn na(&mut self, n: usize) -> io::Result<Vec<i32>> {
        (0..n).map(|_| self.ni()).collect()
    }

    fn solve(&mut self) -> io::Result<()> {
        let tc = self.ni()?;
        for _ in 0..tc {
            let n = self.ni()? as usize;
            let a = self.na(n)?;

            let mut d = vec![vec![0_i64; 3]; n + 1];

            for i in (0..n).rev() {
                let u = a[i] as usize;
                let zero = 1 + d[u][0];
                let zero = if u + 1 <= n { zero + d[u + 1][0] } else { zero };
                let zero = if u + 2 <= n { zero + d[u + 2][1] } else { zero };
                let one = 1 + d[u][1];
                let one = if u > 1 { one + d[u - 2][2] } else { one };
                let two = 1 + d[u][2];
                let two = if u + 2 <= n { two + d[u + 2][1] } else { two };

                d[u][0] = (d[u][0] + zero) % MOD;
                d[u][1] = (d[u][1] + one) % MOD;
                d[u][2] = (d[u][2] + two) % MOD;
            }

            let ans = (d[0][0] + d[1][1]) % MOD;
            writeln!(self.out, "{}", ans)?;
        }
        self.out.flush()?;
        Ok(())
    }

    fn dc(&self, mut a: i64) -> usize {
        let mut r = 0;
        while a > 0 {
            r += 1;
            a /= 10;
        }
        r
    }

    fn gcd(mut a: i32, mut b: i32) -> i32 {
        while b != 0 {
            let t = b;
            b = a % b;
            a = t;
        }
        a.abs()
    }

    fn gcdl(mut a: i64, mut b: i64) -> i64 {
        while b != 0 {
            let t = b;
            b = a % b;
            a = t;
        }
        a.abs()
    }

    fn mp(&self, mut a: i64, mut p: i64) -> i64 {
        let mut r = 1;
        while p > 0 {
            if p & 1 == 1 {
                r = (r * a) % MOD;
            }
            p >>= 1;
            a = (a * a) % MOD;
        }
        r
    }
}

