const INF: usize = usize::MAX / 2;

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let t: usize = lines.next().unwrap()?.parse().map_err(|_| io::Error::new(io::ErrorKind::Other, "Parse error"))?;

    let mut output = String::new();
    for _ in 0..t {
        let line = lines.next().unwrap()?;
        let mut parts = line.split_whitespace();
        let n: usize = parts.next().unwrap().parse().map_err(|_| io::Error::new(io::ErrorKind::Other, "Parse error"))?;
        let d: usize = parts.next().unwrap().parse().map_err(|_| io::Error::new(io::ErrorKind::Other, "Parse error"))?;

        let arr = read_arr(n, &mut lines)?;
        let mut dist = vec![INF; n];
        let mut q = std::collections::VecDeque::new();

        for i in 0..n {
            if arr[i] == b'0' {
                dist[i] = 0;
                q.push_back(i);
            }
        }

        while let Some(curr) = q.pop_front() {
            let next = (curr + d) % n;
            if dist[next] == INF {
                dist[next] = dist[curr] + 1;
                q.push_back(next);
            }
        }

        let res = *dist.iter().max().unwrap_or(&INF);
        let res = if res == INF { -1 } else { res as isize };
        output.push_str(&format!("{}\n", res));
    }

    print!("{}", output);
    Ok(())
}

fn read_arr(n: usize, lines: &mut io::Lines<io::StdinLock>) -> io::Result<Vec<u8>> {
    let line = lines.next().unwrap()?;
    let arr: Vec<u8> = line.bytes().collect();
    if arr.len() != n {
        return Err(io::Error::new(io::ErrorKind::Other, "Array length mismatch"));
    }
    Ok(arr)
}

