fn solve(n: usize, k: usize, mut x: i64, s: &str) {
    let mut res = String::new();
    x -= 1;
    let chars: Vec<char> = s.chars().collect();
    let mut i = n - 1;

    while i < chars.len() {
        if chars[i] == 'a' {
            res.push('a');
        } else {
            let mut count = 1;
            while i >= count && chars[i] == chars[i - count] {
                count += 1;
            }
            let base = (count * k) as i64 + 1;
            for _ in 0..x % base {
                res.push('b');
            }
            x /= base;
            i -= count;
        }
        if i > 0 {
            i -= 1;
        } else {
            break;
        }
    }

    res.chars().rev().for_each(|c| print!("{}", c));
    println!();
}

