const INF: i64 = 0x3f3f3f3f3f3f3f3f;

struct CF1556E {
    aa: Vec<i64>,
    tmax: Vec<i64>,
    tmin: Vec<i64>,
    n: usize,
}

impl CF1556E {
    fn new() -> Self {
        let mut sc = io::stdin().lock().lines();
        let line = sc.next().unwrap().unwrap();
        let mut parts = line.split_whitespace();
        let n: usize = parts.next().unwrap().parse().unwrap();
        let q: usize = parts.next().unwrap().parse().unwrap();

        let mut aa = vec![0; n];
        for i in 0..n {
            aa[i] = -parts.next().unwrap().parse::<i64>().unwrap();
        }
        for i in 0..n {
            aa[i] += parts.next().unwrap().parse::<i64>().unwrap();
        }
        for i in 1..n {
            aa[i] += aa[i - 1];
        }

        let mut tmax = vec![0; n * 2];
        let mut tmin = vec![0; n * 2];
        for i in 0..n {
            tmax[n + i] = aa[i];
            tmin[n + i] = aa[i];
        }
        for i in (1..n).rev() {
            tmax[i] = tmax[i << 1].max(tmax[(i << 1) | 1]);
            tmin[i] = tmin[i << 1].min(tmin[(i << 1) | 1]);
        }

        CF1556E { aa, tmax, tmin, n }
    }

    fn build(&mut self) {
        for i in (1..self.n).rev() {
            self.tmax[i] = self.tmax[i << 1].max(self.tmax[(i << 1) | 1]);
            self.tmin[i] = self.tmin[i << 1].min(self.tmin[(i << 1) | 1]);
        }
    }

    fn qmax(&self, mut l: usize, mut r: usize) -> i64 {
        let mut ans = -INF;
        l += self.n;
        r += self.n;
        while l <= r {
            if (l & 1) == 1 {
                ans = ans.max(self.tmax[l]);
                l += 1;
            }
            if (r & 1) == 0 {
                ans = ans.max(self.tmax[r]);
                r -= 1;
            }
            l >>= 1;
            r >>= 1;
        }
        ans
    }

    fn qmin(&self, mut l: usize, mut r: usize) -> i64 {
        let mut ans = INF;
        l += self.n;
        r += self.n;
        while l <= r {
            if (l & 1) == 1 {
                ans = ans.min(self.tmin[l]);
                l += 1;
            }
            if (r & 1) == 0 {
                ans = ans.min(self.tmin[r]);
                r -= 1;
            }
            l >>= 1;
            r >>= 1;
        }
        ans
    }

    fn main(&mut self) {
        let mut sc = io::stdin().lock().lines();
        for _ in 0..self.n {
            sc.next();
        }
        let q: usize = sc.next().unwrap().unwrap().split_whitespace().next().unwrap().parse().unwrap();

        for _ in 0..q {
            let line = sc.next().unwrap().unwrap();
            let mut parts = line.split_whitespace();
            let l: usize = parts.next().unwrap().parse::<usize>().unwrap() - 1;
            let r: usize = parts.next().unwrap().parse::<usize>().unwrap() - 1;
            let a = if l == 0 { 0 } else { self.aa[l - 1] };
            let b = self.aa[r];
            if a != b || self.qmin(l, r) != a {
                println!("-1");
            } else {
                println!("{}", self.qmax(l, r) - a);
            }
        }
    }
}

