use std::io::{self, BufRead, Write};

struct FastIOAdapter {
    reader: io::BufReader<io::Stdin>,
    writer: io::BufWriter<io::Stdout>,
    buffer: String,
}

impl FastIOAdapter {
    fn new() -> Self {
        FastIOAdapter {
            reader: io::BufReader::new(io::stdin()),
            writer: io::BufWriter::new(io::stdout()),
            buffer: String::new(),
        }
    }

    fn next(&mut self) -> Option<String> {
        let mut line = String::new();
        if self.reader.read_line(&mut line).unwrap() == 0 {
            return None;
        }
        self.buffer.clear();
        self.buffer.push_str(line.trim_end());
        Some(self.buffer.clone())
    }

    fn next_int(&mut self) -> i32 {
        self.next().unwrap().parse().unwrap()
    }

    fn read_array(&mut self, n: usize) -> Vec<i32> {
        (0..n).map(|_| self.next_int()).collect()
    }
}

impl Drop for FastIOAdapter {
    fn drop(&mut self) {
        self.writer.flush().unwrap();
    }
}

fn solve(io: &mut FastIOAdapter) {
    let n = io.next_int() as usize;
    let m = io.next_int() as usize;
    let mut a = vec![vec![' '; m]; n];
    for i in 0..n {
        if let Some(line) = io.next() {
            let chars: Vec<char> = line.chars().collect();
            for j in 0..m {
                a[i][j] = chars[j];
            }
        }
    }

    let mut lengths = vec![vec![0; m]; n];
    let mut indices = vec![vec![0; m]; n];
    let mut max_length = 0;
    let mut max_x = 0;
    let mut max_y = 0;

    for i in 0..n {
        for j in 0..m {
            if lengths[i][j] == 0 {
                let mut stack = vec![(i, j)];
                lengths[i][j] = -1;
                indices[i][j] = 0;
                let mut length = 1;
                let mut cycle = 0;
                let mut cyc_x = None;
                let mut cyc_y = None;

                while let Some(&(xc, yc)) = stack.last() {
                    let (mut new_xc, mut new_yc) = (xc as isize, yc as isize);
                    match a[xc][yc] {
                        'U' => new_xc -= 1,
                        'D' => new_xc += 1,
                        'L' => new_yc -= 1,
                        _ => new_yc += 1,
                    }

                    if new_xc < 0 || new_xc >= n as isize || new_yc < 0 || new_yc >= m as isize {
                        break;
                    } else if lengths[new_xc as usize][new_yc as usize] < 0 {
                        cycle -= indices[new_xc as usize][new_yc as usize] - 1;
                        length = cycle + 1;
                        cyc_x = Some(new_xc as usize);
                        cyc_y = Some(new_yc as usize);
                        break;
                    } else if lengths[new_xc as usize][new_yc as usize] > 0 {
                        length = lengths[new_xc as usize][new_yc as usize] + 1;
                        break;
                    } else {
                        lengths[new_xc as usize][new_yc as usize] = -1;
                        indices[new_xc as usize][new_yc as usize] = cycle + 1;
                        stack.push((new_xc as usize, new_yc as usize));
                        cycle += 1;
                    }
                }

                let is_cycle = cyc_x.is_some();
                let len = if is_cycle { cycle } else { length };
                while let Some((xy_x, xy_y)) = stack.pop() {
                    lengths[xy_x][xy_y] = len;
                    if is_cycle && Some(xy_x) == cyc_x && Some(xy_y) == cyc_y {
                        break;
                    }
                }

                if max_length < lengths[i][j] {
                    max_length = lengths[i][j];
                    max_x = i + 1;
                    max_y = j + 1;
                }
            }
        }
    }

    writeln!(io.writer, "{} {} {}", max_x, max_y, max_length).unwrap();
}

fn main() {
    let mut io = FastIOAdapter::new();
    let count = io.next_int();
    for _ in 0..count {
        solve(&mut io);
    }
}

