const MOD: i64 = 998244353;

fn bin_pow(mut a: i64, mut b: i64) -> i64 {
    let mut res = 1;
    while b > 0 {
        a %= MOD;
        if b & 1 == 1 {
            res = (res * a) % MOD;
        }
        b >>= 1;
        a = (a * a) % MOD;
    }
    res
}

fn mod_inverse(a: i64) -> i64 {
    bin_pow(a, MOD - 2)
}

fn mul(a: i64, b: i64) -> i64 {
    (a * b) % MOD
}

fn n_cr(n: usize, r: usize, fact: &[i64], inv_fact: &[i64]) -> i64 {
    let res = mul(fact[n], inv_fact[r]);
    mul(res, inv_fact[n - r])
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let n: usize = lines.next().unwrap().expect("Failed to read line").trim().parse().unwrap();
