    let mut white = 0;

    for _ in 0..n {
        let line = lines.next().unwrap().expect("Failed to read line").trim().to_string();
        ls.push(line.clone());
        if line.chars().nth(0) == Some('W') {
            white += 1;
        }
        if line.chars().nth(0) == Some('B') {
            black += 1;
        }
        if line.chars().nth(1) == Some('W') {
            white += 1;
        }
        if line.chars().nth(1) == Some('B') {
            black += 1;
        }
    }

    if black > n || white > n {
        println!("0");
        return;
    }

    let mut fact = vec![0; 2 * n + 1];
    let mut inv_fact = vec![0; 2 * n + 1];
    fact[0] = 1;
    inv_fact[0] = 1;

    for i in 1..=2 * n {
        fact[i] = mul(fact[i - 1], i as i64);
        inv_fact[i] = mod_inverse(fact[i]);
    }

    let empty = 2 * n - black - white;
    let mut ans = n_cr(empty, n - black, &fact, &inv_fact);

    let full = ls.iter().any(|line| line.chars().nth(0) != Some('?') && line.chars().nth(0) == line.chars().nth(1));
    if full {
        println!("{}", ans);
        return;
    }

    let mut invalid = 1;
    let mut wb = true;
    let mut bw = true;

    for line in &ls {
        if line.chars().nth(0) == Some('?') && line.chars().nth(1) == Some('?') {
            invalid = mul(invalid, 2);
        }
        if line.chars().nth(0) == Some('B') || line.chars().nth(1) == Some('W') {
            wb = false;
        }
        if line.chars().nth(0) == Some('W') || line.chars().nth(1) == Some('B') {
            bw = false;
        }
    }

    if wb {
        invalid -= 1;
    }
    if bw {
        invalid -= 1;
    }

    ans = (ans - invalid + MOD) % MOD;
    println!("{}", ans);
}

