use std::io::{self, BufRead, Write};

struct MyScanner {
    reader: io::BufReader<io::Stdin>,
    buffer: String,
}

impl MyScanner {
    fn new() -> Self {
        MyScanner {
            reader: io::BufReader::new(io::stdin()),
            buffer: String::new(),
        }
    }

    fn next(&mut self) -> Option<String> {
        if let Some(pos) = self.buffer.find(' ') {
            let token = self.buffer[..pos].to_string();
            self.buffer = self.buffer[pos + 1..].to_string();
            Some(token)
        } else {
            self.buffer.clear();
            let mut line = String::new();
            self.reader.read_line(&mut line).unwrap();
            line.pop(); // Remove newline character
            if line.is_empty() {
                None
            } else {
                Some(line)
            }
        }
    }

    fn next_int(&mut self) -> i32 {
        self.next().unwrap().parse().unwrap()
    }
}

fn solve(scanner: &mut MyScanner, writer: &mut io::StdoutLock) {
    let n = scanner.next_int();
    let m = scanner.next_int();
    let k = scanner.next_int();

    let b_t = n % m;
    let b_p = n / m + 1;
    let mut next_b = 1;

    if b_t == 0 {
        for _ in 0..k {
            for _ in 0..m {
                write!(writer, "{} ", n / m).unwrap();
                for _ in 0..(n / m) {
                    write!(writer, "{} ", next_b).unwrap();
                    next_b = if next_b == n { 1 } else { next_b + 1 };
                }
                writeln!(writer).unwrap();
            }
        }
    } else {
        for _ in 0..k {
            for _ in 0..b_t {
                write!(writer, "{} ", n / m + 1).unwrap();
                for _ in 0..b_p {
                    write!(writer, "{} ", next_b).unwrap();
                    next_b = if next_b == n { 1 } else { next_b + 1 };
                }
                writeln!(writer).unwrap();
            }
            let mut next_s = next_b;
            for _ in 0..(m - b_t) {
                write!(writer, "{} ", n / m).unwrap();
                for _ in 0..(b_p - 1) {
                    write!(writer, "{} ", next_s).unwrap();
                    next_s = if next_s == n { 1 } else { next_s + 1 };
                }
                writeln!(writer).unwrap();
            }
        }
    }
    writeln!(writer).unwrap();
}

fn main() {
    let mut scanner = MyScanner::new();
    let stdout = io::stdout();
    let mut writer = stdout.lock();

    let n = scanner.next_int();
    for _ in 0..n {
        solve(&mut scanner, &mut writer);
    }
}

