class Main {
public:
    std::ostream& out = std::cout;
    std::istream& in = std::cin;
    std::istringstream tok;
    std::string next() {
        if (tok.eof()) {
            std::string line;
            std::getline(in, line);
            tok.str(line);
            tok.clear();
        }
        std::string token;
        tok >> token;
        return token;
    }
    int ni() {
        return std::stoi(next());
    }
    long long nl() {
        return std::stoll(next());
    }
    std::vector<int> na(int n) {
        std::vector<int> A(n);
        for (int i = 0; i < n; ++i) {
            A[i] = ni();
        }
        return A;
    }

    const long long mod = 998244353;

    void solve() {
        int tc = ni();
        while (tc--) {
            int n = ni();
            std::vector<int> A = na(n);

            std::vector<std::vector<long long>> D(n + 1, std::vector<long long>(3, 0));

            for (int i = n - 1; i >= 0; --i) {
                int u = A[i];
                long long zero = 1LL + D[u][0];
                if (u + 1 <= n) zero += D[u + 1][0];
                if (u + 2 <= n) zero += D[u + 2][1];
                long long one = 1LL + D[u][1];
                if (u > 1) one += D[u - 2][2];
                long long two = 1LL + D[u][2];
                if (u + 2 <= n) two += D[u + 2][1];

                D[u][0] = (D[u][0] + zero) % mod;
                D[u][1] = (D[u][1] + one) % mod;
                D[u][2] = (D[u][2] + two) % mod;
            }

            long long ans = (D[0][0] + D[1][1]) % mod;
            out << ans << '\n';
        }
    }

    int dc(long long a) {
        int r = 0;
        while (a > 0) {
            ++r;
            a /= 10;
        }
        return r;
    }

    int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    long long gcd(long long a, long long b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    long long mp(long long a, long long p) {
        long long r = 1;
        while (p > 0) {
            if (p & 1) r = (r * a) % mod;
            p >>= 1;
            a = (a * a) % mod;
        }
        return r;
    }
};

