const int INF = INT_MAX / 2;

int readInt(std::istream& is) {
    std::string token;
    is >> token;
    return std::stoi(token);
}

std::vector<int> readArr(int N, std::istream& infile) {
    std::vector<int> arr(N);
    std::string line;
    std::getline(infile, line);
    for (int i = 0; i < N; ++i) {
        arr[i] = line[i] - '0';
    }
    return arr;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int T = readInt(std::cin);
    while (T--) {
        int N = readInt(std::cin);
        int D = readInt(std::cin);
        std::vector<int> arr = readArr(N, std::cin);
        std::vector<int> dist(N, INF);
        std::queue<int> q;

        for (int i = 0; i < N; ++i) {
            if (arr[i] == 0) {
                dist[i] = 0;
                q.push(i);
            }
        }

        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            int next = (curr + D) % N;
            if (dist[next] == INF) {
                dist[next] = dist[curr] + 1;
                q.push(next);
            }
        }

        int res = *std::max_element(dist.begin(), dist.end());
        if (res == INF) {
            res = -1;
        }
        std::cout << res << "\n";
    }

    return 0;
}

