class FastIOAdapter {
public:
    std::istream& in;
    std::ostream& out;
    std::istringstream iss;

    FastIOAdapter() : in(std::cin), out(std::cout) {}

    std::string next() {
        if (iss.peek() == EOF) {
            std::string line;
            std::getline(in, line);
            iss.str(line);
            iss.clear();
        }
        std::string token;
        iss >> token;
        return token;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long long nextLong() {
        return std::stoll(next());
    }

    std::vector<int> readArray(int n) {
        std::vector<int> arr(n);
        for (int i = 0; i < n; ++i) {
            arr[i] = nextInt();
        }
        return arr;
    }

    std::vector<long long> readArrayLong(int n) {
        std::vector<long long> arr(n);
        for (int i = 0; i < n; ++i) {
            arr[i] = nextLong();
        }
        return arr;
    }
};

void solve(FastIOAdapter& io) {
    int n = io.nextInt();
    int m = io.nextInt();
    std::vector<std::string> a(n);
    for (int i = 0; i < n; ++i) {
        a[i] = io.next();
    }
    std::vector<std::vector<int>> lengths(n, std::vector<int>(m, 0));
    std::vector<std::vector<int>> indices(n, std::vector<int>(m, 0));
    int x = 0, y = 0;
    int max_length = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (lengths[i][j] == 0) { // we did not check this
                std::stack<std::pair<int, int>> stack;
                stack.emplace(i, j);
                lengths[i][j] = -1; // we were here
                indices[i][j] = 0;
                int length = 1;
                int cycle = 0;
                int cycX = -1, cycY = -1;
                while (true) {
                    auto [xc, yc] = stack.top();
                    if (a[xc][yc] == 'U') {
                        --xc;
                    } else if (a[xc][yc] == 'D') {
                        ++xc;
                    } else if (a[xc][yc] == 'L') {
                        --yc;
                    } else {
                        ++yc;
                    }
                    if (xc < 0 || xc >= n || yc < 0 || yc >= m) {
                        break;
                    } else if (lengths[xc][yc] < 0) {
                        cycle -= indices[xc][yc] - 1;
                        length = cycle + 1;
                        cycX = xc;
                        cycY = yc;
                        break;
                    } else if (lengths[xc][yc] > 0) {
                        length = lengths[xc][yc] + 1;
                        break;
                    } else {
                        lengths[xc][yc] = -1;
                        indices[xc][yc] = ++cycle;
                        stack.emplace(xc, yc);
                    }
                }
                bool isCycle = cycX != -1;
                int len = isCycle ? cycle : length;
                while (!stack.empty()) {
                    auto [xy_x, xy_y] = stack.top();
                    stack.pop();
                    lengths[xy_x][xy_y] = len;
                    if (isCycle) {
                        if (xy_x == cycX && xy_y == cycY) {
                            isCycle = false;
                            len = length;
                        }
                    } else {
                        ++len;
                    }
                }
                if (max_length < lengths[i][j]) {
                    max_length = lengths[i][j];
                    x = i + 1;
                    y = j + 1;
                }
            }
        }
    }
    io.out << x << " " << y << " " << max_length << "\n";
}

int main() {
    FastIOAdapter io;
    int count = io.nextInt();
    while (count-- > 0) {
        solve(io);
    }
    return 0;
}

