class D1620 {
public:
    static void main() {
        std::ios_base::sync_with_stdio(false);
        std::cin.tie(nullptr);

        int t;
        std::cin >> t;
        while (t--) {
            int n;
            std::cin >> n;
            std::vector<int> ar(n);
            for (int i = 0; i < n; ++i) {
                std::cin >> ar[i];
            }

            int ans = INT_MAX;
            for (int j = 0; j < 3; ++j) {
                for (int k = 0; k < 3; ++k) {
                    int mod3[10][2] = {{1, 0}};
                    for (int l = 1; l < 10; ++l) {
                        mod3[l][1] = INT_MAX;
                    }
                    for (int l = 0; l <= j; ++l) {
                        for (int m = 0; m <= k; ++m) {
                            mod3[l + m * 2][0] = 1;
                            mod3[l + m * 2][1] = std::min(l + m, mod3[l + m * 2][1]);
                        }
                    }

                    int mx = 0;
                    for (int l = 0; l < n; ++l) {
                        int mod = ar[l] % 3;
                        int mn = INT_MAX;
                        while (mod <= ar[l] && mod <= 9) {
                            if (mod3[mod][0] == 1) {
                                mn = std::min((ar[l] - mod) / 3, mn);
                            }
                            mod += 3;
                        }
                        mx = std::max(mx, mn);
                    }

                    if (mx != INT_MAX) {
                        ans = std::min(ans, mx + j + k);
                    }
                }
            }

            std::cout << ans << '\n';
        }
    }
};

int main() {
    D1620::main();
    return 0;
}

