std::vector<std::vector<int>> diana;
std::vector<std::vector<int>> mocha;

std::vector<int> cDiana;
std::vector<int> cMocha;

std::vector<bool> visD;
std::vector<bool> visM;

void dfs1(int i, int marker) {
    visM[i] = true;
    cMocha[i] = marker;

    for (int e : mocha[i]) {
        if (!visM[e]) {
            dfs1(e, marker);
        }
    }
}

void dfs2(int i, int marker) {
    visD[i] = true;
    cDiana[i] = marker;

    for (int e : diana[i]) {
        if (!visD[e]) {
            dfs2(e, marker);
        }
    }
}

int marker1(int n) {
    int count = 1;
    for (int i = 1; i <= n; ++i) {
        if (!visM[i]) {
            dfs1(i, count);
            ++count;
        }
    }
    return count - 1;
}

int marker2(int n) {
    int count = 1;
    for (int i = 1; i <= n; ++i) {
        if (!visD[i]) {
            dfs2(i, count);
            ++count;
        }
    }
    return count - 1;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, m1, m2;
    std::cin >> n >> m1 >> m2;

    diana.resize(n + 1);
    mocha.resize(n + 1);

    cMocha.assign(n + 1, 0);
    cDiana.assign(n + 1, 0);

    visD.assign(n + 1, false);
    visM.assign(n + 1, false);

    for (int i = 1; i <= n; ++i) {
        cMocha[i] = i;
        cDiana[i] = i;
    }

    for (int i = 0; i < m1; ++i) {
        int u, v;
        std::cin >> u >> v;
        mocha[u].push_back(v);
        mocha[v].push_back(u);
    }

    for (int i = 0; i < m2; ++i) {
        int u, v;
        std::cin >> u >> v;
        diana[u].push_back(v);
        diana[v].push_back(u);
    }

    int compsM = marker1(n);
    int compsD = marker2(n);

    int minComps = std::min(compsD, compsM);

    int ans = 0;

    std::vector<bool> connD(n + 1, false);
    std::vector<bool> connM(n + 1, false);

    for (int i = 1; i <= n && ans < minComps; ++i) {
        for (int j = i + 1; j <= n && ans < minComps; ++j) {
            if (cDiana[i] != cDiana[j] && cMocha[i] != cMocha[j]) {
                if (!(connD[cDiana[i]] && connD[cDiana[j]]) && !(connM[cMocha[i]] && connM[cMocha[j]])) {
                    connD[cDiana[i]] = true;
                    connD[cDiana[j]] = true;
                    connM[cMocha[i]] = true;
                    connM[cMocha[j]] = true;
                    std::cout << i << " " << j << "\n";
                    ++ans;
                }
            }
        }
    }

    return 0;
}

