class FastScanner {
private:
    stringstream ss;
    string token;

public:
    FastScanner() {
        ss.clear();
        ss.str("");
    }

    void readInput() {
        string line;
        while (getline(cin, line)) {
            ss << line << " ";
        }
    }

    string next() {
        if (ss >> token) {
            return token;
        }
        throw runtime_error("No more tokens");
    }

    int nextInt() {
        return stoi(next());
    }

    vector<int> readArray(int n) {
        vector<int> a(n);
        for (int i = 0; i < n; ++i) {
            a[i] = nextInt();
        }
        return a;
    }

    long long nextLong() {
        return stoll(next());
    }
};

long long gcd(long long a, long long b) {
    return (b == 0) ? a : gcd(b, a % b);
}

int gcd(int a, int b) {
    return (b == 0) ? a : gcd(b, a % b);
}

void sortr(vector<int>& a) {
    sort(a.begin(), a.end(), greater<int>());
}

void sort(vector<int>& a) {
    sort(a.begin(), a.end());
}

void sort(vector<long long>& a) {
    sort(a.begin(), a.end());
}

int main() {
    FastScanner s;
    s.readInput();
    int t = s.nextInt();
    while (t-- > 0) {
        string g = s.next();
        if (g.back() == '0') g += '1';
        else g += '0';
        vector<char> a(g.begin(), g.end());
        long long ans = 0;
        for (size_t i = 1; i < a.size(); ++i) {
            if (a[i] == a[i - 1]) continue;
            else {
                if (a[i - 1] == '0') ans++;
            }
        }
        if (ans == 0) {
