const long mod = 998244353;

std::vector<long> fact;
std::vector<long> invFact;

long binPow(long a, long b) {
    long res = 1;
    while (b > 0) {
        a = a % mod;
        if (b & 1) {
            res = (res * a) % mod;
        }
        b >>= 1;
        a = (a * a) % mod;
    }
    return res;
}

long modInverse(long a) {
    return binPow(a, mod - 2);
}

long mul(long a, long b) {
    return (a * b) % mod;
}

long nCr(int n, int r) {
    long res = mul(fact[n], invFact[r]);
    res = mul(res, invFact[n - r]);
    return res;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<std::string> ls(n);
    bool full = false;
    int black = 0, white = 0;
    for (int i = 0; i < n; ++i) {
        std::cin >> ls[i];
        if (ls[i][0] == 'W') white++;
        if (ls[i][0] == 'B') black++;
        if (ls[i][1] == 'W') white++;
        if (ls[i][1] == 'B') black++;
        if (ls[i][0] != '?' && ls[i][0] == ls[i][1]) {
            full = true;
        }
    }
    if (black > n || white > n) {
        std::cout << 0 << std::endl;
        return 0;
    }

    fact.resize(2 * n + 1);
    invFact.resize(2 * n + 1);
    fact[0] = 1;
    invFact[0] = 1;
    for (int i = 1; i <= 2 * n; ++i) {
        fact[i] = mul(fact[i - 1], i);
        invFact[i] = modInverse(fact[i]);
    }
    int empty = 2 * n - black - white;
    long ans = nCr(empty, n - black);
    if (full) {
        std::cout << ans << std::endl;
        return 0;
    }
    long invalid = 1;
    bool WB = true, BW = true;
    for (int i = 0; i < n; ++i) {
        if (ls[i][0] == '?' && ls[i][1] == '?') {
            invalid = mul(invalid, 2);
        }
        if (ls[i][0] == 'B' || ls[i][1] == 'W') {
            WB = false;
        }
        if (ls[i][0] == 'W' || ls[i][1] == 'B') {
            BW = false;
        }
    }
    if (WB) invalid--;
    if (BW) invalid--;
    ans = (ans - invalid + mod) % mod;
    std::cout << ans << std::endl;
    return 0;
}

#include <iostream>
#include <sstream>
#include <vector>
#include <string>

class FastReader {
private:
    std::istream& stream;
    std::istringstream buffer;
    std::string line;
    std::string token;

public:
    FastReader(std::istream& in = std::cin) : stream(in) {}

    std::string next() {
        if (!buffer.eof()) {
            buffer >> token;
            if (!buffer.fail()) return token;
        }
        while (std::getline(stream, line)) {
            buffer.clear();
            buffer.str(line);
            buffer >> token;
            if (!buffer.fail()) return token;
        }
        throw std::runtime_error("No more tokens");
    }

    int nextInt() {
        return std::stoi(next());
    }

    long long nextLong() {
        return std::stoll(next());
    }

    double nextDouble() {
        return std::stod(next());
    }

    std::string nextLine() {
        std::getline(stream, line);
        return line;
    }

    std::vector<int> readInt(int size) {
        std::vector<int> arr(size);
        for (int i = 0; i < size; ++i) {
            arr[i] = nextInt();
        }
        return arr;
    }

    std::vector<long long> readLong(int size) {
        std::vector<long long> arr(size);
        for (int i = 0; i < size; ++i) {
            arr[i] = nextLong();
        }
        return arr;
    }

    std::vector<std::vector<int>> read2dArray(int rows, int cols) {
        std::vector<std::vector<int>> arr(rows, std::vector<int>(cols));
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                arr[i][j] = nextInt();
            }
        }
        return arr;
    }
};

int main() {
    FastReader in;

    int T = in.nextInt();
    while (T-- > 0) {
        int n = in.nextInt();
        std::vector<int> a = in.readInt(n);

        int ans = a[0];
        for (int i : a) ans &= i;
        std::cout << ans << std::endl;
    }

    return 0;
}

