class Point {
public:
    int x;
    int y;

    Point(int a, int b) : x(a), y(b) {}
};

int gcd(int a, int b) {
    if (a > b)
        std::swap(a, b);
    if (a == 0)
        return b;
    return gcd(b % a, a);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    int N;
    iss >> N;

    std::vector<Point> arr;
    arr.reserve(N);
    for (int i = 0; i < N; ++i) {
        std::getline(std::cin, line);
        std::istringstream iss2(line);
        int x, y;
        iss2 >> x >> y;
        x /= 2;
        y /= 2;
        arr.emplace_back(x, y);
    }

    long long res = 0LL;
    for (int centerr = 0; centerr < N; ++centerr) {
        const Point& c = arr[centerr];
        long long freq[2][2][2] = {};

        for (int i = centerr + 1; i < N; ++i) {
            if (i != centerr) {
                const Point& p = arr[i];
                int t1 = 1;
                if (p.x % 2 != c.x % 2)
                    t1 = 0;
                if (p.y % 2 != c.y % 2)
                    t1 = 0;

                int t2 = (p.x & 1);
                int t3 = (p.y & 1);

                freq[t1 ^ 1][t2][t3]++;
            }
        }

        long long temp = freq[0][0][0] * (freq[1][0][1] + freq[1][1][0] + freq[1][1][1]);

        temp += freq[0][0][0] * (freq[0][0][0] - 1) / 2;
        temp += freq[1][0][0] * (freq[1][0][0] - 1) / 2;

        temp += freq[0][0][1] * (freq[1][0][0] + freq[1][1][0] + freq[1][1][1]);

        temp += freq[0][0][1] * (freq[0][0][1] - 1) / 2;
        temp += freq[1][0][1] * (freq[1][0][1] - 1) / 2;

        temp += freq[0][1][0] * (freq[1][0][0] + freq[1][0][1] + freq[1][1][1]);

        temp += freq[0][1][0] * (freq[0][1][0] - 1) / 2;
        temp += freq[1][1][0] * (freq[1][1][0] - 1) / 2;

        temp += freq[0][1][1] * (freq[1][0][0] + freq[1][0][1] + freq[1][1][0]);

        temp += freq[0][1][1] * (freq[0][1][1] - 1) / 2;
        temp += freq[1][1][1] * (freq[1][1][1] - 1) / 2;

        res += temp;
    }

    std::cout << res << std::endl;
    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

class MyScanner {
private:
    std::istream& in;
    std::istringstream buffer;
    std::string line;
    bool hasMoreTokens;

public:
    MyScanner(std::istream& input = std::cin) : in(input), hasMoreTokens(false) {}

    std::string next() {
        if (!hasMoreTokens) {
            if (!std::getline(in, line)) {
                throw std::runtime_error("No more tokens");
            }
            buffer.clear();
            buffer.str(line);
            hasMoreTokens = true;
        }
        std::string token;
        buffer >> token;
        hasMoreTokens = !buffer.eof();
        return token;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long nextLong() {
        return std::stol(next());
    }

    double nextDouble() {
        return std::stod(next());
    }

    std::string nextLine() {
        if (hasMoreTokens) {
            std::string remaining = buffer.str().substr(buffer.tellg());
            hasMoreTokens = false;
            return remaining;
        }
        std::getline(in, line);
        return line;
    }
};

int N;
MyScanner sc;

void solve() {
    int n = sc.nextInt();
    int m = sc.nextInt();
    int k = sc.nextInt();

    int b_t = n % m;
    int b_p = n / m + 1;
    int next_b = 1;
    int next_s = 1;
    if (b_t == 0) {
        for (int i = 0; i < k; ++i) {
            for (int j = 0; j < m; ++j) {
                std::cout << (n / m) << " ";
                for (int play = 0; play < n / m; ++play) {
                    std::cout << next_b << " ";
                    next_b = next_b == n ? 1 : next_b + 1;
                }
                std::cout << std::endl;
            }
        }
    } else {
        for (int i = 0; i < k; ++i) {
            for (int j = 0; j < b_t; ++j) {
                std::cout << (n / m + 1) << " ";
                for (int play = 0; play < b_p; ++play) {
                    std::cout << next_b << " ";
                    next_b = next_b == n ? 1 : next_b + 1;
                }
                std::cout << std::endl;
