class Main {
    let out = FileHandle.standardOutput
    let inStream = FileHandle.standardInput
    var buffer = Data()
    var tokenizer: [String] = []

    func next() throws -> String {
        if !tokenizer.isEmpty {
            return tokenizer.removeFirst()
        }
        buffer.append(inStream.availableData)
        while let range = buffer.range(of: "\n".data(using: .utf8)!, options: [], in: buffer.startIndex..<buffer.endIndex) {
            let line = String(data: buffer.subdata(in: buffer.startIndex..<range.lowerBound), encoding: .utf8)!
            tokenizer = line.split(separator: " ").map { String($0) }
            buffer.removeSubrange(buffer.startIndex...range.upperBound)
            if !tokenizer.isEmpty {
                return tokenizer.removeFirst()
            }
        }
        throw NSError(domain: "End of input", code: 0, userInfo: nil)
    }

    func ni() throws -> Int {
        return Int(next())!
    }

    func nl() throws -> Int64 {
        return Int64(next())!
    }

    func na(_ n: Int) throws -> [Int] {
        var A = [Int]()
        for _ in 0..<n {
            A.append(try ni())
        }
        return A
    }

    let mod: Int64 = 998244353

    func solve() throws {
        let tc = try ni()
        for _ in 0..<tc {
            let n = try ni()
            let A = try na(n)

            var D = Array(repeating: Array(repeating: Int64(0), count: 3), count: n + 1)

            for i in stride(from: n - 1, through: 0, by: -1) {
                let u = A[i]
                let zero = 1 + D[u][0] + (u + 1 <= n ? D[u + 1][0] : 0) + (u + 2 <= n ? D[u + 2][1] : 0)
                let one = 1 + D[u][1] + (u > 1 ? D[u - 2][2] : 0)
                let two = 1 + D[u][2] + (u + 2 <= n ? D[u + 2][1] : 0)

                D[u][0] = (D[u][0] + zero) % mod
                D[u][1] = (D[u][1] + one) % mod
                D[u][2] = (D[u][2] + two) % mod
            }

            let ans = (D[0][0] + D[1][1]) % mod
            out.write("\(ans)\n".data(using: .utf8)!)
        }
    }

    func dc(_ a: Int64) -> Int {
        var r = 0
        var a = a
        while a > 0 {
            r += 1
            a /= 10
        }
        return r
    }

    func gcd(_ a: Int, _ b: Int) -> Int {
        return b == 0 ? a : gcd(b, a % b)
    }

    func gcd(_ a: Int64, _ b: Int64) -> Int64 {
        return b == 0 ? a : gcd(b, a % b)
    }

    func mp(_ a: Int64, _ p: Int64) -> Int64 {
        var r: Int64 = 1
        var a = a
        var p = p
        while p > 0 {
            if p & 1 == 1 {
                r = (r * a) % mod
            }
            p >>= 1
            a = (a * a) % mod
        }
        return r
    }
}

