class CF1556E {
    private let INF: Int64 = 0x3f3f3f3f3f3f3f3f
    private var aa: [Int64] = []
    private var tmax: [Int64] = []
    private var tmin: [Int64] = []
    private var n: Int = 0

    init() {}

    func build() {
        tmax = Array(repeating: 0, count: n * 2)
        tmin = Array(repeating: 0, count: n * 2)
        for i in 0..<n {
            tmax[n + i] = aa[i]
            tmin[n + i] = aa[i]
        }
        for i in stride(from: n - 1, through: 1, by: -1) {
            tmax[i] = max(tmax[i << 1], tmax[(i << 1) | 1])
            tmin[i] = min(tmin[i << 1], tmin[(i << 1) | 1])
        }
    }

    func qmax(_ l: Int, _ r: Int) -> Int64 {
        var ans: Int64 = -INF
        var l = l + n
        var r = r + n
        while l <= r {
            if (l & 1) == 1 {
                ans = max(ans, tmax[l])
                l += 1
            }
            if (r & 1) == 0 {
                ans = max(ans, tmax[r])
                r -= 1
            }
            l >>= 1
            r >>= 1
        }
        return ans
    }

    func qmin(_ l: Int, _ r: Int) -> Int64 {
        var ans: Int64 = INF
        var l = l + n
        var r = r + n
        while l <= r {
            if (l & 1) == 1 {
                ans = min(ans, tmin[l])
                l += 1
            }
            if (r & 1) == 0 {
                ans = min(ans, tmin[r])
                r -= 1
            }
            l >>= 1
            r >>= 1
        }
        return ans
    }

    func main() {
        let input = readLine()!.split(separator: " ").map { Int($0)! }
        n = input[0]
        let q = input[1]
        aa = Array(repeating: 0, count: n)
        for i in 0..<n {
            aa[i] -= Int64(readLine()!.split(separator: " ")[0])!
        }
        for i in 0..<n {
            aa[i] += Int64(readLine()!.split(separator: " ")[0])!
        }
        for i in 1..<n {
            aa[i] += aa[i - 1]
        }
        build()
        for _ in 0..<q {
            let query = readLine()!.split(separator: " ").map { Int($0)! }
            let l = query[0] - 1
            let r = query[1] - 1
            let a = l == 0 ? 0 : aa[l - 1]
            let b = aa[r]
            if a != b || qmin(l, r) != a {
                print(-1)
            } else {
                print(qmax(l, r) - a)
            }
        }
    }
}

