class FastIOAdapter {
    private let inputHandle: FileHandle
    private var buffer: Data
    private let outputHandle: FileHandle

    init() {
        self.inputHandle = FileHandle.standardInput
        self.buffer = Data()
        self.outputHandle = FileHandle.standardOutput
    }

    func next() -> String? {
        while !buffer.contains(where: { $0.isWhitespace }) && !buffer.isEmpty {
            let data = inputHandle.availableData
            buffer.append(data)
        }
        guard let endIndex = buffer.firstIndex(of: UInt8(ascii: " ")) ?? buffer.firstIndex(of: UInt8(ascii: "\n")) else {
            return nil
        }
        let token = String(data: buffer.prefix(upTo: endIndex), encoding: .utf8)
        buffer.removeSubrange(...endIndex)
        return token
    }

    func nextInt() -> Int {
        Int(next()!)!
    }

    func readArray(_ n: Int) -> [Int] {
        (0..<n).map { _ in nextInt() }
    }

    func print(_ items: Any..., separator: String = " ", terminator: String = "\n") {
        let strings = items.map { String(describing: $0) }
        outputHandle.write((strings.joined(separator: separator) + terminator).data(using: .utf8)!)
    }

    func close() {
        outputHandle.closeFile()
    }
}

func solve(_ io: FastIOAdapter) {
    let n = io.nextInt()
    let m = io.nextInt()
    var a = [[Character]](repeating: [], count: n)
    for i in 0..<n {
        if let line = readLine() {
            a[i] = Array(line)
        }
    }
    var lengths = Array(repeating: Array(repeating: 0, count: m), count: n)
    var indices = Array(repeating: Array(repeating: 0, count: m), count: n)
    var x = 0, y = 0
    var maxLen = 0

    for i in 0..<n {
        for j in 0..<m {
            if lengths[i][j] == 0 {
                var stack: [(Int, Int)] = [(i, j)]
                lengths[i][j] = -1
                indices[i][j] = 0
                var length = 1
                var cycle = 0
                var cycX = -1, cycY = -1

                while true {
                    let (xc, yc) = stack.last!
                    var newXc = xc, newYc = yc
                    switch a[xc][yc] {
                    case "U": newXc -= 1
                    case "D": newXc += 1
                    case "L": newYc -= 1
                    default: newYc += 1
                    }
                    if newXc < 0 || newXc >= n || newYc < 0 || newYc >= m {
                        break
                    } else if lengths[newXc][newYc] < 0 {
                        cycle -= indices[newXc][newYc] - 1
                        length = cycle + 1
                        cycX = newXc
                        cycY = newYc
                        break
                    } else if lengths[newXc][newYc] > 0 {
                        length = lengths[newXc][newYc] + 1
                        break
                    } else {
                        lengths[newXc][newYc] = -1
                        indices[newXc][newYc] = cycle + 1
                        stack.append((newXc, newYc))
                    }
                }

                var isCycle = cycX != -1
                var len = isCycle ? cycle : length
                while !stack.isEmpty {
                    let (xyX, xyY) = stack.removeLast()
                    lengths[xyX][xyY] = len
                    if isCycle {
                        if xyX == cycX && xyY == cycY {
                            isCycle = false
                            len = length
                        }
                    } else {
                        len += 1
                    }
                }

                if maxLen < lengths[i][j] {
                    maxLen = lengths[i][j]
                    x = i + 1
                    y = j + 1
                }
            }
        }
    }
    io.print(x, y, maxLen)
}

func main() {
    let io = FastIOAdapter()
    var count = io.nextInt()
    while count > 0 {
        solve(io)
        count -= 1
    }
    io.close()
}

