                count += 1
            }
        }
        return count - 1
    }

    static func marker2(_ n: Int) -> Int {
        var count = 1
        for i in 1...n {
            if !visD[i] {
                dfs2(i, count)
                count += 1
            }
        }
        return count - 1
    }
