import Foundation

let mod: Int64 = 998244353

func binPow(_ a: Int64, _ b: Int) -> Int64 {
    var res: Int64 = 1
    var a = a % mod
    var b = b

    while b > 0 {
        if b & 1 == 1 {
            res = (res * a) % mod
        }
        b >>= 1
        a = (a * a) % mod
    }

    return res
}

func modInverse(_ a: Int64) -> Int64 {
    return binPow(a, Int(mod - 2))
}

func mul(_ a: Int64, _ b: Int64) -> Int64 {
    return (a * b) % mod
}

var fact: [Int64] = []
var invFact: [Int64] = []

func nCr(_ n: Int, _ r: Int) -> Int64 {
    let res = mul(fact[n], invFact[r])
    return mul(res, invFact[n - r])
}

func main() {
    guard let n = readLine()?.components(separatedBy: .whitespaces).compactMap({ Int($0) }).first else { return }

    var ls: [String] = []
    var black = 0
    var white = 0

    for _ in 0..<n {
        if let line = readLine() {
            ls.append(line)
            if line.first == "W" { white += 1 }
            if line.first == "B" { black += 1 }
            if line.dropFirst().first == "W" { white += 1 }
            if line.dropFirst().first == "B" { black += 1 }
        }
    }

    if black > n || white > n {
        print(0)
        return
    }

    fact = Array(repeating: 0, count: 2 * n + 1)
    invFact = Array(repeating: 0, count: 2 * n + 1)
    fact[0] = 1
    invFact[0] = 1

    for i in 1...2 * n {
        fact[i] = mul(fact[i - 1], Int64(i))
        invFact[i] = modInverse(fact[i])
    }

    let empty = 2 * n - black - white
    var ans = nCr(empty, n - black)

    var full = false
    for line in ls {
        if line.first != "?" && line.first == line.dropFirst().first {
            full = true
            break
        }
    }

    if full {
        print(ans)
        return
    }

    var invalid: Int64 = 1
    var WB = true
    var BW = true

    for line in ls {
        if line.first == "?" && line.dropFirst().first == "?" {
            invalid = mul(invalid, 2)
        }
        if line.first == "B" || line.dropFirst().first == "W" {
            WB = false
        }
        if line.first == "W" || line.dropFirst().first == "B" {
            BW = false
        }
    }

    if WB { invalid -= 1 }
    if BW { invalid -= 1 }

    ans -= invalid
    print(ans)
}

