class Point {
    var x: Int
    var y: Int

    init(_ a: Int, _ b: Int) {
        x = a
        y = b
    }
}

func gcd(_ a: Int, _ b: Int) -> Int {
    var a = a
    var b = b
    if a > b {
        let temp = a
        a = b
        b = temp
    }
    if a == 0 {
        return b
    }
    return gcd(b % a, a)
}

func main() {
    guard let firstLine = readLine(), let N = Int(firstLine) else { return }

    var arr: [Point] = []
    for _ in 0..<N {
        if let line = readLine(), let parts = line.split(separator: " ").compactMap({ Int($0) }), parts.count == 2 {
            let x = parts[0] / 2
            let y = parts[1] / 2
            arr.append(Point(x, y))
        }
    }

    var res: Int64 = 0

    for centerr in 0..<N {
        let c = arr[centerr]
        var freq = [[[Int]]](repeating: [[Int]](repeating: [Int](repeating: 0, count: 2), count: 2), count: 2)

        for i in centerr+1..<N {
            let p = arr[i]
            var t1 = 1
            if p.x % 2 != c.x % 2 {
                t1 = 0
            }
            if p.y % 2 != c.y % 2 {
                t1 = 0
            }
            let t2 = p.x & 1
            let t3 = p.y & 1
            freq[t1 ^ 1][t2][t3] += 1
        }

        var temp: Int64 = 0

        temp += Int64(freq[0][0][0]) * Int64(freq[1][0][1] + freq[1][1][0] + freq[1][1][1])

        temp += Int64(freq[0][0][0]) * (Int64(freq[0][0][0]) - 1) / 2

        temp += Int64(freq[1][0][0]) * (Int64(freq[1][0][0]) - 1) / 2

        temp += Int64(freq[0][0][1]) * Int64(freq[1][0][0] + freq[1][1][0] + freq[1][1][1])

        temp += Int64(freq[0][0][1]) * (Int64(freq[0][0][1]) - 1) / 2

        temp += Int64(freq[1][0][1]) * (Int64(freq[1][0][1]) - 1) / 2

        temp += Int64(freq[0][1][0]) * Int64(freq[1][0][0] + freq[1][0][1] + freq[1][1][1])

        temp += Int64(freq[0][1][0]) * (Int64(freq[0][1][0]) - 1) / 2

        temp += Int64(freq[1][1][0]) * (Int64(freq[1][1][0]) - 1) / 2

        temp += Int64(freq[0][1][1]) * Int64(freq[1][0][0] + freq[1][0][1] + freq[1][1][0])

        temp += Int64(freq[0][1][1]) * (Int64(freq[0][1][1]) - 1) / 2

        temp += Int64(freq[1][1][1]) * (Int64(freq[1][1][1]) - 1) / 2

        res += temp
    }

    print(res)
}

